  "lib/pages/music/music_player.dart": "import 'dart:async';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\n\nclass MusicPlayer extends StatefulWidget {\n  final List<String> tracks;\n  final String audioPath;\n  final bool isDesktop;\n\n  const MusicPlayer({\n    super.key,\n    required this.tracks,\n    required this.audioPath,\n    this.isDesktop = true,\n  });\n\n  @override\n  State<MusicPlayer> createState() => _MusicPlayerState();\n}\n\nclass _MusicPlayerState extends State<MusicPlayer> {\n  late AudioPlayer _audioPlayer;\n  int _currentTrackIndex = 0;\n  bool _isPlaying = false;\n  Duration _duration = Duration.zero;\n  Duration _position = Duration.zero;\n\n  StreamSubscription? _durationSubscription;\n  StreamSubscription? _positionSubscription;\n  StreamSubscription? _playerCompleteSubscription;\n  StreamSubscription? _playerStateSubscription;\n\n  @override\n  void initState() {\n    super.initState();\n    _audioPlayer = AudioPlayer();\n    _setupAudioListeners();\n  }\n\n  void _setupAudioListeners() {\n    _durationSubscription = _audioPlayer.onDurationChanged.listen((d) {\n      setState(() => _duration = d);\n    });\n\n    _positionSubscription = _audioPlayer.onPositionChanged.listen((p) {\n      setState(() => _position = p);\n    });\n\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((event) {\n      _next();\n    });\n\n    _playerStateSubscription = _audioPlayer.onPlayerStateChanged.listen((\n      state,\n    ) {\n      setState(() {\n        _isPlaying = state == PlayerState.playing;\n      });\n    });\n  }\n\n  @override\n  void dispose() {\n    _durationSubscription?.cancel();\n    _positionSubscription?.cancel();\n    _playerCompleteSubscription?.cancel();\n    _playerStateSubscription?.cancel();\n    _audioPlayer.dispose();\n    super.dispose();\n  }\n\n  Future<void> _playPause() async {\n    if (_isPlaying) {\n      await _audioPlayer.pause();\n    } else {\n      if (_position == Duration.zero) {\n        await _playTrack();\n      } else {\n        await _audioPlayer.resume();\n      }\n    }\n  }\n\n  Future<void> _playTrack() async {\n    final track = widget.tracks[_currentTrackIndex];\n    final fullPath = '\${widget.audioPath}\$track';\n    await _audioPlayer.play(AssetSource(fullPath));\n  }\n\n  Future<void> _next() async {\n    setState(() {\n      _currentTrackIndex = (_currentTrackIndex + 1) % widget.tracks.length;\n    });\n    await _playTrack();\n  }\n\n  Future<void> _previous() async {\n    setState(() {\n      _currentTrackIndex =\n          (_currentTrackIndex - 1 + widget.tracks.length) %\n          widget.tracks.length;\n    });\n    await _playTrack();\n  }\n\n  String _formatDuration(Duration duration) {\n    String twoDigits(int n) => n.toString().padLeft(2, \"0\");\n    String twoDigitMinutes = twoDigits(duration.inMinutes.remainder(60));\n    String twoDigitSeconds = twoDigits(duration.inSeconds.remainder(60));\n    return \"\$twoDigitMinutes:\$twoDigitSeconds\";\n  }\n\n  String _cleanTrackName(String name) {\n    return name.replaceAll('.wav', '').replaceAll('.m4a', '');\n  }\n\n  Widget _buildTextButton(\n    String label,\n    VoidCallback onTap, {\n    bool isPrimary = false,\n  }) {\n    return InkWell(\n      onTap: onTap,\n      borderRadius: BorderRadius.circular(4),\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 4.0),\n        child: Text(\n          label,\n          style: TextStyle(\n            color: Colors.white70,\n            fontFamily: 'JetBrainsMono',\n            fontSize: 13,\n            fontWeight: isPrimary ? FontWeight.bold : FontWeight.normal,\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildTerminalHeader(Color accentColor) {\n    return Row(\n      children: [\n        Text(\n          '~ > ',\n          style: TextStyle(\n            color: accentColor,\n            fontFamily: 'JetBrainsMono',\n            fontSize: 14,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        Expanded(\n          child: Text(\n            './\${_cleanTrackName(widget.tracks[_currentTrackIndex]).replaceAll(' ', '_')}.sh',\n            style: const TextStyle(\n              color: Colors.white,\n              fontFamily: 'JetBrainsMono',\n              fontSize: 14,\n            ),\n            overflow: TextOverflow.ellipsis,\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildControlsRow(Color accentColor) {\n    return Row(\n      children: [\n        _buildTextButton(\n          _isPlaying ? '[ PAUSE ]' : '[ PLAY ]',\n          _playPause,\n          isPrimary: true,\n        ),\n        const SizedBox(width: 8),\n        _buildTextButton('[ BACK ]', _previous),\n        const SizedBox(width: 4),\n        _buildTextButton('[ NEXT ]', _next),\n        const SizedBox(width: 16),\n        Expanded(\n          child: SliderTheme(\n            data: SliderThemeData(\n              trackHeight: 1,\n              activeTrackColor: accentColor,\n              inactiveTrackColor: Colors.white.withOpacity(0.1),\n              thumbColor: accentColor,\n              thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 4),\n              overlayShape: const RoundSliderOverlayShape(overlayRadius: 10),\n            ),\n            child: Slider(\n              value: _position.inMilliseconds.toDouble(),\n              max: _duration.inMilliseconds.toDouble() > 0\n                  ? _duration.inMilliseconds.toDouble()\n                  : 1.0,\n              onChanged: (value) {\n                _audioPlayer.seek(Duration(milliseconds: value.toInt()));\n              },\n            ),\n          ),\n        ),\n        const SizedBox(width: 12),\n        Text(\n          '\${_formatDuration(_position)} / \${_formatDuration(_duration)}',\n          style: TextStyle(\n            color: Colors.white.withOpacity(0.5),\n            fontFamily: 'JetBrainsMono',\n            fontSize: 12,\n          ),\n        ),\n      ],\n    );\n  }\n\n  Widget _buildTracklist(Color accentColor) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          '// AVAILABLE_TRACKS',\n          style: TextStyle(\n            color: Colors.white.withOpacity(0.3),\n            fontFamily: 'JetBrainsMono',\n            fontSize: 11,\n            fontWeight: FontWeight.bold,\n            letterSpacing: 1.1,\n          ),\n        ),\n        const SizedBox(height: 12),\n        ...widget.tracks.asMap().entries.map((entry) {\n          final int index = entry.key;\n          final String track = entry.value;\n          final bool isCurrent = index == _currentTrackIndex;\n\n          return InkWell(\n            onTap: () {\n              setState(() => _currentTrackIndex = index);\n              _playTrack();\n            },\n            hoverColor: accentColor.withOpacity(0.05),\n            child: Padding(\n              padding: const EdgeInsets.symmetric(\n                vertical: 6.0,\n                horizontal: 4.0,\n              ),\n              child: Row(\n                children: [\n                  SizedBox(\n                    width: 24,\n                    child: Text(\n                      isCurrent ? '->' : '  ',\n                      style: TextStyle(\n                        color: accentColor,\n                        fontFamily: 'JetBrainsMono',\n                        fontWeight: FontWeight.bold,\n                      ),\n                    ),\n                  ),\n                  Text(\n                    _cleanTrackName(track).toLowerCase(),\n                    style: TextStyle(\n                      color: isCurrent\n                          ? accentColor\n                          : Colors.white.withOpacity(0.7),\n                      fontFamily: 'JetBrainsMono',\n                      fontSize: 13,\n                      decoration: isCurrent ? TextDecoration.none : null,\n                    ),\n                  ),\n                  if (isCurrent && _isPlaying) ...[\n                    const SizedBox(width: 12),\n                    _buildPlayingIndicator(accentColor),\n                  ],\n                ],\n              ),\n            ),\n          );\n        }).toList(),\n      ],\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final Color accentColor = kAccentColor;\n\n    return Container(\n      margin: const EdgeInsets.symmetric(vertical: 24),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          _buildTerminalHeader(accentColor),\n          const SizedBox(height: 16),\n          _buildControlsRow(accentColor),\n          const SizedBox(height: 32),\n          _buildTracklist(accentColor),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildPlayingIndicator(Color color) {\n    return SizedBox(\n      height: 10,\n      width: 12,\n      child: Row(\n        mainAxisAlignment: MainAxisAlignment.spaceBetween,\n        children: List.generate(\n          3,\n          (i) => _PlayingBar(color: color, delay: i * 200),\n        ),\n      ),\n    );\n  }\n}\n\nclass _PlayingBar extends StatefulWidget {\n  final Color color;\n  final int delay;\n  const _PlayingBar({required this.color, required this.delay});\n\n  @override\n  State<_PlayingBar> createState() => _PlayingBarState();\n}\n\nclass _PlayingBarState extends State<_PlayingBar>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 600),\n    );\n    Future.delayed(Duration(milliseconds: widget.delay), () {\n      if (mounted) _controller.repeat(reverse: true);\n    });\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        return Container(\n          width: 2,\n          height: 3 + (7 * _controller.value),\n          color: widget.color,\n        );\n      },\n    );\n  }\n}\n",
  "lib/pages/music/album_item.dart": "class AlbumItem {\n  final String title;\n  final String coverUrl;\n  final String spotifyUrl;\n  final String appleMusicUrl;\n  final String soundCloudUrl; \n  final String youtubeUrl;\n  final bool soundCloudOnly;    \n  final String lyrics;        \n  final List<String> tracks;\n  final String audioPath;\n  final bool isLocked;\n\n  const AlbumItem({\n    required this.title,\n    required this.coverUrl,\n    required this.spotifyUrl,\n    required this.appleMusicUrl,\n    required this.soundCloudUrl,\n    required this.youtubeUrl,\n    required this.lyrics,\n    required this.soundCloudOnly,\n    required this.tracks,\n    required this.audioPath,\n    this.isLocked = false,\n  });\n}\n",
  "lib/pages/music/music_page.dart": "import 'package:archbtw_sh/pages/music/album_grid_item.dart';\nimport 'package:archbtw_sh/pages/music/album_item_list.dart';\nimport 'package:flutter/material.dart';\n\nclass MusicPage extends StatelessWidget {\n  const MusicPage({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: GridView.builder(\n        padding: const EdgeInsets.all(16.0),\n        gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(\n          maxCrossAxisExtent: 250.0,\n          crossAxisSpacing: 16.0,\n          mainAxisSpacing: 16.0,\n          childAspectRatio: 0.80,\n        ),\n        itemCount: albumItems.length,\n        itemBuilder: (context, index) {\n          return AlbumGridItem(item: albumItems[index]);\n        },\n      ),\n    );\n  }\n}\n",
  "lib/pages/music/album_social_icon.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/helpers.dart';\nimport 'package:flutter/material.dart';\n\nclass AlbumSocialIcon extends StatelessWidget {\n  final IconData icon;\n  final String url;\n  final double size;\n\n  const AlbumSocialIcon({super.key, \n    required this.icon,\n    required this.url,\n    this.size = 18.0,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return IconButton(\n      icon: Icon(icon, color: Colors.grey, size: size),\n      onPressed: () => openUrl(url),\n      splashColor: kAccentColor.withOpacity(0.3),\n      hoverColor: kAccentColor.withOpacity(0.1),\n    );\n  }\n}",
  "lib/pages/music/album_details.dart": "import 'package:archbtw_sh/games/blubber_game.dart';\nimport 'package:archbtw_sh/pages/music/music_player.dart';\nimport 'package:archbtw_sh/games/lemon_game.dart';\nimport 'package:archbtw_sh/games/santa_game.dart';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/music/album_item.dart';\nimport 'package:archbtw_sh/pages/overheat/overheat_page.dart';\nimport 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass AlbumDetails extends StatefulWidget {\n  final AlbumItem item;\n  final bool isDesktop;\n  final bool showTitle;\n  final bool showPlayer;\n  final bool showLyricsButton;\n  final bool showLyricsContent;\n  final bool? isLyricsExpanded;\n  final VoidCallback? onToggleLyrics;\n\n  const AlbumDetails({\n    super.key,\n    required this.item,\n    required this.isDesktop,\n    this.showTitle = true,\n    this.showPlayer = true,\n    this.showLyricsButton = false,\n    this.showLyricsContent = true,\n    this.isLyricsExpanded,\n    this.onToggleLyrics,\n  });\n\n  @override\n  State<AlbumDetails> createState() => _AlbumDetailsState();\n}\n\nclass _AlbumDetailsState extends State<AlbumDetails> {\n  bool _internalExpanded = false;\n\n  bool get _isExpanded => widget.isLyricsExpanded ?? _internalExpanded;\n\n  void _handleToggle() {\n    if (widget.onToggleLyrics != null) {\n      widget.onToggleLyrics!();\n    } else {\n      setState(() {\n        _internalExpanded = !_internalExpanded;\n      });\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final double iconSize = widget.isDesktop ? 22 : 18;\n\n    return Column(\n      crossAxisAlignment: widget.isDesktop && widget.showTitle\n          ? CrossAxisAlignment.center\n          : CrossAxisAlignment.start,\n      children: [\n        if (widget.showTitle)\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 12),\n            child: Row(\n              mainAxisAlignment: widget.isDesktop\n                  ? MainAxisAlignment.center\n                  : MainAxisAlignment.start,\n              children: [\n                Text(\n                  widget.item.title,\n                  style: TextStyle(\n                    color: kTextColor,\n                    fontWeight: FontWeight.bold,\n                    fontSize: 24,\n                    fontFamily: 'JetBrainsMono',\n                  ),\n                ),\n                if (!widget.isDesktop) Expanded(child: const SizedBox()),\n                if (widget.item.isLocked) ...[\n                  const SizedBox(width: 16),\n                  Container(\n                    width: 1,\n                    height: 20,\n                    color: Colors.grey.withValues(alpha: 0.5),\n                  ),\n                  const SizedBox(width: 16),\n                  IconButton(\n                    tooltip: \"launch_protocol: overheat\",\n                    icon: FaIcon(\n                      FontAwesomeIcons.fire,\n                      color: const Color(0xFFFF6F00),\n                      size: iconSize,\n                    ),\n                    onPressed: () {\n                      Navigator.of(context).push(\n                        PageRouteBuilder(\n                          opaque: false,\n                          pageBuilder: (context, anim, secAnim) =>\n                              const OverheatPage(),\n                          transitionsBuilder: (context, anim, secAnim, child) {\n                            return FadeTransition(opacity: anim, child: child);\n                          },\n                        ),\n                      );\n                    },\n                  ),\n                ] else if (widget.item.title.toLowerCase() == 'blubber' ||\n                    widget.item.title.toLowerCase() == 'santa\\'s cookies' ||\n                    widget.item.title.toLowerCase() == 'life\\'s lemons') ...[\n                  const SizedBox(width: 16),\n                  Container(\n                    width: 1,\n                    height: 20,\n                    color: Colors.grey.withValues(alpha: 0.5),\n                  ),\n                  const SizedBox(width: 16),\n                  IconButton(\n                    tooltip: _getTooltipForAlbum(widget.item.title),\n                    icon: Icon(\n                      Icons.terminal,\n                      color: kAccentColor,\n                      size: iconSize,\n                    ),\n                    onPressed: () {\n                      Widget gamePage;\n                      final title = widget.item.title.toLowerCase();\n\n                      if (title == 'blubber') {\n                        gamePage = WhaleGame();\n                      } else if (title == 'santa\\'s cookies') {\n                        gamePage = const SantasInvadersGame();\n                      } else {\n                        gamePage = const LemonsGame();\n                      }\n\n                      Navigator.of(context).push(\n                        PageRouteBuilder(\n                          pageBuilder: (context, anim, secAnim) => gamePage,\n                          transitionsBuilder: (context, anim, secAnim, child) {\n                            return FadeTransition(opacity: anim, child: child);\n                          },\n                        ),\n                      );\n                    },\n                  ),\n                ],\n              ],\n            ),\n          ),\n        if (widget.item.isLocked && (widget.showPlayer || !widget.isDesktop))\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 8),\n            child: Container(\n              padding: const EdgeInsets.all(20),\n              decoration: BoxDecoration(\n                border: Border.all(color: Colors.white24),\n                color: Colors.white.withValues(alpha: 0.04),\n                borderRadius: BorderRadius.circular(8),\n              ),\n              child: const Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Text(\n                    \"your order is in the oven.\",\n                    style: TextStyle(\n                      color: kTextColor,\n                      fontFamily: 'JetBrainsMono',\n                      fontSize: 14,\n                      height: 1.5,\n                    ),\n                  ),\n                  SizedBox(height: 4),\n                  Text(\n                    \"estimated delivery time: march 2027\",\n                    style: TextStyle(\n                      color: Colors.white70,\n                      fontFamily: 'JetBrainsMono',\n                      fontSize: 13,\n                      letterSpacing: 1.1,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        if (widget.showPlayer && widget.item.tracks.isNotEmpty)\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16.0),\n            child: MusicPlayer(\n              tracks: widget.item.tracks,\n              audioPath: widget.item.audioPath,\n              isDesktop: widget.isDesktop,\n            ),\n          ),\n        if (widget.showLyricsButton &&\n            !widget.item.isLocked &&\n            widget.item.lyrics.isNotEmpty)\n          Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 16.0),\n            child: Row(\n              mainAxisAlignment: MainAxisAlignment.start,\n              children: [\n                TextButton.icon(\n                  onPressed: _handleToggle,\n                  icon: Icon(\n                    _isExpanded ? Icons.expand_less : Icons.expand_more,\n                    color: kAccentColor,\n                  ),\n                  label: Text(\n                    _isExpanded ? \"lyrics.collapse();\" : \"lyrics.expand();\",\n                    style: TextStyle(\n                      color: kAccentColor,\n                      fontFamily: 'JetBrainsMono',\n                      fontWeight: FontWeight.bold,\n                      letterSpacing: 1.2,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        if (widget.showLyricsContent &&\n            _isExpanded &&\n            !widget.item.isLocked &&\n            widget.item.lyrics.isNotEmpty)\n          Padding(\n            padding: const EdgeInsets.all(16.0),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text.rich(\n                  TextSpan(\n                    children: _buildLyricSpans(\n                      widget.item.lyrics,\n                      isDesktop: widget.isDesktop,\n                    ),\n                  ),\n                  textAlign: TextAlign.start,\n                ),\n              ],\n            ),\n          ),\n      ],\n    );\n  }\n}\n\nString _getTooltipForAlbum(String title) {\n  final t = title.toLowerCase();\n  if (t == 'blubber') return \"launch_protocol: gravity\";\n  if (t == 'santa\\'s cookies') return \"launch_protocol: chimney\";\n  return \"launch_protocol: gnu/linux\";\n}\n\nList<TextSpan> _buildLyricSpans(String lyrics, {required bool isDesktop}) {\n  final double defaultFontSize = isDesktop ? 16 : 14;\n  final double titleFontSize = isDesktop ? 20 : 16;\n  final double descriptionFontSize = isDesktop ? 14 : 12;\n\n  final defaultStyle = TextStyle(\n    color: kTextColor,\n    fontSize: defaultFontSize,\n    height: 1.5,\n    fontFamily: 'JetBrainsMono',\n  );\n\n  final titleStyle = TextStyle(\n    color: Colors.white70,\n    fontSize: titleFontSize,\n    fontWeight: FontWeight.bold,\n    height: 1.5,\n    fontFamily: 'JetBrainsMono',\n  );\n\n  final descriptionStyle = TextStyle(\n    color: kTextColor,\n    fontSize: descriptionFontSize,\n    fontStyle: FontStyle.italic,\n    height: 1.5,\n    fontFamily: 'JetBrainsMono',\n  );\n\n  final List<TextSpan> spans = [];\n  final lines = lyrics.split('\\n');\n\n  bool inDescriptionBlock = false;\n\n  for (final line in lines) {\n    final trimmedLine = line.trim();\n    if (trimmedLine == '**') {\n      inDescriptionBlock = !inDescriptionBlock;\n      continue;\n    }\n\n    if (inDescriptionBlock) {\n      spans.add(TextSpan(text: '\$line\\n', style: descriptionStyle));\n    } else if (trimmedLine.startsWith('[') && trimmedLine.endsWith(']')) {\n      final content = trimmedLine.substring(1, trimmedLine.length - 1);\n      spans.add(TextSpan(text: '// \$content\\n', style: titleStyle));\n    } else {\n      spans.add(TextSpan(text: '\$line\\n', style: defaultStyle));\n    }\n  }\n  return spans;\n}\n",
  "lib/pages/music/album_grid_item.dart": "import 'dart:ui';\n\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/music/album_detail_page.dart';\nimport 'package:archbtw_sh/pages/music/album_item.dart';\nimport 'package:archbtw_sh/widgets/loading_waveform.dart';\nimport 'package:flutter/material.dart';\n\nclass AlbumGridItem extends StatelessWidget {\n  final AlbumItem item;\n  const AlbumGridItem({super.key, required this.item});\n\n  @override\n  Widget build(BuildContext context) {\n    return InkWell(\n      onTap: () {\n        Navigator.push(\n          context,\n          PageRouteBuilder(\n            opaque: false,\n            pageBuilder: (context, animation, secondaryAnimation) {\n              return AlbumDetailPage(item: item);\n            },\n            transitionsBuilder:\n                (context, animation, secondaryAnimation, child) {\n                  return FadeTransition(opacity: animation, child: child);\n                },\n          ),\n        );\n      },\n      borderRadius: BorderRadius.circular(12.0),\n      child: ClipRRect(\n        borderRadius: BorderRadius.circular(12.0),\n        child: Stack(\n          children: [\n            BackdropFilter(\n              filter: ImageFilter.blur(sigmaX: 10.0, sigmaY: 10.0),\n              child: Container(\n                decoration: const BoxDecoration(color: Colors.transparent),\n              ),\n            ),\n            Card(\n              color: Colors.white.withValues(alpha: 0.05),\n              elevation: 0,\n              clipBehavior: Clip.antiAlias,\n              shape: RoundedRectangleBorder(\n                side: BorderSide(\n                  color: Colors.white.withValues(alpha: 0.1),\n                  width: 1,\n                ),\n                borderRadius: BorderRadius.circular(12.0),\n              ),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Expanded(\n                    child: Hero(\n                      tag: item.coverUrl,\n                      child: Stack(\n                        fit: StackFit.expand,\n                        children: [\n                          Image.asset(\n                            item.coverUrl,\n                            fit: BoxFit.cover,\n                            frameBuilder:\n                                (context, child, frame, wasSynchronouslyLoaded) {\n                                  if (wasSynchronouslyLoaded || frame != null) {\n                                    return child;\n                                  }\n                                  return Container(\n                                    color: Colors.white.withValues(alpha: 0.02),\n                                    child: const Center(\n                                      child: WaveformLoader(\n                                        height: 25,\n                                        barWidth: 3,\n                                      ),\n                                    ),\n                                  );\n                                },\n                            errorBuilder: (context, error, stackTrace) {\n                              return Container(\n                                color: Colors.grey[800],\n                                child: const Center(\n                                  child: Icon(\n                                    Icons.album_outlined,\n                                    color: kTextColor,\n                                    size: 50,\n                                  ),\n                                ),\n                              );\n                            },\n                          ),\n                          if (item.isLocked) ...[\n                            Container(\n                              color: Colors.black.withValues(alpha: 0.45),\n                            ),\n                 