                overflow: TextOverflow.ellipsis,\n                                ),\n                              ),\n                              if (item.isLocked)\n                                const Padding(\n                                  padding: EdgeInsets.only(left: 4.0),\n                                  child: Icon(\n                                    Icons.lock_outline,\n                                    size: 14,\n                                    color: Colors.white54,\n                                  ),\n                                ),\n                            ],\n                          ),\n                          const SizedBox(height: 4),\n                          if (item.isLocked)\n                            const Text(\n                              'coming march 2027',\n                              style: TextStyle(\n                                color: Colors.white54,\n                                fontSize: 11,\n                                fontFamily: 'JetBrainsMono',\n                              ),\n                            ),\n                        ],\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n",
