  "lib/pages/music/album_detail_page.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/music/album_art.dart';\nimport 'package:archbtw_sh/pages/music/album_details.dart';\nimport 'package:archbtw_sh/pages/music/album_item.dart';\nimport 'package:flutter/material.dart';\n\nclass AlbumDetailPage extends StatefulWidget {\n  final AlbumItem item;\n  const AlbumDetailPage({super.key, required this.item});\n\n  @override\n  State<AlbumDetailPage> createState() => _AlbumDetailPageState();\n}\n\nclass _AlbumDetailPageState extends State<AlbumDetailPage> {\n  bool _isLyricsExpanded = false;\n\n  void _toggleLyrics() {\n    setState(() {\n      _isLyricsExpanded = !_isLyricsExpanded;\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: kBackgroundColor,\n      appBar: AppBar(\n        backgroundColor: Colors.transparent,\n        elevation: 0,\n        leading: const BackButton(color: kTextColor),\n      ),\n      body: SingleChildScrollView(\n        child: Center(\n          child: ConstrainedBox(\n            constraints: const BoxConstraints(maxWidth: 1200.0),\n            child: LayoutBuilder(\n              builder: (context, constraints) {\n                final bool isDesktop = constraints.maxWidth > 800.0;\n  \n                final albumArt = AlbumArt(item: widget.item);\n\n                if (isDesktop) {\n                  return Padding(\n                    padding: const EdgeInsets.all(32.0),\n                    child: Column(\n                      children: [\n                        Row(\n                          crossAxisAlignment: CrossAxisAlignment.start,\n                          children: [\n                            Expanded(\n                              flex: 2,\n                              child: Column(\n                                children: [\n                                  albumArt,\n                                  AlbumDetails(\n                                    item: widget.item,\n                                    isDesktop: isDesktop,\n                                    showTitle: true,\n                                    showPlayer: false,\n                                    showLyricsButton: false,\n                                    showLyricsContent: false,\n                                  ),\n                                ],\n                              ),\n                            ),\n                            const SizedBox(width: 32.0),\n                            Expanded(\n                              flex: 3,\n                              child: AlbumDetails(\n                                item: widget.item,\n                                isDesktop: isDesktop,\n                                showTitle: false,\n                                showPlayer: true,\n                                showLyricsButton: true,\n                                showLyricsContent: true,\n                                isLyricsExpanded: _isLyricsExpanded,\n                                onToggleLyrics: _toggleLyrics,\n                              ),\n                            ),\n                          ],\n                        ),\n                      ],\n                    ),\n                  );\n                } else {\n                  return Column(\n                    crossAxisAlignment: CrossAxisAlignment.stretch,\n                    children: [\n                      albumArt,\n                      AlbumDetails(\n                        item: widget.item,\n                        isDesktop: isDesktop,\n                        showTitle: true,\n                        showPlayer: true,\n                        showLyricsButton: true,\n                        showLyricsContent: true,\n                      ),\n                    ],\n                  );\n                }\n              },\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}",
