  "lib/pages/home/home_page.dart": "import 'dart:async';\n\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/overheat/overheat_page.dart';\nimport 'package:archbtw_sh/widgets/social_icons.dart';\nimport 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass HomePage extends StatefulWidget {\n  const HomePage({super.key});\n\n  @override\n  State<HomePage> createState() => _HomePageState();\n}\n\nclass _HomePageState extends State<HomePage>\n    with AutomaticKeepAliveClientMixin {\n  static const String _fullText = \"hi. i'm archBTW.\";\n  String _currentText = '';\n  int _currentIndex = 0;\n  bool _showCursor = true;\n\n  late final Timer _typingTimer;\n  Timer? _cursorTimer;\n\n  @override\n  bool get wantKeepAlive => true;\n\n  @override\n  void initState() {\n    super.initState();\n\n    _typingTimer = Timer.periodic(const Duration(milliseconds: 150), (timer) {\n      if (_currentIndex < _fullText.length) {\n        if (mounted) {\n          setState(() {\n            _currentText = _fullText.substring(0, _currentIndex + 1);\n            _currentIndex++;\n          });\n        }\n      } else {\n        timer.cancel();\n        _cursorTimer = Timer.periodic(const Duration(milliseconds: 500), (\n          timer,\n        ) {\n          if (mounted) {\n            setState(() {\n              _showCursor = !_showCursor;\n            });\n          }\n        });\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _typingTimer.cancel();\n    _cursorTimer?.cancel();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    super.build(context);\n\n    final screenWidth = MediaQuery.of(context).size.width;\n    final bool isDesktop = screenWidth >= 768.0;\n\n    final double titleFontSize = isDesktop ? 36 : 24;\n    final double iconSize = isDesktop ? 24 : 18;\n    final double socialSpacing = isDesktop ? 24 : 16;\n    final double bottomPadding = isDesktop ? 64 : 32;\n\n    return Column(\n      children: [\n        Expanded(\n          child: Center(\n            child: Text.rich(\n              TextSpan(\n                children: [\n                  TextSpan(\n                    text: _currentText,\n                    style: TextStyle(\n                      color: kTextColor,\n                      fontSize: titleFontSize,\n                      fontWeight: FontWeight.bold,\n                      letterSpacing: 1.5,\n                      fontFamily: 'JetBrainsMono',\n                    ),\n                  ),\n                  TextSpan(\n                    text: _showCursor ? '|' : ' ',\n                    style: TextStyle(\n                      color: _showCursor ? kAccentColor : Colors.transparent,\n                      fontSize: titleFontSize,\n                      fontWeight: FontWeight.bold,\n                      fontFamily: 'JetBrainsMono',\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ),\n        Padding(\n          padding: EdgeInsets.only(bottom: bottomPadding),\n          child: Row(\n            mainAxisAlignment: MainAxisAlignment.center,\n            children: [\n              SocialIcon(\n                icon: FontAwesomeIcons.linux,\n                url: 'https://welledumacated.dev',\n                iconSize: iconSize,\n              ),\n              SizedBox(width: socialSpacing),\n              SocialIcon(\n                icon: FontAwesomeIcons.computer,\n                url: 'https://archerwoods.dev',\n                iconSize: iconSize,\n              ),\n              SizedBox(width: socialSpacing),\n              SocialIcon(\n                icon: FontAwesomeIcons.github,\n                url: 'https://www.github.com/archieBTW',\n                iconSize: iconSize,\n              ),\n              SizedBox(width: socialSpacing),\n              SocialIcon(\n                icon: FontAwesomeIcons.code,\n                iconSize: iconSize,\n                onPressed: () {\n                  Navigator.pushNamed(context, '/source');\n                },\n              ),\n              SizedBox(width: socialSpacing),\n              SocialIcon(\n                icon: FontAwesomeIcons.fire,\n                iconSize: iconSize,\n                tooltip: 'overheat',\n                hoverColor: const Color(0xFFFF6F00),\n                onPressed: () {\n                  Navigator.push(\n                    context,\n                    PageRouteBuilder(\n                      opaque: false,\n                      pageBuilder: (context, animation, secondaryAnimation) {\n                        return const OverheatPage();\n                      },\n                      transitionsBuilder:\n                          (context, animation, secondaryAnimation, child) {\n                        return FadeTransition(opacity: animation, child: child);\n                      },\n                    ),\n                  );\n                },\n              ),\n            ],\n          ),\n        ),\n      ],\n    );\n  }\n}\n",
  "lib/pages/about/about.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass AboutPage extends StatelessWidget {\n  const AboutPage({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final bool isDesktop = MediaQuery.of(context).size.width >= 768.0;\n    final EdgeInsets padding = isDesktop\n        ? const EdgeInsets.symmetric(horizontal: 120.0, vertical: 48.0)\n        : const EdgeInsets.symmetric(horizontal: 24.0, vertical: 24.0);\n\n    return SingleChildScrollView(\n      padding: padding,\n      child: Center(\n        child: ConstrainedBox(\n          constraints: const BoxConstraints(maxWidth: 800),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              Text(\n                \"\"\"\n __________________\n< hi. i'm archBTW. >\n ------------------\n         \\   ^__^\n          \\  (oo)\\_______\n            (__)\\       )\\/\\\n              ||----w |\n              ||     ||\n\n\nI started this project at the beginning of 2024 as a sort of musical diary. I've played guitar since I was a kid and started writing music in 5th grade. This continued into my later years, writing acoustic songs since I didn't have a band or know how to use music software. For several years, I was even a soundcloud rapper. As cringe as that was, it did teach me a lot about writing and using software so archBTW wouldn't exist without that experience.\n\narchBTW has been my way of combining the emo confessionals I grew up with and the stream-of-consciousness hip hop that I fell in love with in my 20's. All wrapped in a bedroom-indie package. \n\nI write and produce all of my music myself from the guitar and bass down to the synths and drums. I'm a huge fan of bandlab for this (it's way better and more capable than people think). I play a modded purple Harley Benton PRS-style guitar mainly but also have an SG, Tele, Mitchell acoustic, and occasionally borrow a strat. \n\nAll of the guitar sounds you hear come from various pedals (the main 2 being a fender amp simulator and a ts-808 clone) sometimes mixed with some digital effects depending on the song. \n\nMore background on me as a person:\n\nMy name is Archer and I live in Oklahoma City with my wife, dog, cat, and bearded dragon. When I'm not writing and making music, I'm working as a DevOps Engineer or coding on my personal projects. Before DevOps, I worked as a software developer and before that, as a systems administrator so DevOps has been a fun way to combine the two worlds.\n\nCoding and music are huge passions of mine, but aside from those, I'm also a pretty big gearhead, a theology nerd, and a huge Linux fanboy.\n\nOh, I also have a mild obsession with Sanrio, specifically My Melody.\n\nIf you'd like to know more, click on the music tab. Like I said, it's pretty much my diary.\n\n-archBTW\n\n\"\"\",\n                style: TextStyle(\n                  color: kTextColor,\n                  fontSize: isDesktop ? 16 : 14,\n                  height: 1.6,\n                  fontFamily: 'JetBrainsMono',\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/pages/overheat/overheat_page.dart": "import 'dart:async';\nimport 'dart:math';\n\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\n\nenum OverheatPhase {\n  overheating,\n  announcement,\n  fading,\n  fireplace,\n}\n\nclass OverheatPage extends StatefulWidget {\n  const OverheatPage({super.key});\n\n  @override\n  State<OverheatPage> createState() => _OverheatPageState();\n}\n\nclass _OverheatPageState extends State<OverheatPage>\n    with SingleTickerProviderStateMixin {\n  OverheatPhase _phase = OverheatPhase.overheating;\n\n  // Timers\n  Timer? _sequenceTimer;\n  Timer? _shakeTimer;\n  Timer? _logTimer;\n  Timer? _fireTimer;\n  Timer? _cursorTimer;\n\n  // Phase 1: Overheating log simulation & meters\n  final List<String> _overheatLogs = [\n    \"[    0.000000] ACPI: ACPI thermal trip points reached!\",\n    \"[    0.041029] thermal thermal_zone0: critical temperature reached (105 C)\",\n    \"[    0.108231] CPU0: Core temperature above threshold, cpu clock throttled!\",\n    \"[    0.189442] coretemp: TCC activation temperature exceeded on CPU 0..7\",\n    \"[    0.280194] cooling_device0: max cooling state 100% engaged (8500 RPM)\",\n    \"[    0.391002] WARNING: HEAT DISSIPATION SATURATION DETECTED\",\n    \"[    0.512998] ACPI: \\\\_TZ.THM0: CRITICAL THERMAL EVENT IN PROGRESS\",\n    \"[    0.640129] KERNEL PANIC IMMINENT: CPU SILICON EXCEEDING SAFE LIMITS\",\n    \"[    0.781290] TEMPERATURE RUNAWAY: +15°C/s [112°C -> 128°C -> 149°C]\",\n    \"[    0.920194] EMERGENCY: COOLING SUB-SYSTEM FAILURE\",\n    \"[    1.104291] SYSTEM OVERHEATING: HARDWARE THERMAL TRIP DETECTED!\",\n    \"[    1.290112] CRITICAL: FLASHPOINT REACHED IN SYSTEM CORE\",\n  ];\n  final List<String> _displayedLogs = [];\n  int _logIndex = 0;\n  int _temperature = 45;\n  double _shakeX = 0;\n  double _shakeY = 0;\n  bool _redFlash = false;\n  final ScrollController _logScrollController = ScrollController();\n\n  // Phase 2: Announcement\n  bool _showCursor = true;\n\n  // Phase 3 & 4: Fade controller & Full-Screen ASCII Fire simulation\n  late AnimationController _fadeController;\n  late Animation<double> _textOpacityAnimation;\n  late Animation<double> _fireplaceOpacityAnimation;\n\n  final Random _rand = Random();\n\n  // Full-screen dynamic fire grid\n  int _heatCols = 0;\n  int _heatRows = 0;\n  List<List<int>> _heat = [];\n\n  // Flame intensity (controlled via Up/Down arrows like fireplace-cli)\n  int _flameHeight = 8; // Range 4..12\n\n  static const List<String> _fireRamp = [\n    ' ',\n    '.',\n    ':',\n    '-',\n    '=',\n    '+',\n    '*',\n    '#',\n    '%',\n    '@',\n  ];\n\n  static const List<Color> _firePalette = [\n    Colors.transparent,\n    Color(0xFF3E1205), // dark smoky ember\n    Color(0xFF6B1B0C), // dark crimson\n    Color(0xFF9E2300), // deep red\n    Color(0xFFC73600), // red-orange\n    Color(0xFFE85400), // fiery orange\n    Color(0xFFFF7A00), // bright flame orange\n    Color(0xFFFFB300), // warm amber gold\n    Color(0xFFFFEE58), // bright yellow\n    Color(0xFFFFFFFF), // pure white-hot center\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n\n    // Animation controller for fading out announcement and fading in fireplace\n    _fadeController = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 1000),\n    );\n\n    _textOpacityAnimation = Tween<double>(begin: 1.0, end: 0.0).animate(\n      CurvedAnimation(parent: _fadeController, curve: Curves.easeInOut),\n    );\n\n    _fireplaceOpacityAnimation = Tween<double>(begin: 0.0, end: 1.0).animate(\n      CurvedAnimation(parent: _fadeController, curve: Curves.easeInOut),\n    );\n\n    _fadeController.addStatusListener((status) {\n      if (status == AnimationStatus.completed) {\n        if (mounted) {\n          setState(() {\n            _phase = OverheatPhase.fireplace;\n          });\n        }\n      }\n    });\n\n    _startOverheatingSequence();\n  }\n\n  void _startOverheatingSequence() {\n    // Shake timer\n    _shakeTimer = Timer.periodic(const Duration(milliseconds: 40), (_) {\n      if (!mounted) return;\n      if (_phase == OverheatPhase.overheating) {\n        setState(() {\n          _shakeX = (_rand.nextDouble() * 6) - 3;\n          _shakeY = (_rand.nextDouble() * 6) - 3;\n          _redFlash = !_redFlash;\n        });\n      }\n    });\n\n    // Feed logs and increase temperature rapidly\n    _logTimer = Timer.periodic(const Duration(milliseconds: 250), (timer) {\n      if (!mounted) return;\n      if (_logIndex < _overheatLogs.length) {\n        setState(() {\n          _displayedLogs.add(_overheatLogs[_logIndex]);\n          _logIndex++;\n          _temperature = (_temperature + 12).clamp(45, 185);\n        });\n        if (_logScrollController.hasClients) {\n          _logScrollController.animateTo(\n            _logScrollController.position.maxScrollExtent,\n            duration: const Duration(milliseconds: 100),\n            curve: Curves.easeOut,\n          );\n        }\n      } else {\n        timer.cancel();\n      }\n    });\n\n    // After 3.5 seconds of overheating, transition to announcement\n    _sequenceTimer = Timer(const Duration(milliseconds: 3500), () {\n      if (!mounted) return;\n      _shakeTimer?.cancel();\n      _logTimer?.cancel();\n      setState(() {\n        _phase = OverheatPhase.announcement;\n        _shakeX = 0;\n        _shakeY = 0;\n      });\n\n      // Cursor blinking for announcement (fixed position, no layout shift)\n      _cursorTimer = Timer.periodic(const Duration(milliseconds: 450), (_) {\n        if (!mounted) return;\n        setState(() {\n          _showCursor = !_showCursor;\n        });\n      });\n\n      // Display announcement for 2.8 seconds, then start crossfade to fireplace\n      _sequenceTimer = Timer(const Duration(milliseconds: 2800), () {\n        if (!mounted) return;\n        _cursorTimer?.cancel();\n        _startFireplaceSimulation();\n        setState(() {\n          _phase = OverheatPhase.fading;\n        });\n        _fadeController.forward();\n      });\n    });\n  }\n\n  void _startFireplaceSimulation() {\n    // Fire animation runs indefinitely at ~50ms (~20 FPS matching fireplace-cli)\n    _fireTimer = Timer.periodic(const Duration(milliseconds: 50), (_) {\n      if (!mounted) return;\n      _updateFire();\n      setState(() {});\n    });\n  }\n\n  void _ensureGridSize(int cols, int rows) {\n    if (_heatCols == cols && _heatRows == rows) return;\n    _heatCols = cols;\n    _heatRows = rows;\n    _heat = List.generate(rows, (_) => List.filled(cols, 0));\n  }\n\n  void _updateFire() {\n    if (_heatCols <= 0 || _heatRows <= 0 || _heat.isEmpty) return;\n\n    // 1. Ignite bottom 2 rows with randomized fuel across the entire screen width\n    for (int x = 0; x < _heatCols; x++) {\n      if (_rand.nextDouble() < 0.88) {\n        _heat[_heatRows - 1][x] = 9;\n        _heat[_heatRows - 2][x] = 7 + _rand.nextInt(3);\n      } else {\n        _heat[_heatRows - 1][x] = 5 + _rand.nextInt(4);\n        _heat[_heatRows - 2][x] = _rand.nextInt(5);\n      }\n    }\n\n    // 2. Propagate upward (fireplace / aafire cellular automaton)\n    // Dynamic decay rate influenced by _flameHeight\n    final double decayProb = (14.0 - _flameHeight) / 10.0;\n\n    for (int y = 0; y < _heatRows - 2; y++) {\n      for (int x = 0; x < _heatCols; x++) {\n        int decay = _rand.nextDouble() < decayProb ? 1 : 0;\n        if (y < _heatRows * 0.45 && _rand.nextBool()) decay += 1;\n        if (y < _heatRows * 0.25) decay += _rand.nextInt(2);\n\n        int spread = _rand.nextInt(3) - 1; // -1, 0, or 1\n        int srcX = (x + spread).clamp(0, _heatCols - 1);\n        int srcY = min(_heatRows - 1, y + 1 + (_rand.nextDouble() < 0.2 ? 1 : 0));\n        _heat[y][x] = max(0, _heat[srcY][srcX] - decay);\n      }\n    }\n  }\n\n  void _exit() {\n    Navigator.of(context).pop();\n  }\n\n  void _adjustFlame(int delta) {\n    setState(() {\n      _flameHeight = (_flameHeight + delta).clamp(4, 12);\n    });\n  }\n\n  @override\n  void dispose() {\n    _sequenceTimer?.cancel();\n    _shakeTimer?.cancel();\n    _logTimer?.cancel();\n    _fireTimer?.cancel();\n    _cursorTimer?.cancel();\n    _fadeController.dispose();\n    _logScrollController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return KeyboardListener(\n      focusNode: FocusNode()..requestFocus(),\n      onKeyEvent: (event) {\n        if (event is KeyDownEvent) {\n          if (event.logicalKey == LogicalKeyboardKey.escape ||\n              event.logicalKey == LogicalKeyboardKey.keyQ) {\n            _exit();\n          } else if (event.logicalKey == LogicalKeyboardKey.arrowUp ||\n              event.logicalKey == LogicalKeyboardKey.keyW) {\n            _adjustFlame(1);\n          } else if (event.logicalKey == LogicalKeyboardKey.arrowDown ||\n              event.logicalKey == LogicalKeyboardKey.keyS) {\n            _adjustFlame(-1);\n          }\n        }\n      },\n      child: GestureDetector(\n        behavior: HitTestBehavior.opaque,\n        onTap: () {\n          // If in fireplace stage or fading stage, click anywhere exits\n          if (_phase == OverheatPhase.fireplace || _phase == OverheatPhase.fading) {\n            _exit();\n          } else {\n            // If user clicks during early overheating, skip directly to fireplace\n            _skipToFireplace();\n          }\n        },\n        child: Scaffold(\n          backgroundColor: Colors.black,\n          body: Stack(\n            fit: StackFit.expand,\n            children: [\n              // Content: overheating alert, announcement, or full-screen fire\n              _buildCurrentPhaseContent(),\n\n              // Subtle CRT red flash vignette during overheating\n              if (_phase == OverheatPhase.overheating && _redFlash)\n                IgnorePointer(\n                  child: Container(\n                    decoration: BoxDecoration(\n                      gradient: RadialGradient(\n                        center: Alignment.center,\n                        radius: 1.2,\n                        colors: [\n                          Colors.transparent,\n                          Colors.red.withValues(alpha: 0.15),\n                        ],\n                      ),\n                    ),\n                  ),\n                ),\n\n              // Close button in top-right\n              Positioned(\n                top: 20,\n                right: 20,\n                child: IconButton(\n                  icon: const Icon(Icons.close, color: Colors.white54, size: 24),\n                  tooltip: \"exit\",\n                  onPressed: _exit,\n                ),\n              ),\n\n              // Instructions / status hint in fireplace mode\n              if (_phase == OverheatPhase.fireplace || _phase == OverheatPhase.fading)\n                Positioned(\n                  top: 24,\n                  left: 24,\n                  child: IgnorePointer(\n                    child: Text(\n                      \"[ click anywhere to exit ]\",\n                      style: TextStyle(\n                        color: Colors.white.withValues(alpha: 0.35),\n                        fontFamily: 'JetBrainsMono',\n                        fontSize: 12,\n                        letterSpacing: 1.2,\n                      ),\n                    ),\n                  ),\n                ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  void _skipToFireplace() {\n    _shakeTimer?.cancel();\n    _logTimer?.cancel();\n    _sequenceTimer?.cancel();\n    _cursorTimer?.cancel();\n    _shakeX = 0;\n    _shakeY = 0;\n    _startFireplaceSimulation();\n    setState(() {\n      _phase = OverheatPhase.fireplace;\n    });\n  }\n\n  Widget _buildCurrentPhaseContent() {\n    switch (_phase) {\n      case OverheatPhase.overheating:\n        return Transform.translate(\n          offset: Offset(_shakeX, _shakeY),\n          child: Center(child: _buildOverheatingView()),\n        );\n      case OverheatPhase.announcement:\n        return Center(child: _buildAnnouncementText());\n      case OverheatPhase.fading:\n        return Stack(\n          fit: StackFit.expand,\n          children: [\n            FadeTransition(\n              opacity: _fireplaceOpacityAnimation,\n              child: _buildFullScreenFire(),\n            ),\n            Center(\n              child: FadeTransition(\n                opacity: _textOpacityAnimation,\n                child: _buildAnnouncementText(),\n              ),\n            ),\n          ],\n        );\n      case OverheatPhase.fireplace:\n        return _buildFullScreenFire();\n    }\n  }\n\n  // --- Phase 1: Overheating Alert & Logs ---\n  Widget _buildOverheatingView() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final isMobile = constraints.maxWidth < 600;\n        final double logHeight =\n            (constraints.maxHeight * 0.40).clamp(160.0, 280.0);\n\n        return ConstrainedBox(\n          constraints: const BoxConstraints(maxWidth: 720),\n          child: Padding(\n            padding: EdgeInsets.symmetric(\n              horizontal: isMobile ? 16.0 : 24.0,\n              vertical: isMobile ? 16.0 : 32.0,\n            ),\n            child: Column(\n              mainAxisAlignment: MainAxisAlignment.center,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: [\n                // Warning Box\n                Container(\n                  padding: EdgeInsets.all(isMobile ? 12.0 : 16.0),\n                  decoration: BoxDecoration(\n                    color: Colors.red.withValues(alpha: 0.12),\n                    border: Border.all(\n                      color: _redFlash ? Colors.redAccent : Colors.deepOrange,\n                      width: 2,\n                    ),\n                    borderRadius: BorderRadius.circular(4),\n                  ),\n                  child: Column(\n                    children: [\n                      FittedBox(\n                        fit: BoxFit.scaleDown,\n                        child: Row(\n                          mainAxisAlignment: MainAxisAlignment.center,\n                          children: [\n                            Icon(\n                              Icons.warning_amber_rounded,\n                              color: _redFlash\n                                  ? Colors.redAccent\n                                  : Colors.orangeAccent,\n                              size: isMobile ? 22 : 28,\n                            ),\n                            const SizedBox(width: 8),\n                            Text(\n                              \"SYSTEM OVERHEATING\",\n                              style: TextStyle(\n                                color: _redFlash\n                                    ? Colors.redAccent\n                                    : Colors.orangeAccent,\n                                fontFamily: 'JetBrainsMono',\n                                fontSize: isMobile ? 18 : 22,\n                                fontWeight: FontWeight.bold,\n                                letterSpacing: isMobile ? 1.2 : 2.0,\n                              ),\n                            ),\n                          ],\n                        ),\n                      ),\n                      const SizedBox(height: 10),\n                      FittedBox(\n                        fit: BoxFit.scaleDown,\n                        child: Text(\n                          \"THERMAL RUNAWAY // TEMP: \$_temperature°C // CRITICAL\",\n                          style: TextStyle(\n                            color: Colors.white,\n                            fontFamily: 'JetBrainsMono',\n                            fontSize: isMobile ? 11 : 13,\n                            fontWeight: FontWeight.bold,\n                            letterSpacing: 1.1,\n                          ),\n                          textAlign: TextAlign.center,\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n                const SizedBox(height: 20),\n\n                // Live Kernel Thermal Log Output\n                Container(\n                  height: logHeight,\n                  padding: const EdgeInsets.all(16),\n                  decoration: BoxDecoration(\n                    color: Colors.white.withValues(alpha: 0.03),\n                    border: Border.all(color: Colors.white24),\n                    borderRadius: BorderRadius.circular(4),\n                  ),\n                  child: ListView.builder(\n                    controller: _logScrollController,\n                    itemCount: _displayedLogs.length,\n                    itemBuilder: (context, index) {\n                      final log = _displayedLogs[index];\n                      final isCrit = log.contains(\"CRITICAL\") ||\n                          log.contains(\"OVERHEATING\") ||\n                          log.contains(\"PANIC\") ||\n                          log.contains(\"EMERGENCY\");\n                      return Padding(\n                        padding: const EdgeInsets.symmetric(vertical: 3.0),\n                        child: Text(\n                          log,\n                          style: TextStyle(\n                            color: isCrit ? Colors.redAccent : Colors.white70,\n                            fontFamily: 'JetBrainsMono',\n                            fontSize: isMobile ? 11 : 12,\n                            height: 1.3,\n                          ),\n                        ),\n                      );\n                    },\n                  ),\n                ),\n              ],\n            ),\n          ),\n        );\n      },\n    );\n  }\n\n  // --- Phase 2: Announcement ---\n  // Symmetrical layout prevents any horizontal shifting when cursor blinks\n  Widget _buildAnnouncementText() {\n    return Padding(\n      padding: const EdgeInsets.symmetric(horizontal: 24.0),\n      child: LayoutBuilder(\n        builder: (context, constraints) {\n          final isDesktop = constraints.maxWidth >= 768;\n          final double fontSize = isDesktop ? 30 : 20;\n\n          final textStyle = TextStyle(\n            color: Colors.white,\n            fontFamily: 'JetBrainsMono',\n            fontSize: fontSize,\n            fontWeight: FontWeight.bold,\n            letterSpacing: 1.5,\n            shadows: const [\n              Shadow(color: Colors.white38, blurRadius: 20),\n            ],\n          );\n\n          final cursorStyle = TextStyle(\n            color: Colors.white,\n            fontFamily: 'JetBrainsMono',\n            fontSize: fontSize,\n            fontWeight: FontWeight.bold,\n          );\n\n          return FittedBox(\n            fit: BoxFit.scaleDown,\n            child: Row(\n              mainAxisSize: MainAxisSize.min,\n              mainAxisAlignment: MainAxisAlignment.center,\n              children: [\n                // Hidden dummy cursor on left to perfectly balance the right cursor\n                Opacity(\n                  opacity: 0.0,\n                  child: Text(\"_\", style: cursorStyle),\n                ),\n                Text(\n                  \"third-degree coming march 2027\",\n                  style: textStyle,\n                  textAlign: TextAlign.center,\n                ),\n                // Visible blinking cursor on right - Opacity changes paint only, zero layout change\n                Opacity(\n                  opacity: _showCursor ? 1.0 : 0.0,\n                  child: Text(\"_\", style: cursorStyle),\n                ),\n              ],\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  // --- Phase 4: Full-Screen ASCII Fire (fireplace-cli aesthetic) ---\n  Widget _buildFullScreenFire() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final double width = constraints.maxWidth;\n        final double height = constraints.maxHeight;\n\n        // Responsive font sizing to densely fill the screen\n        final double fontSize = width < 600 ? 10.0 : 13.0;\n        final double charWidth = fontSize * 0.60;\n        final double charHeight = fontSize * 1.15;\n\n        final int cols = (width / charWidth).floor().clamp(30, 200);\n        final int rows = (height / charHeight).floor().clamp(15, 90);\n\n        _ensureGridSize(cols, rows);\n\n        if (_heat.isEmpty || _heatRows != rows || _heatCols != cols) {\n          return const SizedBox.expand();\n        }\n\n        // Build spans using Run-Length Encoding (RLE) for high performance\n        final spans = <TextSpan>[];\n\n        for (int y = 0; y < rows; y++) {\n          int currentHeat = _heat[y][0].clamp(0, 9);\n          int runCount = 0;\n\n          for (int x = 0; x < cols; x++) {\n            final int h = _heat[y][x].clamp(0, 9);\n            if (h == currentHeat) {\n              runCount++;\n            } else {\n              if (runCount > 0) {\n                spans.add(\n                  TextSpan(\n                    text: _fireRamp[currentHeat] * runCount,\n                    style: TextStyle(\n                      color: _firePalette[currentHeat],\n                      fontWeight:\n                          currentHeat >= 7 ? FontWeight.bold : FontWeight.normal,\n                    ),\n                  ),\n                );\n              }\n              currentHeat = h;\n              runCount = 1;\n            }\n          }\n          if (runCount > 0) {\n            spans.add(\n              TextSpan(\n                text: _fireRamp[currentHeat] * runCount,\n                style: TextStyle(\n                  color: _firePalette[currentHeat],\n                  fontWeight:\n                      currentHeat >= 7 ? FontWeight.bold : FontWeight.normal,\n                ),\n              ),\n            );\n          }\n          if (y < rows - 1) {\n            spans.add(const TextSpan(text: '\\n'));\n          }\n        }\n\n        return Align(\n          alignment: Alignment.bottomCenter,\n          child: SizedBox(\n            width: cols * charWidth,\n            height: rows * charHeight,\n            child: Text.rich(\n              TextSpan(children: spans),\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                fontSize: fontSize,\n                height: 1.15,\n                letterSpacing: 0,\n              ),\n              softWrap: false,\n              overflow: TextOverflow.clip,\n            ),\n          ),\n        );\n      },\n    );\n  }\n}\n",
  "lib/pages/source_code/source_code_page.dart": "import 'package:archbtw_sh/generated/source_code.dart';\nimport 'package:archbtw_sh/pages/source_code/file_tree.dart';\nimport 'package:flutter/material.dart';\nimport 'package:archbtw_sh/widgets/selectable_highlight_view.dart';\nimport 'package:flutter_highlight/themes/atom-one-dark.dart';\n\nclass SourceCodePage extends StatefulWidget {\n  const SourceCodePage({super.key});\n\n  @override\n  State<SourceCodePage> createState() => _SourceCodePageState();\n}\n\nclass _SourceCodePageState extends State<SourceCodePage> {\n  String? _selectedFile = 'lib/main.dart';\n\n  final GlobalKey<ScaffoldState> _scaffoldKey = GlobalKey<ScaffoldState>();\n\n  Widget _buildTopBar(bool isDesktop) {\n    return Container(\n      height: 40,\n      color: const Color(0xFF0D0D0D),\n      padding: const EdgeInsets.symmetric(horizontal: 16),\n      child: Row(\n        children: [\n          IconButton(\n            icon: const Icon(Icons.arrow_back, color: Colors.white70, size: 20),\n            onPressed: () {\n              Navigator.pop(context); // Go back home\n            },\n            tooltip: 'Back to Home',\n            padding: EdgeInsets.zero,\n            constraints: const BoxConstraints(),\n          ),\n          const Spacer(),\n          const Text(\n            'archBTW.sh',\n            style: TextStyle(\n              fontFamily: 'JetBrainsMono',\n              fontSize: 14,\n              color: Colors.white70,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const Spacer(),\n          if (!isDesktop)\n            IconButton(\n              icon: const Icon(Icons.menu, color: Colors.white70, size: 20),\n              onPressed: () {\n                _scaffoldKey.currentState?.openDrawer();\n              },\n              tooltip: 'files',\n              padding: EdgeInsets.zero,\n              constraints: const BoxConstraints(),\n            )\n          else\n            const SizedBox(width: 20),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildCodeViewer(String content, bool isDesktop) {\n    final lines = content.split('\\n');\n    final double fontSize = isDesktop ? 14 : 11;\n\n    return SelectionArea(\n      child: SingleChildScrollView(\n        padding: const EdgeInsets.all(16.0),\n        child: SingleChildScrollView(\n          scrollDirection: Axis.horizontal,\n          child: Row(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              // Line numbers\n              SelectionContainer.disabled(\n                child: Column(\n                  crossAxisAlignment: CrossAxisAlignment.end,\n                  children: List.generate(lines.length, (index) {\n                    return Text(\n                      '\${index + 1}',\n                      style: TextStyle(\n                        fontFamily: 'JetBrainsMono',\n                        fontSize: fontSize,\n                        color: Colors.white38,\n                        height: 1.5,\n                      ),\n                    );\n                  }),\n                ),\n              ),\n              const SizedBox(width: 16),\n              // Code\n              SelectableHighlightView(\n                content,\n                language: 'dart',\n                theme: {\n                  ...atomOneDarkTheme,\n                  'root': TextStyle(\n                    backgroundColor: const Color(0xFF0D0D0D),\n                    color:\n                        atomOneDarkTheme['root']?.color ??\n                        const Color(0xffabb2bf),\n                  ),\n                },\n                padding: EdgeInsets.zero,\n                textStyle: TextStyle(\n                  fontFamily: 'JetBrainsMono',\n                  fontSize: fontSize,\n                  height: 1.5,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final screenWidth = MediaQuery.of(context).size.width;\n    final isDesktop = screenWidth >= 768.0;\n\n    final fileTreeWidget = FileTreeWidget(\n      files: sourceCodeFiles,\n      selectedFile: _selectedFile,\n      onFileSelected: (path) {\n        setState(() {\n          _selectedFile = path;\n        });\n        if (!isDesktop) {\n          Navigator.of(context).pop(); // Close drawer\n        }\n      },\n    );\n\n    final String? fileName = _selectedFile?.split('/').last;\n    final content = _selectedFile != null\n        ? sourceCodeFiles[_selectedFile!]\n        : null;\n\n    final codeViewerWidget = Container(\n      color: const Color(0xFF0D0D0D), // Match sidebar background\n      width: double.infinity,\n      height: double.infinity,\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          if (fileName != null)\n            Container(\n              color: const Color(0xFF0D0D0D),\n              child: Row(\n                children: [\n                  Container(\n                    padding: const EdgeInsets.symmetric(\n                      horizontal: 16,\n                      vertical: 8,\n                    ),\n                    decoration: const BoxDecoration(\n                      color: Color(0xFF0D0D0D), // Match the background\n                      border: Border(\n                        top: BorderSide(color: Colors.blueAccent, width: 2),\n                      ),\n                    ),\n                    child: Row(\n                      children: [\n                        Text(\n                          fileName,\n                          style: const TextStyle(\n                            fontFamily: 'JetBrainsMono',\n                            color: Colors.white,\n                            fontSize: 13,\n                          ),\n                        ),\n                        const SizedBox(width: 8),\n                        const Icon(\n                          Icons.close,\n                          size: 14,\n                          color: Colors.white54,\n                        ),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          Expanded(\n            child: content == null\n                ? const Center(\n                    child: Text(\n                      'Select a file to view its source code.',\n                      style: TextStyle(\n                        fontFamily: 'JetBrainsMono',\n                        color: Colors.white54,\n                      ),\n                    ),\n                  )\n                : _buildCodeViewer(content, isDesktop),\n          ),\n        ],\n      ),\n    );\n\n    return Scaffold(\n      key: _scaffoldKey,\n      backgroundColor: const Color(0xFF0D0D0D),\n      drawer: isDesktop ? null : Drawer(child: fileTreeWidget),\n      body: SafeArea(\n        child: Column(\n          children: [\n            _buildTopBar(isDesktop),\n            Expanded(\n              child: isDesktop\n                  ? Row(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        SizedBox(width: 250, child: fileTreeWidget),\n                        Expanded(child: codeViewerWidget),\n                      ],\n                    )\n                  : codeViewerWidget,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/pages/source_code/file_tree.dart": "import 'package:flutter/material.dart';\n\nclass FileNode {\n  final String name;\n  final String? fullPath;\n  final List<FileNode> children;\n\n  FileNode({required this.name, this.fullPath, List<FileNode>? children})\n      : children = children ?? [];\n\n  bool get isFile => fullPath != null;\n}\n\nclass FileTreeWidget extends StatelessWidget {\n  final Map<String, String> files;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n\n  const FileTreeWidget({\n    super.key,\n    required this.files,\n    this.selectedFile,\n    required this.onFileSelected,\n  });\n\n  FileNode _buildTree() {\n    final root = FileNode(name: 'archbtw.sh');\n    final libNode = FileNode(name: 'lib');\n    root.children.add(libNode);\n\n    for (final path in files.keys) {\n      final cleanPath = path.startsWith('lib/') ? path.substring(4) : path;\n      final parts = cleanPath.split('/');\n      var current = libNode;\n      for (var i = 0; i < parts.length; i++) {\n        final part = parts[i];\n        final isFile = i == parts.length - 1;\n\n        var child = current.children.cast<FileNode?>().firstWhere(\n            (n) => n!.name == part,\n            orElse: () => null);\n        if (child == null) {\n          child = FileNode(\n            name: part,\n            fullPath: isFile ? path : null,\n          );\n          current.children.add(child);\n        }\n        current = child;\n      }\n    }\n    \n    _sortNode(libNode);\n    return root;\n  }\n\n  void _sortNode(FileNode node) {\n    node.children.sort((a, b) {\n      if (a.isFile && !b.isFile) return 1;\n      if (!a.isFile && b.isFile) return -1;\n      return a.name.compareTo(b.name);\n    });\n    for (final child in node.children) {\n      _sortNode(child);\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final root = _buildTree();\n    return Container(\n      color: const Color(0xFF0D0D0D), // very dark background for sidebar\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          const Padding(\n            padding: EdgeInsets.fromLTRB(16, 12, 16, 8),\n            child: Text(\n              'EXPLORER',\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                fontSize: 11,\n                color: Colors.white54,\n                letterSpacing: 1.2,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n          ),\n          Expanded(\n            child: ListView(\n              padding: EdgeInsets.zero,\n              children: [\n                _TreeNodeWidget(\n                  node: root,\n                  level: 0,\n                  selectedFile: selectedFile,\n                  onFileSelected: onFileSelected,\n                  initiallyExpanded: true,\n                ),\n              ],\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _TreeNodeWidget extends StatefulWidget {\n  final FileNode node;\n  final int level;\n  final String? selectedFile;\n  final ValueChanged<String> onFileSelected;\n  final bool initiallyExpanded;\n\n  const _TreeNodeWidget({\n    required this.node,\n    required this.level,\n    required this.selectedFile,\n    required this.onFileSelected,\n    this.initiallyExpanded = false,\n  });\n\n  @override\n  State<_TreeNodeWidget> createState() => _TreeNodeWidgetState();\n}\n\nclass _TreeNodeWidgetState extends State<_TreeNodeWidget> {\n  late bool _isExpanded;\n\n  @override\n  void initState() {\n    super.initState();\n    _isExpanded = widget.initiallyExpanded || widget.level <= 1;\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    if (widget.node.isFile) {\n      final isSelected = widget.node.fullPath == widget.selectedFile;\n      return InkWell(\n        onTap: () => widget.onFileSelected(widget.node.fullPath!),\n        child: Container(\n          color: isSelected ? Colors.white.withOpacity(0.1) : Colors.transparent,\n          padding: EdgeInsets.only(left: 16.0 + (widget.level * 12.0), top: 4, bottom: 4, right: 8),\n          child: Row(\n            children: [\n              const Icon(Icons.insert_drive_file, size: 14, color: Colors.white70),\n              const SizedBox(width: 6),\n              Expanded(\n                child: Text(\n                  widget.node.name,\n                  style: TextStyle(\n                    fontFamily: 'JetBrainsMono',\n                    fontSize: 13,\n                    color: isSelected ? Colors.white : Colors.white70,\n                  ),\n                  overflow: TextOverflow.ellipsis,\n                ),\n              ),\n            ],\n          ),\n        ),\n      );\n    } else {\n      return Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          InkWell(\n            onTap: () {\n              setState(() {\n                _isExpanded = !_isExpanded;\n              });\n            },\n            child: Container(\n              padding: EdgeInsets.only(left: 8.0 + (widget.level * 12.0), top: 4, bottom: 4, right: 8),\n              child: Row(\n                children: [\n                  Icon(\n                    _isExpanded ? Icons.keyboard_arrow_down : Icons.keyboard_arrow_right,\n                    size: 16,\n                    color: Colors.white54,\n                  ),\n                  const SizedBox(width: 2),\n                  const Icon(Icons.folder, size: 14, color: Color(0xFF9E75FF)), // purple folder\n                  const SizedBox(width: 6),\n                  Expanded(\n                    child: Text(\n                      widget.node.name,\n                      style: const TextStyle(\n                        fontFamily: 'JetBrainsMono',\n                        fontSize: 13,\n                        color: Colors.white,\n                        fontWeight: FontWeight.w500,\n                      ),\n                      overflow: TextOverflow.ellipsis,\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n          if (_isExpanded)\n            ...widget.node.children.map((child) => _TreeNodeWidget(\n                  node: child,\n                  level: widget.level + 1,\n                  selectedFile: widget.selectedFile,\n                  onFileSelected: widget.onFileSelected,\n                )),\n        ],\n      );\n    }\n  }\n}\n",
  "lib/pages/merch/merch_item_list.dart": "import 'package:archbtw_sh/pages/merch/merch_item.dart';\n\nfinal List<MerchItem> merchItems = [\n  const MerchItem(\n    name: 'logo shirt',\n    price: '\\\$23.00',\n    imageUrl: 'assets/images/logo-tee.png',\n    productUrl: 'https://www.teepublic.com/t-shirt/83503900-archbtw-logo?store_id=4214012',\n  ),\n  const MerchItem(\n    name: 'logo hoodie',\n    price: '\\\$42.00',\n    imageUrl: 'assets/images/logo-hoodie.png',\n    productUrl: 'https://www.teepublic.com/hoodie/83503900-archbtw-logo',\n  ),\n  const MerchItem(\n    name: 'logo sticker',\n    price: '\\\$3.25',\n    imageUrl: 'assets/images/logo-sticker.png',\n    productUrl: 'https://www.teepublic.com/sticker/83503900-archbtw-logo',\n  ),\n  const MerchItem(\n    name: 'lithiated shirt',\n    price: '\\\$23.00',\n    imageUrl: 'assets/images/lithiated-tee.png',\n    productUrl: 'https://www.teepublic.com/t-shirt/83503505-lithiated?store_id=4214012',\n  ),\n  const MerchItem(\n    name: 'lithiated hoodie',\n    price: '\\\$42.00',\n    imageUrl: 'assets/images/lithiated-hoodie.png',\n    productUrl: 'https://www.teepublic.com/hoodie/83503505-lithiated',\n  ),\n  const MerchItem(\n    name: 'lithiated baseball tee',\n    price: '\\\$26.00',\n    imageUrl: 'assets/images/lithiated-baseball.png',\n    productUrl: 'https://www.teepublic.com/baseball-tee/83503505-lithiated',\n  ),\n  const MerchItem(\n    name: 'blubber shirt',\n    price: '\\\$23.00',\n    imageUrl: 'assets/images/blubber-tee.png',\n    productUrl: 'https://www.teepublic.com/t-shirt/83503756-blubber?store_id=4214012',\n  ),\n  const MerchItem(\n    name: 'blubber hoodie',\n    price: '\\\$42.00',\n    imageUrl: 'assets/images/blubber-hoodie.png',\n    productUrl: 'https://www.teepublic.com/hoodie/83503756-blubber',\n  ),\n  const MerchItem(\n    name: 'blubber socks',\n    price: '\\\$18.00',\n    imageUrl: 'assets/images/blubber-socks.png',\n    productUrl: 'https://www.teepublic.com/socks/83503756-blubber',\n  ),\n];",
  "lib/pages/merch/merch__page.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/pages/merch/merch_grid_item.dart';\nimport 'package:archbtw_sh/pages/merch/merch_item_list.dart';\nimport 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\n\nconst String kStoreUrl = 'https://www.teepublic.com/user/archbtw';\n\nclass MerchPage extends StatelessWidget {\n  const MerchPage({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: CustomScrollView(\n        slivers: [\n          SliverPadding(\n            padding: const EdgeInsets.all(16.0),\n            sliver: SliverGrid.builder(\n              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(\n                maxCrossAxisExtent: 250.0,\n                crossAxisSpacing: 16.0,\n                mainAxisSpacing: 16.0,\n                childAspectRatio: 0.75,\n              ),\n              itemCount: merchItems.length,\n              itemBuilder: (context, index) {\n                return MerchGridItem(item: merchItems[index]);\n              },\n            ),\n          ),\n          SliverToBoxAdapter(\n            child: Padding(\n              padding: const EdgeInsets.fromLTRB(16.0, 8.0, 16.0, 32.0),\n              child: Center(\n                child: TextButton(\n                  onPressed: () => launchUrl(Uri.parse(kStoreUrl)),\n                  style: TextButton.styleFrom(\n                    foregroundColor: kAccentColor,\n                    textStyle: TextStyle(\n                      fontSize: 16,\n                      fontWeight: FontWeight.bold,\n                      fontFamily: 'JetBrainsMono',\n                    ),\n                  ),\n                  child: const Text('View More on TeePublic'),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\n",
  "lib/pages/merch/merch_grid_item.dart": "import 'dart:ui';\n\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/helpers.dart';\nimport 'package:archbtw_sh/pages/merch/merch_item.dart';\nimport 'package:archbtw_sh/widgets/loading_waveform.dart';\nimport 'package:flutter/material.dart';\n\nclass MerchGridItem extends StatelessWidget {\n  final MerchItem item;\n  const MerchGridItem({super.key, required this.item});\n\n  @override\n  Widget build(BuildContext context) {\n    return InkWell(\n      onTap: () => openUrl(item.productUrl),\n      borderRadius: BorderRadius.circular(12.0),\n      child: ClipRRect(\n        borderRadius: BorderRadius.circular(12.0),\n        child: Stack(\n          children: [\n            BackdropFilter(\n              filter: ImageFilter.blur(sigmaX: 10.0, sigmaY: 10.0),\n              child: Container(\n                decoration: const BoxDecoration(color: Colors.transparent),\n              ),\n            ),\n            Card(\n              color: Colors.white.withOpacity(0.05),\n              elevation: 0,\n              clipBehavior: Clip.antiAlias,\n              shape: RoundedRectangleBorder(\n                side: BorderSide(\n                  color: Colors.white.withOpacity(0.1),\n                  width: 1,\n                ),\n                borderRadius: BorderRadius.circular(12.0),\n              ),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.stretch,\n                children: [\n                  Expanded(\n                    child: Image.asset(\n                      item.imageUrl,\n                      fit: BoxFit.cover,\n                      frameBuilder:\n                          (context, child, frame, wasSynchronouslyLoaded) {\n                            if (wasSynchronouslyLoaded || frame != null) {\n                              return child;\n                            }\n                            return Container(\n                              color: Colors.white.withOpacity(0.02),\n                              child: const Center(\n                                child: WaveformLoader(height: 25, barWidth: 3),\n                              ),\n                            );\n                          },\n                      errorBuilder: (context, error, stackTrace) {\n                        return Container(\n                          color: Colors.grey[800],\n                          child: const Center(\n                            child: Icon(\n                              Icons.image_not_supported_outlined,\n                              color: kTextColor,\n                              size: 50,\n                            ),\n                          ),\n                        );\n                      },\n                    ),\n                  ),\n                  SizedBox(\n                    height: 85.0,\n                    child: Padding(\n                      padding: const EdgeInsets.all(12.0),\n                      child: Column(\n                        crossAxisAlignment: CrossAxisAlignment.start,\n                        mainAxisAlignment: MainAxisAlignment.center,\n                        children: [\n                          Text(\n                            item.name,\n                            style: const TextStyle(\n                              color: kTextColor,\n                              fontWeight: FontWeight.bold,\n                              fontSize: 14,\n                              fontFamily: 'JetBrainsMono',\n                            ),\n                            maxLines: 2,\n                            overflow: TextOverflow.ellipsis,\n                          ),\n                          const SizedBox(height: 4),\n                          Text(\n                            item.price,\n                            style: const TextStyle(\n                              color: kAccentColor,\n                              fontSize: 12,\n                              fontWeight: FontWeight.w500,\n                              fontFamily: 'JetBrainsMono',\n                            ),\n                          ),\n                        ],\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n",
  "lib/pages/merch/merch_item.dart": "class MerchItem {\n  final String name;\n  final String price;\n  final String imageUrl; \n  final String productUrl;\n\n  const MerchItem({\n    required this.name,\n    required this.price,\n    required this.imageUrl,\n    required this.productUrl,\n  });\n}\n",
  "lib/pages/error/kernel_panic_page.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass KernelPanicPage extends StatefulWidget {\n  const KernelPanicPage({super.key});\n\n  @override\n  State<KernelPanicPage> createState() => _KernelPanicPageState();\n}\n\nclass _KernelPanicPageState extends State<KernelPanicPage> {\n  final List<String> _lines = [];\n  final ScrollController _scrollController = ScrollController();\n  bool _isPanic = false;\n  Timer? _timer;\n  int _lineIndex = 0;\n\n  final List<String> _panicLogs = [\n    \"[    0.000000] Linux version 6.8.0-archbtw (gcc version 13.2.1) #1 SMP PREEMPT_DYNAMIC\",\n    \"[    0.000000] Command line: initrd=\\\\initramfs-linux.img root=PARTUUID=deadbeef-01 rw quiet\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x001: 'x87 floating point registers'\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x002: 'SSE registers'\",\n    \"[    0.000000] x86/fpu: Supporting XSAVE feature 0x004: 'AVX registers'\",\n    \"[    0.000000] BIOS-e820: [mem 0x0000000000000000-0x000000000009ffff] usable\",\n    \"[    0.000000] BIOS-e820: [mem 0x0000000000100000-0x00000000bfffffff] usable\",\n    \"[    0.000001] NX (Execute Disable) protection: active\",\n    \"[    0.000002] SMBIOS 3.5.0 present.\",\n    \"[    0.000123] DMI: archBTW Virtual Machine/archBTW-VM, BIOS 1.16.2-1.fc38 04/01/2014\",\n    \"[    0.001456] tsc: Fast TSC calibration failed\",\n    \"[    0.012345] Calibrating delay loop... 5988.12 BogoMIPS (lpj=2994060)\",\n    \"[    0.123456] devtmpfs: initialized\",\n    \"[    0.234567] clocksource: jiffies: mask: 0xffffffff max_cycles: 0xffffffff, max_idle_ns: 7645041785100000 ns\",\n    \"[    0.345678] NET: Registered Data Link Protocol family 0\",\n    \"[    0.456789] Storage device found: /dev/sda1 (ext4)\",\n    \"[    0.567890] EXT4-fs (sda1): mounting root file system\",\n    \"[    0.678901] EXT4-fs (sda1): ERROR: unexpected journal error -5\",\n    \"[    0.789012] EXT4-fs (sda1): critical error: cannot read superblock\",\n    \"[    0.890123] Kernel panic - not syncing: VFS: Unable to mount root fs on unknown-block(0,0)\",\n    \"[    0.890124] CPU: 0 PID: 1 Comm: swapper/0 Not tainted 6.8.0-archbtw #1\",\n    \"[    0.890125] Hardware name: archBTW Virtual Machine\",\n    \"[    0.890126] Call Trace:\",\n    \"[    0.890127]  <TASK>\",\n    \"[    0.890128]  dump_stack_lvl+0x44/0x5c\",\n    \"[    0.890129]  panic+0x10d/0x2ad\",\n    \"[    0.890130]  mount_block_root+0x1a8/0x1b4\",\n    \"[    0.890131]  mount_root+0x6e/0x81\",\n    \"[    0.890132]  prepare_namespace+0x13b/0x182\",\n    \"[    0.890133]  kernel_init_freeable+0x231/0x256\",\n    \"[    0.890134]  ? rest_init+0xce/0xce\",\n    \"[    0.890135]  kernel_init+0x17/0x130\",\n    \"[    0.890136]  ret_from_fork+0x1f/0x30\",\n    \"[    0.890137]  </TASK>\",\n    \"[    0.890138] ---[ end Kernel panic - not syncing: VFS: Unable to mount root fs on unknown-block(0,0) ]---\",\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n    _startBootSequence();\n  }\n\n  void _startBootSequence() {\n    _timer = Timer.periodic(const Duration(milliseconds: 50), (timer) {\n      if (_lineIndex < _panicLogs.length) {\n        setState(() {\n          _lines.add(_panicLogs[_lineIndex]);\n          _lineIndex++;\n          if (_panicLogs[_lineIndex - 1].contains(\"Kernel panic\")) {\n            _isPanic = true;\n          }\n        });\n        _scrollToBottom();\n      } else {\n        _timer?.cancel();\n      }\n    });\n  }\n\n  void _scrollToBottom() {\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (_scrollController.hasClients) {\n        _scrollController.animateTo(\n          _scrollController.position.maxScrollExtent,\n          duration: const Duration(milliseconds: 50),\n          curve: Curves.easeOut,\n        );\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _timer?.cancel();\n    _scrollController.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: Colors.black,\n      body: Stack(\n        children: [\n          Padding(\n            padding: const EdgeInsets.all(20.0),\n            child: ListView.builder(\n              controller: _scrollController,\n              itemCount: _lines.length + 1,\n              itemBuilder: (context, index) {\n                if (index == _lines.length) {\n                  return _isPanic\n                      ? _buildRebootPrompt()\n                      : const SizedBox.shrink();\n                }\n                return Text(\n                  _lines[index],\n                  style: const TextStyle(\n                    color: Colors.white,\n                    fontFamily: 'JetBrainsMono',\n                    fontSize: 14,\n                  ),\n                );\n              },\n            ),\n          ),\n          IgnorePointer(\n            child: Container(\n              decoration: BoxDecoration(\n                gradient: LinearGradient(\n                  begin: Alignment.topCenter,\n                  end: Alignment.bottomCenter,\n                  colors: [\n                    Colors.white.withOpacity(0.05),\n                    Colors.transparent,\n                    Colors.black.withOpacity(0.05),\n                  ],\n                  stops: const [0, 0.5, 1],\n                ),\n              ),\n              child: _buildScanlines(),\n            ),\n          ),\n          if (_isPanic) const IgnorePointer(child: FlickeringOverlay()),\n          if (_isPanic) IgnorePointer(child: GlitchEffect()),\n        ],\n      ),\n    );\n  }\n\n  Widget _buildScanlines() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        return Column(\n          children: List.generate(\n            (constraints.maxHeight / 3).floor(),\n            (index) =>\n                Container(height: 1, color: Colors.black.withOpacity(0.3)),\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _buildRebootPrompt() {\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 40.0),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          const Text(\n            \"\\n[!] KERNEL PANIC: VFS: Unable to mount root fs\",\n            style: TextStyle(\n              color: Colors.redAccent,\n              fontFamily: 'JetBrainsMono',\n              fontSize: 18,\n              fontWeight: FontWeight.bold,\n            ),\n          ),\n          const SizedBox(height: 20),\n          const Text(\n            \"404 - SYSTEM ERROR\\n------------------\\nTHE REQUESTED PAGE DOES NOT EXIST IN THE CURRENT NAMESPACE.\",\n            style: TextStyle(\n              color: Colors.white,\n              fontFamily: 'JetBrainsMono',\n              fontSize: 14,\n            ),\n          ),\n          const SizedBox(height: 40),\n          MouseRegion(\n            cursor: SystemMouseCursors.click,\n            child: GestureDetector(\n              onTap: () => Navigator.of(context).pushReplacementNamed('/'),\n              child: Container(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 20,\n                  vertical: 10,\n                ),\n                decoration: BoxDecoration(\n                  border: Border.all(color: Colors.white),\n                  color: Colors.transparent,\n                ),\n                child: const Text(\n                  \"REBOOT_SYSTEM_FORCE\",\n                  style: TextStyle(\n                    color: Colors.white,\n                    fontFamily: 'JetBrainsMono',\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass GlitchEffect extends StatefulWidget {\n  const GlitchEffect({super.key});\n\n  @override\n  State<GlitchEffect> createState() => _GlitchEffectState();\n}\n\nclass _GlitchEffectState extends State<GlitchEffect>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n  final Random _random = Random();\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 200),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        if (_random.nextDouble() > 0.1) return const SizedBox.shrink();\n\n        return Stack(\n          children: [\n            Positioned(\n              top: _random.nextDouble() * MediaQuery.of(context).size.height,\n              left: 0,\n              right: 0,\n              child: Container(\n                height: _random.nextDouble() * 20,\n                color: Colors.white.withOpacity(0.1),\n              ),\n            ),\n            Positioned(\n              left: _random.nextDouble() * MediaQuery.of(context).size.width,\n              top: 0,\n              bottom: 0,\n              child: Container(\n                width: _random.nextDouble() * 2,\n                color: Colors.red.withOpacity(0.1),\n              ),\n            ),\n          ],\n        );\n      },\n    );\n  }\n}\n\nclass FlickeringOverlay extends StatefulWidget {\n  const FlickeringOverlay({super.key});\n\n  @override\n  State<FlickeringOverlay> createState() => _FlickeringOverlayState();\n}\n\nclass _FlickeringOverlayState extends State<FlickeringOverlay>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n  final Random _random = Random();\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 100),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedBuilder(\n      animation: _controller,\n      builder: (context, child) {\n        return Container(\n          color: Colors.red.withOpacity(_random.nextDouble() * 0.03),\n        );\n      },\n    );\n  }\n}\n",
  "lib/games/blubber_game.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/scheduler.dart';\nimport 'package:flutter/services.dart';\n\nenum OceanItemType {\n  krill,\n  candy,\n  anglerFish,\n  coffeeCup,\n  crab,\n  rowboat,\n  sailingShip,\n  dessertIsland,\n}\n\nclass WhaleGame extends StatefulWidget {\n  const WhaleGame({super.key});\n\n  @override\n  State<WhaleGame> createState() => _WhaleGameState();\n}\n\nclass _WhaleGameState extends State<WhaleGame>\n    with SingleTickerProviderStateMixin {\n  final AudioPlayer _audioPlayer = AudioPlayer();\n  final FocusNode _focusNode = FocusNode();\n  final Random _rng = Random();\n\n  final List<String> _playlist = [\n    'why_is_it_spicy.m4a',\n    'whale_mail.wav',\n    'ill_have_the_ribs_please.wav',\n    'beached.wav',\n    'sos.wav',\n    'all_aboard_thats_going_aboard.wav',\n    'we_just_need_to_budget_better.wav',\n    'is_that_real_wool.m4a',\n    'wheres_the_boat.wav',\n    'specter.wav',\n    'tightrope.wav',\n    'i_swear_the_fish_was_this_big.wav',\n    'spouted.wav',\n    'before_the_before.wav',\n  ];\n\n  List<String> _musicQueue = [];\n  StreamSubscription? _playerCompleteSubscription;\n\n  late Ticker _ticker;\n  Duration _lastElapsed = Duration.zero;\n  double _worldTime = 0.0;\n\n  // 3D Ocean Arena bounds (-_worldRadius .. +_worldRadius on horizontal X and Z axes)\n  static const double _worldRadius = 1100.0;\n\n  // Whale state on the horizontal sea plane (X = east/west, Z = north/south)\n  double _whaleX = 0.0;\n  double _whaleZ = 0.0;\n  double _whaleHeading = 0.0; // 0 = right/east, pi = left/west, -pi/2 = north, pi/2 = south\n  double _whaleSpeed = 0.0;\n  double _whaleMass = 10.0;\n  double _displayScale = 1.0;\n  double _mouthOpen = 0.25;\n  double _tailPhase = 0.0;\n  double _boostTimer = 0.0;\n  double _boostCooldown = 0.0;\n\n  // Level & Collection Goal (No time limit!)\n  int _score = 0;\n  int _level = 1;\n  int _levelCollected = 0;\n  int _levelGoal = 10;\n  double _celebrationSpoutTimer = 0.0;\n\n  // Input state (Keyboard + Touch Drag anywhere)\n  final Set<LogicalKeyboardKey> _keysPressed = {};\n  int? _dragPointerId;\n  Offset _joystickOrigin = Offset.zero;\n  Offset _joystickDelta = Offset.zero;\n\n  // World entities & sea decorations\n  final List<_OceanEntity> _entities = [];\n  final List<_SwallowingEntity> _swallowing = [];\n  final List<_WaterRipple> _ripples = [];\n  final List<_SpoutDrop> _spoutDrops = [];\n  final List<_FloatingScore> _floatingScores = [];\n  late final List<_SeaDecoration> _seaDecorations;\n  late final List<_WaveCrest> _waveCrests;\n\n  double get _targetScale =>\n      (1.0 + pow((_whaleMass - 10.0) / 24.0, 0.58) * 0.45).clamp(1.0, 4.5);\n\n  int get _unlockedTier {\n    if (_displayScale >= 2.35) return 4;\n    if (_displayScale >= 1.75) return 3;\n    if (_displayScale >= 1.30) return 2;\n    return 1;\n  }\n\n  String get _sizeTitle {\n    switch (_unlockedTier) {\n      case 1:\n        return 'KRILL GULPER';\n      case 2:\n        return 'ABYSS PROWLER';\n      case 3:\n        return 'BOAT SWALLOWER';\n      default:\n        return 'LEVIATHAN';\n    }\n  }\n\n  @override\n  void initState() {\n    super.initState();\n    _setupAudioPlayer();\n    _initSeaEnvironment();\n    _spawnInitialWorld();\n\n    _ticker = createTicker(_onTick)..start();\n\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (mounted) {\n        _focusNode.requestFocus();\n      }\n    });\n  }\n\n  @override\n  void dispose() {\n    _ticker.dispose();\n    _playerCompleteSubscription?.cancel();\n    _focusNode.dispose();\n    _audioPlayer.dispose();\n    super.dispose();\n  }\n\n  void _setupAudioPlayer() {\n    _audioPlayer.setReleaseMode(ReleaseMode.release);\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((_) {\n      _playNextTrack();\n    });\n    _playNextTrack();\n  }\n\n  Future<void> _playNextTrack() async {\n    if (_playlist.isEmpty) return;\n    if (_musicQueue.isEmpty) {\n      _musicQueue = List.of(_playlist)..shuffle();\n    }\n    final nextSong = _musicQueue.removeAt(0);\n    try {\n      await _audioPlayer.setSource(AssetSource('music/blubber/\$nextSong'));\n      await _audioPlayer.setVolume(0.5);\n      await _audioPlayer.resume();\n    } catch (e) {\n      debugPrint('Audio Error: \$e');\n    }\n  }\n\n  void _initSeaEnvironment() {\n    // Coral reefs, kelp forests, starfish, and sandbars across the seabed\n    _seaDecorations = List.generate(75, (i) {\n      return _SeaDecoration(\n        x: (_rng.nextDouble() * 2 - 1) * _worldRadius,\n        z: (_rng.nextDouble() * 2 - 1) * _worldRadius,\n        kind: i % 4, // 0: kelp, 1: coral, 2: starfish, 3: sandbar/clam\n        scale: 0.75 + _rng.nextDouble() * 0.7,\n        phase: _rng.nextDouble() * pi * 2,\n        colorIndex: _rng.nextInt(3),\n      );\n    });\n\n    // Animated whitecap wave crests & seafoam across the surface\n    _waveCrests = List.generate(65, (_) {\n      return _WaveCrest(\n        x: (_rng.nextDouble() * 2 - 1) * _worldRadius,\n        z: (_rng.nextDouble() * 2 - 1) * _worldRadius,\n        width: 28.0 + _rng.nextDouble() * 36.0,\n        phase: _rng.nextDouble() * pi * 2,\n      );\n    });\n  }\n\n  void _resetGame() {\n    setState(() {\n      _whaleX = 0.0;\n      _whaleZ = 0.0;\n      _whaleHeading = 0.0;\n      _whaleMass = 10.0;\n      _displayScale = 1.0;\n      _score = 0;\n      _level = 1;\n      _levelCollected = 0;\n      _levelGoal = 10;\n      _celebrationSpoutTimer = 0.0;\n      _entities.clear();\n      _swallowing.clear();\n      _ripples.clear();\n      _spoutDrops.clear();\n      _floatingScores.clear();\n      _spawnInitialWorld();\n    });\n  }\n\n  void _spawnInitialWorld() {\n    for (int i = 0; i < 38; i++) {\n      _spawnEntityOfType(\n        _rng.nextDouble() < 0.72 ? OceanItemType.krill : OceanItemType.candy,\n        nearCenter: i < 16,\n      );\n    }\n    for (int i = 0; i < 14; i++) {\n      _spawnEntityOfType(\n        i.isEven ? OceanItemType.anglerFish : OceanItemType.coffeeCup,\n      );\n    }\n    for (int i = 0; i < 10; i++) {\n      _spawnEntityOfType(\n        i.isEven ? OceanItemType.crab : OceanItemType.rowboat,\n      );\n    }\n    for (int i = 0; i < 7; i++) {\n      _spawnEntityOfType(\n        i.isEven ? OceanItemType.sailingShip : OceanItemType.dessertIsland,\n      );\n    }\n  }\n\n  void _spawnEntityOfType(OceanItemType type, {bool nearCenter = false}) {\n    final double maxR = nearCenter ? 340.0 : (_worldRadius - 80.0);\n    final double minR = nearCenter ? 75.0 : 120.0;\n    final double angle = _rng.nextDouble() * pi * 2;\n    final double dist = minR + _rng.nextDouble() * (maxR - minR);\n\n    final double x = (_whaleX + cos(angle) * dist).clamp(\n      -_worldRadius + 60,\n      _worldRadius - 60,\n    );\n    final double z = (_whaleZ + sin(angle) * dist).clamp(\n      -_worldRadius + 60,\n      _worldRadius - 60,\n    );\n\n    double requiredScale;\n    double radius;\n    double massGain;\n    int points;\n\n    switch (type) {\n      case OceanItemType.krill:\n        requiredScale = 1.0;\n        radius = 15.0;\n        massGain = 1.8;\n        points = 25;\n        break;\n      case OceanItemType.candy:\n        requiredScale = 1.0;\n        radius = 16.0;\n        massGain = 2.1;\n        points = 40;\n        break;\n      case OceanItemType.anglerFish:\n        requiredScale = 1.30;\n        radius = 25.0;\n        massGain = 4.4;\n        points = 100;\n        break;\n      case OceanItemType.coffeeCup:\n        requiredScale = 1.30;\n        radius = 24.0;\n        massGain = 4.0;\n        points = 90;\n        break;\n      case OceanItemType.crab:\n        requiredScale = 1.75;\n        radius = 35.0;\n        massGain = 8.2;\n        points = 220;\n        break;\n      case OceanItemType.rowboat:\n        requiredScale = 1.75;\n        radius = 38.0;\n        massGain = 9.5;\n        points = 250;\n        break;\n      case OceanItemType.sailingShip:\n        requiredScale = 2.35;\n        radius = 54.0;\n        massGain = 18.0;\n        points = 600;\n        break;\n      case OceanItemType.dessertIsland:\n        requiredScale = 2.35;\n        radius = 60.0;\n        massGain = 22.0;\n        points = 750;\n        break;\n    }\n\n    final bool mobile =\n        type == OceanItemType.krill ||\n        type == OceanItemType.anglerFish ||\n        type == OceanItemType.crab ||\n        type == OceanItemType.rowboat;\n\n    _entities.add(\n      _OceanEntity(\n        type: type,\n        x: x,\n        z: z,\n        heading: _rng.nextDouble() * pi * 2,\n        speed: mobile ? (16.0 + _rng.nextDouble() * 22.0) : 0.0,\n        requiredScale: requiredScale,\n        radius: radius,\n        massGain: massGain,\n        points: points,\n        bobPhase: _rng.nextDouble() * pi * 2,\n        colorVariant: _rng.nextInt(3),\n      ),\n    );\n  }\n\n  void _spawnBlowholeDrops(int count, {bool isLevelUp = false}) {\n    final double blowX = _whaleX + cos(_whaleHeading) * (10.0 * _displayScale);\n    final double blowZ = _whaleZ + sin(_whaleHeading) * (10.0 * _displayScale);\n    for (int i = 0; i < count; i++) {\n      final double a = _rng.nextDouble() * pi * 2;\n      final double spd = (isLevelUp ? 40.0 : 25.0) +\n          _rng.nextDouble() * (isLevelUp ? 95.0 : 55.0);\n      _spoutDrops.add(\n        _SpoutDrop(\n          x: blowX,\n          y: 28.0 * _displayScale,\n          z: blowZ,\n          vx: cos(a) * spd,\n          vy: (isLevelUp ? 190.0 : 135.0) + _rng.nextDouble() * 110.0,\n          vz: sin(a) * spd,\n          life: (isLevelUp ? 0.95 : 0.65) + _rng.nextDouble() * 0.35,\n          isCelebration: isLevelUp,\n        ),\n      );\n    }\n  }\n\n  void _triggerBoost() {\n    if (_boostCooldown > 0) return;\n    setState(() {\n      _boostTimer = 0.65;\n      _boostCooldown = 1.5;\n      _spawnBlowholeDrops(18);\n    });\n    HapticFeedback.lightImpact();\n  }\n\n  void _triggerLevelUpSpout() {\n    _level++;\n    _levelCollected = 0;\n    _levelGoal = 10 + (_level - 1) * 4;\n    _celebrationSpoutTimer = 2.6;\n    _spawnBlowholeDrops(42, isLevelUp: true);\n\n    _ripples.add(\n      _WaterRipple(\n        x: _whaleX,\n        z: _whaleZ,\n        radius: 20.0 * _displayScale,\n        maxRadius: 110.0 * _displayScale,\n        life: 1.2,\n      ),\n    );\n    HapticFeedback.mediumImpact();\n  }\n\n  KeyEventResult _handleKeyEvent(FocusNode node, KeyEvent event) {\n    if (event is KeyDownEvent) {\n      _keysPressed.add(event.logicalKey);\n      if (event.logicalKey == LogicalKeyboardKey.space) {\n        _triggerBoost();\n      }\n    } else if (event is KeyUpEvent) {\n      _keysPressed.remove(event.logicalKey);\n    }\n    return KeyEventResult.handled;\n  }\n\n  void _onTick(Duration elapsed) {\n    final double dt = _lastElapsed == Duration.zero\n        ? 0.016\n        : ((elapsed - _lastElapsed).inMicroseconds / 1000000.0).clamp(\n            0.001,\n            0.05,\n          );\n    _lastElapsed = elapsed;\n\n    setState(() {\n      _worldTime += dt;\n      if (_boostTimer > 0) _boostTimer = max(0, _boostTimer - dt);\n      if (_boostCooldown > 0) _boostCooldown = max(0, _boostCooldown - dt);\n\n      if (_celebrationSpoutTimer > 0) {\n        _celebrationSpoutTimer = max(0, _celebrationSpoutTimer - dt);\n        // Continuous fountain spray during the level-up spout celebration\n        if (_rng.nextDouble() < 0.65) {\n          _spawnBlowholeDrops(4, isLevelUp: true);\n        }\n      }\n\n      _displayScale +=\n          (_targetScale - _displayScale) * (dt * 4.5).clamp(0.0, 1.0);\n\n      _updateWhaleMovement(dt);\n      _updateEntitiesAndSwallowing(dt);\n      _updateEffects(dt);\n    });\n  }\n\n  void _updateWhaleMovement(double dt) {\n    double inputX = 0.0;\n    double inputZ = 0.0;\n\n    if (_keysPressed.contains(LogicalKeyboardKey.keyA) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowLeft)) {\n      inputX -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyD) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowRight)) {\n      inputX += 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyW) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowUp)) {\n      inputZ -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyS) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowDown)) {\n      inputZ += 1.0;\n    }\n\n    if (_dragPointerId != null && _joystickDelta.distance > 0.08) {\n      inputX = _joystickDelta.dx;\n      // Scale Z input to compensate for foreshortened sea plane so screen movement matches finger direction\n      inputZ = _joystickDelta.dy / _Whale3DPainter.kSeaTilt;\n    }\n\n    final double inputMag = sqrt(inputX * inputX + inputZ * inputZ);\n    final double maxSpeed =\n        (205.0 + (_displayScale - 1.0) * 34.0) * (_boostTimer > 0 ? 1.65 : 1.0);\n\n    if (inputMag > 0.05) {\n      final double targetHeading = atan2(inputZ, inputX);\n      double diff = targetHeading - _whaleHeading;\n      while (diff > pi) {\n        diff -= pi * 2;\n      }\n      while (diff < -pi) {\n        diff += pi * 2;\n      }\n      _whaleHeading += diff * (dt * 9.5).clamp(0.0, 1.0);\n      _whaleSpeed = maxSpeed * inputMag.clamp(0.25, 1.0);\n    } else {\n      _whaleSpeed *= pow(0.08, dt).toDouble();\n    }\n\n    _whaleX += cos(_whaleHeading) * _whaleSpeed * dt;\n    _whaleZ += sin(_whaleHeading) * _whaleSpeed * dt;\n\n    final double limit = _worldRadius - 50.0;\n    _whaleX = _whaleX.clamp(-limit, limit);\n    _whaleZ = _whaleZ.clamp(-limit, limit);\n\n    _tailPhase += dt * (4.5 + (_whaleSpeed / 42.0));\n\n    if (_whaleSpeed > 25.0 && _rng.nextDouble() < 0.35) {\n      _ripples.add(\n        _WaterRipple(\n          x: _whaleX - cos(_whaleHeading) * 34.0 * _displayScale,\n          z: _whaleZ - sin(_whaleHeading) * 34.0 * _displayScale,\n          radius: 14.0 * _displayScale,\n          maxRadius: 58.0 * _displayScale,\n          life: 1.0,\n        ),\n      );\n    }\n  }\n\n  void _updateEntitiesAndSwallowing(double dt) {\n    final double mouthX = _whaleX + cos(_whaleHeading) * (28.0 * _displayScale);\n    final double mouthZ = _whaleZ + sin(_whaleHeading) * (28.0 * _displayScale);\n    final double swallowRadius = 48.0 * _displayScale;\n\n    bool gulpingAny = false;\n    final List<_OceanEntity> newlySwallowed = [];\n\n    for (final e in _entities) {\n      if (e.speed > 0) {\n        e.x += cos(e.heading) * e.speed * dt;\n        e.z += sin(e.heading) * e.speed * dt;\n        if (e.x.abs() > _worldRadius - 65 || e.z.abs() > _worldRadius - 65) {\n          e.heading += pi + (_rng.nextDouble() - 0.5) * 0.5;\n        }\n      }\n\n      final double dx = e.x - mouthX;\n      final double dz = e.z - mouthZ;\n      final double dist = sqrt(dx * dx + dz * dz);\n\n      final bool canEat = _displayScale + 0.02 >= e.requiredScale;\n\n      if (canEat) {\n        if (dist < swallowRadius * 1.45) {\n          gulpingAny = true;\n          final double pullSpeed = 245.0 * _displayScale;\n          if (dist > 1.0) {\n            e.x -= (dx / dist) * pullSpeed * dt;\n            e.z -= (dz / dist) * pullSpeed * dt;\n          }\n        }\n        if (dist < swallowRadius * 0.80) {\n          newlySwallowed.add(e);\n        }\n      } else {\n        final double minSep = 32.0 * _displayScale + e.radius * 0.7;\n        final double bodyDx = e.x - _whaleX;\n        final double bodyDz = e.z - _whaleZ;\n        final double bodyDist = sqrt(bodyDx * bodyDx + bodyDz * bodyDz);\n        if (bodyDist < minSep && bodyDist > 0.01) {\n          final double push = (minSep - bodyDist) * 0.5;\n          e.x += (bodyDx / bodyDist) * push;\n          e.z += (bodyDz / bodyDist) * push;\n        }\n      }\n    }\n\n    for (final e in newlySwallowed) {\n      _entities.remove(e);\n      _swallowing.add(_SwallowingEntity(entity: e, progress: 0.0));\n      _whaleMass += e.massGain;\n      _score += e.points;\n      _levelCollected++;\n\n      _floatingScores.add(\n        _FloatingScore(\n          text: '+\${e.points}',\n          x: _whaleX,\n          y: 35.0 * _displayScale,\n          z: _whaleZ,\n          life: 0.9,\n        ),\n      );\n\n      _ripples.add(\n        _WaterRipple(\n          x: mouthX,\n          z: mouthZ,\n          radius: 10.0,\n          maxRadius: 46.0 * _displayScale,\n          life: 0.85,\n        ),\n      );\n\n      // Check if we reached the collection goal for this level!\n      if (_levelCollected >= _levelGoal) {\n        _triggerLevelUpSpout();\n      }\n    }\n\n    for (final s in _swallowing) {\n      s.progress += dt * 3.4;\n      gulpingAny = true;\n    }\n    _swallowing.removeWhere((s) => s.progress >= 1.0);\n\n    final double targetMouth = gulpingAny ? 1.0 : 0.25;\n    _mouthOpen += (targetMouth - _mouthOpen) * (dt * 10.0).clamp(0.0, 1.0);\n\n    if (_entities.length < 38) {\n      final int tier = _unlockedTier;\n      if (_rng.nextDouble() < 0.55) {\n        _spawnEntityOfType(\n          _rng.nextBool() ? OceanItemType.krill : OceanItemType.candy,\n        );\n      } else if (tier >= 2 && _rng.nextDouble() < 0.5) {\n        _spawnEntityOfType(\n          _rng.nextBool() ? OceanItemType.anglerFish : OceanItemType.coffeeCup,\n        );\n      } else if (tier >= 3 && _rng.nextDouble() < 0.5) {\n        _spawnEntityOfType(\n          _rng.nextBool() ? OceanItemType.crab : OceanItemType.rowboat,\n        );\n      } else {\n        _spawnEntityOfType(\n          _rng.nextBool()\n              ? OceanItemType.sailingShip\n              : OceanItemType.dessertIsland,\n        );\n      }\n    }\n  }\n\n  void _updateEffects(double dt) {\n    for (final r in _ripples) {\n      r.life -= dt * 1.1;\n      r.radius += (r.maxRadius - r.radius) * dt * 3.2;\n    }\n    _ripples.removeWhere((r) => r.life <= 0);\n\n    for (final d in _spoutDrops) {\n      d.x += d.vx * dt;\n      d.y += d.vy * dt;\n      d.z += d.vz * dt;\n      d.vy -= 310.0 * dt;\n      d.life -= dt;\n    }\n    _spoutDrops.removeWhere((d) => d.life <= 0 || d.y < 0);\n\n    for (final fs in _floatingScores) {\n      fs.y += 45.0 * dt;\n      fs.life -= dt;\n    }\n    _floatingScores.removeWhere((fs) => fs.life <= 0);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final double goalProgress =\n        (_levelCollected / max(1, _levelGoal)).clamp(0.0, 1.0);\n\n    return Scaffold(\n      backgroundColor: const Color(0xFF044A7C),\n      appBar: AppBar(\n        backgroundColor: const Color(0xFF032B4A),\n        elevation: 0,\n        leading: const BackButton(color: Colors.white),\n        title: const Text(\n          'floppy_whale.sh',\n          style: TextStyle(\n            color: Colors.white,\n            fontFamily: 'JetBrainsMono',\n            fontSize: 15,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        centerTitle: true,\n        actions: [\n          IconButton(\n            tooltip: 'Reset Ocean',\n            onPressed: _resetGame,\n            icon: const Icon(Icons.refresh, color: Colors.white70, size: 20),\n          ),\n        ],\n      ),\n      body: KeyboardListener(\n        focusNode: _focusNode,\n        autofocus: true,\n        onKeyEvent: (event) => _handleKeyEvent(_focusNode, event),\n        child: LayoutBuilder(\n          builder: (context, constraints) {\n            final bool isCompact = constraints.maxWidth < 700;\n\n            return Stack(\n              fit: StackFit.expand,\n              children: [\n                // 3D Isometric/Perspective Ocean Canvas\n                Listener(\n                  behavior: HitTestBehavior.opaque,\n                  onPointerDown: (event) {\n                    _focusNode.requestFocus();\n                    if (_dragPointerId == null) {\n                      setState(() {\n                        _dragPointerId = event.pointer;\n                        _joystickOrigin = event.localPosition;\n                        _joystickDelta = Offset.zero;\n                      });\n                    }\n                  },\n                  onPointerMove: (event) {\n                    if (event.pointer == _dragPointerId) {\n                      setState(() {\n                        const double maxDrag = 60.0;\n                        final Offset raw =\n                            event.localPosition - _joystickOrigin;\n                        final double dist = raw.distance;\n                        if (dist > 0.001) {\n                          final double clamped = min(dist, maxDrag);\n                          _joystickDelta = (raw / dist) * (clamped / maxDrag);\n                        } else {\n                          _joystickDelta = Offset.zero;\n                        }\n                      });\n                    }\n                  },\n                  onPointerUp: (event) {\n                    if (event.pointer == _dragPointerId) {\n                      setState(() {\n                        _dragPointerId = null;\n                        _joystickDelta = Offset.zero;\n                      });\n                    }\n                  },\n                  onPointerCancel: (event) {\n                    if (event.pointer == _dragPointerId) {\n                      setState(() {\n                        _dragPointerId = null;\n                        _joystickDelta = Offset.zero;\n                      });\n                    }\n                  },\n                  child: CustomPaint(\n                    painter: _Whale3DPainter(\n                      worldTime: _worldTime,\n                      whaleX: _whaleX,\n                      whaleZ: _whaleZ,\n                      whaleHeading: _whaleHeading,\n                      whaleScale: _displayScale,\n                      mouthOpen: _mouthOpen,\n                      tailPhase: _tailPhase,\n                      celebrationSpoutTimer: _celebrationSpoutTimer,\n                      entities: _entities,\n                      swallowing: _swallowing,\n                      ripples: _ripples,\n                      spoutDrops: _spoutDrops,\n                      floatingScores: _floatingScores,\n                      seaDecorations: _seaDecorations,\n                      waveCrests: _waveCrests,\n                    ),\n                  ),\n                ),\n\n                // Top HUD: Score, Size Class, and Level Collection Goal Bar (No Timer)\n                Positioned(\n                  top: 12,\n                  left: 14,\n                  right: 14,\n                  child: IgnorePointer(\n                    child: Wrap(\n                      alignment: WrapAlignment.spaceBetween,\n                      crossAxisAlignment: WrapCrossAlignment.center,\n                      spacing: 8,\n                      runSpacing: 6,\n                      children: [\n                        Container(\n                          padding: const EdgeInsets.symmetric(\n                            horizontal: 14,\n                            vertical: 10,\n                          ),\n                          decoration: BoxDecoration(\n                            color: const Color(0xFF03233C).withValues(alpha: 0.82),\n                            border: Border.all(\n                              color: kAccentColor.withValues(alpha: 0.85),\n                              width: 1.8,\n                            ),\n                            borderRadius: BorderRadius.circular(10),\n                          ),\n                          child: Column(\n                            crossAxisAlignment: CrossAxisAlignment.start,\n                            mainAxisSize: MainAxisSize.min,\n                            children: [\n                              Text(\n                                'SCORE: \$_score  |  SIZE: \${_displayScale.toStringAsFixed(2)}x',\n                                style: const TextStyle(\n                                  color: Colors.white,\n                                  fontFamily: 'JetBrainsMono',\n                                  fontWeight: FontWeight.bold,\n                                  fontSize: 15,\n                                ),\n                              ),\n                              const SizedBox(height: 3),\n                              Text(\n                                'CLASS: \$_sizeTitle (LVL \$_level)',\n                                style: const TextStyle(\n                                  color: kAccentColor,\n                                  fontFamily: 'JetBrainsMono',\n                                  fontWeight: FontWeight.bold,\n                                  fontSize: 12,\n                                ),\n                              ),\n                              const SizedBox(height: 6),\n                              Row(\n                                mainAxisSize: MainAxisSize.min,\n                                children: [\n                                  Text(\n                                    'GOAL: \$_levelCollected/\$_levelGoal',\n                                    style: const TextStyle(\n                                      color: Colors.white70,\n                                      fontFamily: 'JetBrainsMono',\n                                      fontSize: 11,\n                                    ),\n                                  ),\n                                  const SizedBox(width: 8),\n                                  SizedBox(\n                                    width: 110,\n                                    height: 8,\n                                    child: ClipRRect(\n                                      borderRadius: BorderRadius.circular(4),\n                                      child: LinearProgressIndicator(\n                                        value: goalProgress,\n                                        backgroundColor: Colors.white12,\n                                        valueColor:\n                                            const AlwaysStoppedAnimation<Color>(\n                                              Color(0xFF38BDF8),\n                                            ),\n                                      ),\n                                    ),\n                                  ),\n                                ],\n                              ),\n                            ],\n                          ),\n                        ),\n                        Container(\n                          padding: const EdgeInsets.symmetric(\n                            horizontal: 12,\n                            vertical: 7,\n                          ),\n                          decoration: BoxDecoration(\n                            color: const Color(0xFF03233C).withValues(alpha: 0.72),\n                            borderRadius: BorderRadius.circular(8),\n                            border: Border.all(color: Colors.white24),\n                          ),\n                          child: Text(\n                            isCompact\n                                ? 'DRAG ANYWHERE TO SWIM & GULP KRILL'\n                                : 'DRAG / WASD / ARROWS: Swim & Gulp  |  SPACE: Spout Boost',\n                            style: const TextStyle(\n                              color: Colors.white70,\n                              fontFamily: 'JetBrainsMono',\n                              fontSize: 11,\n                            ),\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n\n                // Bottom-Right Spout Boost Button\n                Positioned(\n                  right: isCompact ? 18 : 28,\n                  bottom: isCompact ? 20 : 28,\n                  child: GestureDetector(\n                    key: const Key('spout_boost_button'),\n                    onTap: _triggerBoost,\n                    child: Container(\n                      width: isCompact ? 76 : 84,\n                      height: isCompact ? 76 : 84,\n                      decoration: BoxDecoration(\n                        shape: BoxShape.circle,\n                        color: _boostCooldown > 0\n                            ? const Color(0xFF1E3A5F).withValues(alpha: 0.65)\n                            : const Color(0xFF0284C7).withValues(alpha: 0.85),\n                        border: Border.all(\n                          color: Colors.white.withValues(alpha: 0.85),\n                          width: 2.5,\n                        ),\n                        boxShadow: [\n                          BoxShadow(\n                            color: const Color(0xFF38BDF8).withValues(\n                              alpha: _boostCooldown > 0 ? 0.15 : 0.55,\n                            ),\n                            blurRadius: 12,\n                            spreadRadius: 1,\n                          ),\n                        ],\n                      ),\n                      child: const Center(\n                        child: Column(\n                          mainAxisSize: MainAxisSize.min,\n                          children: [\n                            Text(\n                              'SPOUT',\n                              style: TextStyle(\n                                color: Colors.white,\n                                fontFamily: 'JetBrainsMono',\n                                fontWeight: FontWeight.bold,\n                                fontSize: 13,\n                              ),\n                            ),\n                            Text(\n                              'BOOST',\n                              style: TextStyle(\n                                color: Colors.white70,\n                                fontFamily: 'JetBrainsMono',\n                                fontSize: 10,\n                              ),\n                            ),\n                          ],\n                        ),\n                      ),\n                    ),\n                  ),\n                ),\n              ],\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass _ProjectedPoint {\n  final Offset screen;\n  final double scale;\n  final double depth;\n\n  const _ProjectedPoint({\n    required this.screen,\n    required this.scale,\n    required this.depth,\n  });\n}\n\nclass _Whale3DPainter extends CustomPainter {\n  // Horizontal sea-plane foreshortening factor (~36-degree elevated 3D view)\n  static const double kSeaTilt = 0.58;\n\n  final double worldTime;\n  final double whaleX;\n  final double whaleZ;\n  final double whaleHeading;\n  final double whaleScale;\n  final double mouthOpen;\n  final double tailPhase;\n  final double celebrationSpoutTimer;\n  final List<_OceanEntity> entities;\n  final List<_SwallowingEntity> swallowing;\n  final List<_WaterRipple> ripples;\n  final List<_SpoutDrop> spoutDrops;\n  final List<_FloatingScore> floatingScores;\n  final List<_SeaDecoration> seaDecorations;\n  final List<_WaveCrest> waveCrests;\n\n  _Whale3DPainter({\n    required this.worldTime,\n    required this.whaleX,\n    required this.whaleZ,\n    required this.whaleHeading,\n    required this.whaleScale,\n    required this.mouthOpen,\n    required this.tailPhase,\n    required this.celebrationSpoutTimer,\n    required this.entities,\n    required this.swallowing,\n    required this.ripples,\n    required this.spoutDrops,\n    required this.floatingScores,\n    required this.seaDecorations,\n    required this.waveCrests,\n  });\n\n  // Consistent 3D Horizontal Sea-Plane Projection:\n  // (wx, wz) is the horizontal ocean plane, wy is vertical height above water.\n  // Because wy always projects straight up (-dy) and (wx, wz) projects onto the\n  // foreshortened horizontal plane, moving in any direction looks like swimming\n  // across a flat 3D sea rather than swimming up and down!\n  _ProjectedPoint _project(\n    Size size,\n    double wx,\n    double wy,\n    double wz,\n  ) {\n    final double camZoom = 1.0 / (0.88 + (whaleScale - 1.0) * 0.36);\n    final double relX = (wx - whaleX) * camZoom;\n    final double relZ = (wz - whaleZ) * camZoom;\n    final double relY = wy * camZoom;\n\n    // Gentle perspective depth factor across the horizontal plane\n    const double focal = 1150.0;\n    final double depth = (focal + relZ * 0.35).clamp(400.0, 2600.0);\n    final double persp = focal / depth;\n\n    final double sx = size.width * 0.5 + relX * persp;\n    final double sy = size.height * 0.52 + (relZ * kSeaTilt - relY) * persp;\n\n    return _ProjectedPoint(\n      screen: Offset(sx, sy),\n      scale: persp * camZoom,\n      depth: depth,\n    );\n  }\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    _drawRichSeaEnvironment(canvas, size);\n    _drawWaterRipples(canvas, size);\n\n    // Depth-sorted 3D objects on the horizontal sea surface\n    final List<_DepthDrawable> drawables = [];\n\n    for (final e in entities) {\n      final p = _project(size, e.x, 0, e.z);\n      if (p.screen.dx < -130 ||\n          p.screen.dx > size.width + 130 ||\n          p.screen.dy < -130 ||\n          p.screen.dy > size.height + 130) {\n        continue;\n      }\n      drawables.add(\n        _DepthDrawable(\n          depth: p.depth,\n          draw: (c) => _drawOceanEntity3D(c, size, e, p, swallowFactor: 0.0),\n        ),\n      );\n    }\n\n    for (final s in swallowing) {\n      final double mouthX =\n          whaleX + cos(whaleHeading) * (28.0 * whaleScale * (1.0 - s.progress * 0.5));\n      final double mouthZ =\n          whaleZ + sin(whaleHeading) * (28.0 * whaleScale * (1.0 - s.progress * 0.5));\n      final double ix = s.entity.x + (mouthX - s.entity.x) * s.progress;\n      final double iz = s.entity.z + (mouthZ - s.entity.z) * s.progress;\n      final double iy = -16.0 * s.progress;\n      final p = _project(size, ix, iy, iz);\n      drawables.add(\n        _DepthDrawable(\n          depth: p.depth - 2.0,\n          draw: (c) => _drawOceanEntity3D(\n            c,\n            size,\n            s.entity,\n            p,\n            swallowFactor: s.progress,\n          ),\n        ),\n      );\n    }\n\n    final double breachHop = celebrationSpoutTimer > 0\n        ? sin(celebrationSpoutTimer * 7.5).abs() * 14.0 * whaleScale\n        : 0.0;\n    final whaleProj = _project(size, whaleX, breachHop, whaleZ);\n    drawables.add(\n      _DepthDrawable(\n        depth: whaleProj.depth,\n        draw: (c) => _draw3DCartoonWhale(c, size, whaleProj, breachHop),\n      ),\n    );\n\n    drawables.sort((a, b) => b.depth.compareTo(a.depth));\n    for (final d in drawables) {\n      d.draw(canvas);\n    }\n\n    _drawSpoutDrops(canvas, size);\n    _drawFloatingScores(canvas, size);\n  }\n\n  void _drawRichSeaEnvironment(Canvas canvas, Size size) {\n    final Rect full = Offset.zero & size;\n\n    // 1. Vibrant tropical/temperate cartoon ocean water gradient\n    final Paint seaGrad = Paint()\n      ..shader = const LinearGradient(\n        begin: Alignment.topCenter,\n        end: Alignment.bottomCenter,\n        colors: [\n          Color(0xFF03406A),\n          Color(0xFF056699),\n          Color(0xFF0883B8),\n          Color(0xFF045380),\n        ],\n        stops: [0.0, 0.35, 0.72, 1.0],\n      ).createShader(full);\n    canvas.drawRect(full, seaGrad);\n\n    // 2. Submerged seabed reefs, swaying kelp, coral & starfish (parallaxes at wy = -48)\n    for (final dec in seaDecorations) {\n      final p = _project(size, dec.x, -48.0, dec.z);\n      if (p.screen.dx < -90 ||\n          p.screen.dx > size.width + 90 ||\n          p.screen.dy < -90 ||\n          p.screen.dy > size.height + 90) {\n        continue;\n      }\n      final double s = p.scale * dec.scale;\n      final Offset c = p.screen;\n\n      if (dec.kind == 0) {\n        // Swaying underwater kelp fronds\n        final Paint kelpPaint = Paint()\n          ..color = const Color(0xFF0D9488).withValues(alpha: 0.38)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 5.0 * s\n          ..strokeCap = StrokeCap.round;\n        for (int frond = -1; frond <= 1; frond++) {\n          final double sway = sin(worldTime * 2.2 + dec.phase + frond) * 8.0 * s;\n          final Path kPath = Path()\n            ..moveTo(c.dx + frond * 8 * s, c.dy)\n            ..quadraticBezierTo(\n              c.dx + frond * 8 * s + sway,\n              c.dy - 18 * s,\n              c.dx + frond * 10 * s - sway * 0.5,\n              c.dy - 36 * s,\n            );\n          canvas.drawPath(kPath, kelpPaint);\n        }\n      } else if (dec.kind == 1) {\n        // Submerged coral reef cluster\n        final Color coralColor = dec.colorIndex == 0\n            ? const Color(0xFFF43F5E)\n            : (dec.colorIndex == 1\n                ? const Color(0xFFF97316)\n                : const Color(0xFFA855F7));\n        canvas.drawOval(\n          Rect.fromCenter(center: c, width: 38 * s, height: 22 * s),\n          Paint()..color = coralColor.withValues(alpha: 0.25),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c + Offset(8 * s, -4 * s),\n            width: 22 * s,\n            height: 14 * s,\n          ),\n          Paint()..color = coralColor.withValues(alpha: 0.32),\n        );\n      } else if (dec.kind == 2) {\n        // Seafloor starfish silhouette\n        final Path star = Path();\n        for (int pIdx = 0; pIdx < 10; pIdx++) {\n          final double a = dec.phase + pIdx * pi / 5;\n          final double r = (pIdx.isEven ? 14.0 : 6.0) * s;\n          final Offset pt = c + Offset(cos(a) * r, sin(a) * r * kSeaTilt);\n          if (pIdx == 0) {\n            star.moveTo(pt.dx, pt.dy);\n          } else {\n            star.lineTo(pt.dx, pt.dy);\n          }\n        }\n        star.close();\n        canvas.drawPath(\n          star,\n          Paint()..color = const Color(0xFFFBBF24).withValues(alpha: 0.24),\n        );\n      } else {\n        // Shimmering caustic ring on the water surface\n        final double pulse = 1.0 + 0.15 * sin(worldTime * 2.0 + dec.phase);\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c,\n            width: 56 * s * pulse,\n            height: 56 * s * kSeaTilt * pulse,\n          ),\n          Paint()\n            ..color = const Color(0xFF7DD3FC).withValues(alpha: 0.15)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = 2.2 * s,\n        );\n      }\n    }\n\n    // 3. Animated cartoon ocean wave crests & seafoam on the water plane (wy = 0)\n    final Paint wavePaint = Paint()\n      ..color = const Color(0xFFE0F2FE).withValues(alpha: 0.32)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.4\n      ..strokeCap = StrokeCap.round;\n\n    for (final wc in waveCrests) {\n      final double driftX = wc.x + sin(worldTime * 0.8 + wc.phase) * 18.0;\n      final p = _project(size, driftX, 0, wc.z);\n      if (p.screen.dx < -80 ||\n          p.screen.dx > size.width + 80 ||\n          p.screen.dy < -80 ||\n          p.screen.dy > size.height + 80) {\n        continue;\n      }\n      final double w = wc.width * p.scale;\n      final Offset c = p.screen;\n      final Path crest = Path()\n        ..moveTo(c.dx - w * 0.5, c.dy)\n        ..quadraticBezierTo(c.dx - w * 0.25, c.dy - 5 * p.scale, c.dx, c.dy)\n        ..quadraticBezierTo(\n          c.dx + w * 0.25,\n          c.dy - 5 * p.scale,\n          c.dx + w * 0.5,\n          c.dy,\n        );\n      canvas.drawPath(crest, wavePaint);\n    }\n  }\n\n  void _drawWaterRipples(Canvas canvas, Size size) {\n    for (final r in ripples) {\n      final p = _project(size, r.x, 0, r.z);\n      final double rx = r.radius * p.scale;\n      final double ry = rx * kSeaTilt;\n      canvas.drawOval(\n        Rect.fromCenter(center: p.screen, width: rx * 2, height: ry * 2),\n        Paint()\n          ..color = Colors.white.withValues(\n            alpha: (r.life * 0.45).clamp(0.0, 1.0),\n          )\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 2.2,\n      );\n    }\n  }\n\n  void _drawOceanEntity3D(\n    Canvas canvas,\n    Size size,\n    _OceanEntity e,\n    _ProjectedPoint p, {\n    required double swallowFactor,\n  }) {\n    final double s = p.scale * (1.0 - swallowFactor * 0.78);\n    if (s <= 0.02) return;\n\n    final double bob = sin(worldTime * 3.2 + e.bobPhase) * 3.0 * s;\n    final Offset pos = p.screen + Offset(0, bob);\n    final bool isEdible = whaleScale + 0.02 >= e.requiredScale;\n\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = (2.2 * s).clamp(1.2, 3.2);\n\n    // Shadow on the seabed below\n    final _ProjectedPoint shadowProj = _project(size, e.x, -26, e.z);\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: shadowProj.screen,\n        width: e.radius * 1.6 * s,\n        height: e.radius * 1.6 * kSeaTilt * s,\n      ),\n      Paint()..color = Colors.black.withValues(alpha: 0.24),\n    );\n\n    // Horizontal waterline ring showing whether item is currently edible\n    if (swallowFactor == 0.0) {\n      canvas.drawOval(\n        Rect.fromCenter(\n          center: p.screen + Offset(0, 3 * s),\n          width: e.radius * 2.1 * s,\n          height: e.radius * 2.1 * kSeaTilt * s,\n        ),\n        Paint()\n          ..color = isEdible\n              ? const Color(0xFF4ADE80).withValues(alpha: 0.42)\n              : const Color(0xFFF87171).withValues(alpha: 0.28)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 1.8,\n      );\n    }\n\n    canvas.save();\n    canvas.translate(pos.dx, pos.dy);\n\n    switch (e.type) {\n      case OceanItemType.krill:\n        for (int k = 0; k < 3; k++) {\n          final Offset offset = Offset(\n            (k - 1) * 10 * s,\n            (k == 1 ? -4 : 3) * s,\n          );\n          canvas.save();\n          canvas.translate(offset.dx, offset.dy);\n          final RRect body = RRect.fromRectAndRadius(\n            Rect.fromCenter(center: Offset.zero, width: 15 * s, height: 8 * s),\n            Radius.circular(4 * s),\n          );\n          canvas.drawRRect(body, Paint()..color = const Color(0xFFFB7185));\n          canvas.drawRRect(body, outline);\n          canvas.drawCircle(\n            Offset(5 * s, -1.5 * s),\n            1.8 * s,\n            Paint()..color = Colors.black,\n          );\n          canvas.restore();\n        }\n        break;\n\n      case OceanItemType.candy:\n        final RRect candyRect = RRect.fromRectAndRadius(\n          Rect.fromCenter(center: Offset.zero, width: 24 * s, height: 14 * s),\n          Radius.circular(5 * s),\n        );\n        canvas.drawRRect(\n          candyRect,\n          Paint()\n            ..color = e.colorVariant == 0\n                ? const Color(0xFFE11D48)\n                : const Color(0xFFA855F7),\n        );\n        canvas.drawRRect(candyRect, outline);\n        canvas.drawCircle(\n          Offset(-4 * s, -2 * s),\n          2.5 * s,\n          Paint()..color = Colors.white.withValues(alpha: 0.7),\n        );\n        break;\n\n      case OceanItemType.anglerFish:\n        final RRect fishBody = RRect.fromRectAndRadius(\n          Rect.fromCenter(center: Offset.zero, width: 38 * s, height: 26 * s),\n          Radius.circular(13 * s),\n        );\n        canvas.drawRRect(fishBody, Paint()..color = const Color(0xFF312E81));\n        canvas.drawRRect(fishBody, outline);\n        final Path stalk = Path()\n          ..moveTo(8 * s, -11 * s)\n          ..quadraticBezierTo(20 * s, -26 * s, 24 * s, -15 * s);\n        canvas.drawPath(stalk, outline);\n        canvas.drawCircle(\n          Offset(24 * s, -15 * s),\n          6.5 * s,\n          Paint()..color = const Color(0xFFFDE047).withValues(alpha: 0.45),\n        );\n        canvas.drawCircle(\n          Offset(24 * s, -15 * s),\n          3.5 * s,\n          Paint()..color = const Color(0xFFFEF08A),\n        );\n        canvas.drawCircle(\n          Offset(9 * s, -4 * s),\n          4.2 * s,\n          Paint()..color = Colors.white,\n        );\n        canvas.drawCircle(\n          Offset(10 * s, -4 * s),\n          2.0 * s,\n          Paint()..color = Colors.black,\n        );\n        break;\n\n      case OceanItemType.coffeeCup:\n        final RRect cup = RRect.fromRectAndRadius(\n          Rect.fromCenter(center: Offset.zero, width: 26 * s, height: 28 * s),\n          Radius.circular(5 * s),\n        );\n        canvas.drawRRect(cup, Paint()..color = const Color(0xFFEF4444));\n        canvas.drawRRect(cup, outline);\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, -11 * s),\n            width: 24 * s,\n            height: 8 * s,\n          ),\n          Paint()..color = const Color(0xFF3E2723),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, -11 * s),\n            width: 24 * s,\n            height: 8 * s,\n          ),\n          outline,\n        );\n        break;\n\n      case OceanItemType.crab:\n        final RRect shell = RRect.fromRectAndRadius(\n          Rect.fromCenter(center: Offset.zero, width: 46 * s, height: 28 * s),\n          Radius.circular(14 * s),\n        );\n        canvas.drawRRect(shell, Paint()..color = const Color(0xFFEA580C));\n        canvas.drawRRect(shell, outline);\n        canvas.drawCircle(\n          Offset(-24 * s, -11 * s),\n          8.5 * s,\n          Paint()..color = const Color(0xFFDC2626),\n        );\n        canvas.drawCircle(Offset(-24 * s, -11 * s), 8.5 * s, outline);\n        canvas.drawCircle(\n          Offset(24 * s, -11 * s),\n          8.5 * s,\n          Paint()..color = const Color(0xFFDC2626),\n        );\n        canvas.drawCircle(Offset(24 * s, -11 * s), 8.5 * s, outline);\n        canvas.drawCircle(\n          Offset(-8 * s, -15 * s),\n          4 * s,\n          Paint()..color = Colors.white,\n        );\n        canvas.drawCircle(\n          Offset(8 * s, -15 * s),\n          4 * s,\n          Paint()..color = Colors.white,\n        );\n        canvas.drawCircle(\n          Offset(-8 * s, -15 * s),\n          1.8 * s,\n          Paint()..color = Colors.black,\n        );\n        canvas.drawCircle(\n          Offset(8 * s, -15 * s),\n          1.8 * s,\n          Paint()..color = Colors.black,\n        );\n        break;\n\n      case OceanItemType.rowboat:\n        final Path hull = Path()\n          ..moveTo(-34 * s, -6 * s)\n          ..lineTo(34 * s, -6 * s)\n          ..lineTo(24 * s, 13 * s)\n          ..lineTo(-24 * s, 13 * s)\n          ..close();\n        canvas.drawPath(hull, Paint()..color = const Color(0xFF92400E));\n        canvas.drawPath(hull, outline);\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, -6 * s),\n            width: 66 * s,\n            height: 15 * s,\n          ),\n          Paint()..color = const Color(0xFFD97706),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, -6 * s),\n            width: 66 * s,\n            height: 15 * s,\n          ),\n          outline,\n        );\n        break;\n\n      case OceanItemType.sailingShip:\n        final Path shipHull = Path()\n          ..moveTo(-48 * s, 0)\n          ..lineTo(48 * s, 0)\n          ..lineTo(34 * s, 20 * s)\n          ..lineTo(-34 * s, 20 * s)\n          ..close();\n        canvas.drawPath(shipHull, Paint()..color = const Color(0xFF78350F));\n        canvas.drawPath(shipHull, outline);\n        canvas.drawLine(\n          Offset.zero,\n          Offset(0, -54 * s),\n          Paint()\n            ..color = const Color(0xFF451A03)\n            ..strokeWidth = 4 * s,\n        );\n        final Path sail = Path()\n          ..moveTo(0, -50 * s)\n          ..quadraticBezierTo(34 * s, -28 * s, 0, -10 * s)\n          ..close();\n        canvas.drawPath(sail, Paint()..color = Colors.white);\n        canvas.drawPath(sail, outline);\n        break;\n\n      case OceanItemType.dessertIsland:\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, 6 * s),\n            width: 92 * s,\n            height: 42 * s,\n          ),\n          Paint()..color = const Color(0xFFFDE68A),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: Offset(0, 6 * s),\n            width: 92 * s,\n            height: 42 * s,\n          ),\n          outline,\n        );\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(0, 4 * s),\n            width: 72 * s,\n            height: 50 * s,\n          ),\n          pi,\n          pi,\n          true,\n          Paint()..color = const Color(0xFFF472B6),\n        );\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(0, 4 * s),\n            width: 72 * s,\n            height: 50 * s,\n          ),\n          pi,\n          pi,\n          true,\n          outline,\n        );\n        canvas.drawCircle(\n          Offset(0, -24 * s),\n          8.5 * s,\n          Paint()..color = const Color(0xFFE11D48),\n        );\n        canvas.drawCircle(Offset(0, -24 * s), 8.5 * s, outline);\n        break;\n    }\n\n    canvas.restore();\n  }\n\n  void _draw3DCartoonWhale(\n    Canvas canvas,\n    Size size,\n    _ProjectedPoint whaleProj,\n    double breachHop,\n  ) {\n    final double s = whaleProj.scale * whaleScale;\n    final Offset center = whaleProj.screen;\n\n    // Deep 3D shadow on the ocean floor beneath the whale\n    final _ProjectedPoint shadowProj = _project(size, whaleX, -32, whaleZ);\n    canvas.save();\n    canvas.translate(shadowProj.screen.dx, shadowProj.screen.dy);\n    canvas.rotate(whaleHeading);\n    canvas.drawOval(\n      Rect.fromCenter(center: Offset.zero, width: 115 * s, height: 64 * s),\n      Paint()..color = Colors.black.withValues(alpha: 0.35),\n    );\n    canvas.restore();\n\n    canvas.save();\n    canvas.translate(center.dx, center.dy);\n    canvas.rotate(whaleHeading);\n\n    const Color whaleBlue = Color(0xFF1D4ED8);\n    const Color whaleHighlight = Color(0xFF60A5FA);\n    const Color whaleBelly = Color(0xFFE0F2FE);\n    const Color mawDark = Color(0xFF090D16);\n    const Color tonguePink = Color(0xFFFB7185);\n\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0B132B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = (2.8 * s).clamp(1.8, 4.2)\n      ..strokeJoin = StrokeJoin.round;\n\n    // Animated swishing tail fluke behind body\n    final double tailWag = sin(tailPhase) * 14.0 * s;\n    final Path tailPath = Path()\n      ..moveTo(-42 * s, 0)\n      ..quadraticBezierTo(-64 * s, tailWag * 0.5, -78 * s, tailWag - 18 * s)\n      ..quadraticBezierTo(-70 * s, tailWag, -82 * s, tailWag)\n      ..quadraticBezierTo(-70 * s, tailWag, -78 * s, tailWag + 18 * s)\n      ..quadraticBezierTo(-64 * s, tailWag * 0.5, -42 * s, 0)\n      ..close();\n    canvas.drawPath(tailPath, Paint()..color = whaleBlue);\n    canvas.drawPath(tailPath, outline);\n\n    // Side pectoral flippers\n    final Path leftFlipper = Path()\n      ..moveTo(-6 * s, -24 * s)\n      ..quadraticBezierTo(-22 * s, -48 * s, -4 * s, -44 * s)\n      ..quadraticBezierTo(8 * s, -34 * s, 6 * s, -22 * s)\n      ..close();\n    final Path rightFlipper = Path()\n      ..moveTo(-6 * s, 24 * s)\n      ..quadraticBezierTo(-22 * s, 48 * s, -4 * s, 44 * s)\n      ..quadraticBezierTo(8 * s, 34 * s, 6 * s, -22 * s)\n      ..close();\n    canvas.drawPath(leftFlipper, Paint()..color = whaleBlue);\n    canvas.drawPath(leftFlipper, outline);\n    canvas.drawPath(rightFlipper, Paint()..color = whaleBlue);\n    canvas.drawPath(rightFlipper, outline);\n\n    // Plump 3D shaded cartoon whale body\n    final RRect bodyRect = RRect.fromRectAndRadius(\n      Rect.fromCenter(center: Offset.zero, width: 106 * s, height: 64 * s),\n      Radius.circular(32 * s),\n    );\n    final Paint bodyPaint = Paint()\n      ..shader = RadialGradient(\n        center: const Alignment(-0.2, -0.35),\n        radius: 0.95,\n        colors: const [whaleHighlight, whaleBlue, Color(0xFF1E3A8A)],\n      ).createShader(bodyRect.outerRect);\n    canvas.drawRRect(bodyRect, bodyPaint);\n\n    // Light pleated ventral belly grooves near front\n    canvas.drawArc(\n      Rect.fromCenter(center: Offset(8 * s, 0), width: 82 * s, height: 54 * s),\n      -0.65,\n      1.3,\n      false,\n      Paint()..color = whaleBelly.withValues(alpha: 0.85),\n    );\n    canvas.drawRRect(bodyRect, outline);\n\n    // Gaping Hole-Buster Whale Mouth Vortex at the front!\n    final double mawWidth = (28.0 + mouthOpen * 16.0) * s;\n    final double mawHeight = (34.0 + mouthOpen * 18.0) * s;\n    final Rect mawRect = Rect.fromCenter(\n      center: Offset(32 * s, 0),\n      width: mawWidth,\n      height: mawHeight,\n    );\n\n    canvas.drawOval(mawRect, Paint()..color = mawDark);\n\n    for (int ring = 1; ring <= 2; ring++) {\n      canvas.drawOval(\n        mawRect.deflate(ring * 5.0 * s),\n        Paint()\n          ..color = const Color(0xFF1E293B)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 1.6 * s,\n      );\n    }\n\n    canvas.drawArc(\n      mawRect.deflate(3 * s),\n      0.4,\n      2.3,\n      false,\n      Paint()..color = tonguePink,\n    );\n    canvas.drawOval(mawRect, outline);\n\n    // Expressive cartoon whale eyes on either side of the head\n    void drawWhaleEye(Offset eyePos) {\n      canvas.drawCircle(eyePos, 6.2 * s, Paint()..color = Colors.white);\n      canvas.drawCircle(eyePos, 6.2 * s, outline);\n      canvas.drawCircle(\n        eyePos + Offset(1.8 * s, 0),\n        3.0 * s,\n        Paint()..color = Colors.black,\n      );\n      canvas.drawCircle(\n        eyePos + Offset(2.5 * s, -1.2 * s),\n        1.1 * s,\n        Paint()..color = Colors.white,\n      );\n    }\n\n    drawWhaleEye(Offset(14 * s, -22 * s));\n    drawWhaleEye(Offset(14 * s, 22 * s));\n\n    // Dorsal blowhole on top of head with specular shine\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: Offset(-4 * s, -4 * s),\n        width: 9 * s,\n        height: 5 * s,\n      ),\n      Paint()..color = const Color(0xFF0F172A),\n    );\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: Offset(-18 * s, -12 * s),\n        width: 26 * s,\n        height: 10 * s,\n      ),\n      Paint()..color = Colors.white.withValues(alpha: 0.25),\n    );\n\n    canvas.restore();\n\n    // Celebratory Level-Up Water Spout Fountain Animation shooting up from blowhole!\n    if (celebrationSpoutTimer > 0) {\n      final Offset blowholeWorldScreen = center +\n          Offset(\n            (-4 * cos(whaleHeading) + 4 * sin(whaleHeading)) * s,\n            (-4 * sin(whaleHeading) - 4 * cos(whaleHeading)) * s,\n          );\n      _drawCelebrationSpoutGeyser(canvas, blowholeWorldScreen, s);\n    }\n  }\n\n  void _drawCelebrationSpoutGeyser(\n    Canvas canvas,\n    Offset blowholePos,\n    double s,\n  ) {\n    final double pulse = 0.85 + 0.15 * sin(worldTime * 18.0);\n    final double spoutHeight = 95.0 * s * pulse;\n    final Offset topCenter = blowholePos - Offset(0, spoutHeight);\n\n    // Subtle rainbow arc in the mist when spouting!\n    final Rect rainbowRect = Rect.fromCenter(\n      center: blowholePos - Offset(0, spoutHeight * 0.45),\n      width: 90 * s,\n      height: 55 * s,\n    );\n    final List<Color> rainbowColors = [\n      const Color(0xFFEF4444),\n      const Color(0xFFF59E0B),\n      const Color(0xFF10B981),\n      const Color(0xFF38BDF8),\n    ];\n    for (int i = 0; i < rainbowColors.length; i++) {\n      canvas.drawArc(\n        rainbowRect.inflate(i * 3.5 * s),\n        pi + 0.3,\n        pi - 0.6,\n        false,\n        Paint()\n          ..color = rainbowColors[i].withValues(alpha: 0.35)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = 3.0 * s\n          ..strokeCap = StrokeCap.round,\n      );\n    }\n\n    // Central pressurized water column shooting straight up from blowhole\n    final Path columnPath = Path()\n      ..moveTo(blowholePos.dx - 4 * s, blowholePos.dy)\n      ..quadraticBezierTo(\n        blowholePos.dx - 7 * s,\n        blowholePos.dy - spoutHeight * 0.6,\n        topCenter.dx - 22 * s,\n        topCenter.dy,\n      )\n      ..quadraticBezierTo(\n        topCenter.dx,\n        topCenter.dy - 16 * s,\n        topCenter.dx + 22 * s,\n        topCenter.dy,\n      )\n      ..quadraticBezierTo(\n        blowholePos.dx + 7 * s,\n        blowholePos.dy - spoutHeight * 0.6,\n        blowholePos.dx + 4 * s,\n        blowholePos.dy,\n      )\n      ..close();\n\n    canvas.drawPath(\n      columnPath,\n      Paint()..color = const Color(0xFFE0F2FE).withValues(alpha: 0.92),\n    );\n    canvas.drawPath(\n      columnPath,\n      Paint()\n        ..color = const Color(0xFF0284C7)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 2.0 * s,\n    );\n\n    // Twin curling fountain arches at the top of the geyser\n    final Paint archPaint = Paint()\n      ..color = Colors.white\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 4.5 * s\n      ..strokeCap = StrokeCap.round;\n\n    for (final double side in [-1.0, 1.0]) {\n      final Path arch = Path()\n        ..moveTo(topCenter.dx, topCenter.dy)\n        ..quadraticBezierTo(\n          topCenter.dx + side * 34 * s,\n          topCenter.dy - 18 * s,\n          topCenter.dx + side * 48 * s,\n          topCenter.dy + 26 * s,\n        );\n      canvas.drawPath(arch, archPaint);\n    }\n  }\n\n  void _drawSpoutDrops(Canvas canvas, Size size) {\n    for (final d in spoutDrops) {\n      final p = _project(size, d.x, d.y, d.z);\n      final Paint dropPaint = Paint()\n        ..color = (d.isCelebration\n                ? const Color(0xFF7DD3FC)\n                : const Color(0xFFE0F2FE))\n            .withValues(alpha: d.life.clamp(0.0, 1.0));\n      canvas.drawCircle(\n        p.screen,\n        ((d.isCelebration ? 5.0 : 4.0) * p.scale).clamp(1.8, 7.0),\n        dropPaint,\n      );\n    }\n  }\n\n  void _drawFloatingScores(Canvas canvas, Size size) {\n    for (final fs in floatingScores) {\n      final p = _project(size, fs.x, fs.y, fs.z);\n      final TextPainter tp = TextPainter(\n        text: TextSpan(\n          text: fs.text,\n          style: TextStyle(\n            color: const Color(0xFF4ADE80).withValues(\n              alpha: fs.life.clamp(0.0, 1.0),\n            ),\n            fontFamily: 'JetBrainsMono',\n            fontWeight: FontWeight.bold,\n            fontSize: 15,\n            shadows: const [Shadow(color: Colors.black, blurRadius: 5)],\n          ),\n        ),\n        textDirection: TextDirection.ltr,\n      )..layout();\n      tp.paint(canvas, p.screen - Offset(tp.width / 2, tp.height / 2));\n    }\n  }\n\n  @override\n  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;\n}\n\nclass _SeaDecoration {\n  final double x;\n  final double z;\n  final int kind;\n  final double scale;\n  final double phase;\n  final int colorIndex;\n\n  const _SeaDecoration({\n    required this.x,\n    required this.z,\n    required this.kind,\n    required this.scale,\n    required this.phase,\n    required this.colorIndex,\n  });\n}\n\nclass _WaveCrest {\n  final double x;\n  final double z;\n  final double width;\n  final double phase;\n\n  const _WaveCrest({\n    required this.x,\n    required this.z,\n    required this.width,\n    required this.phase,\n  });\n}\n\nclass _DepthDrawable {\n  final double depth;\n  final void Function(Canvas canvas) draw;\n\n  _DepthDrawable({required this.depth, required this.draw});\n}\n\nclass _OceanEntity {\n  final OceanItemType type;\n  double x;\n  double z;\n  double heading;\n  final double speed;\n  final double requiredScale;\n  final double radius;\n  final double massGain;\n  final int points;\n  final double bobPhase;\n  final int colorVariant;\n\n  _OceanEntity({\n    required this.type,\n    required this.x,\n    required this.z,\n    required this.heading,\n    required this.speed,\n    required this.requiredScale,\n    required this.radius,\n    required this.massGain,\n    required this.points,\n    required this.bobPhase,\n    required this.colorVariant,\n  });\n}\n\nclass _SwallowingEntity {\n  final _OceanEntity entity;\n  double progress;\n\n  _SwallowingEntity({required this.entity, required this.progress});\n}\n\nclass _WaterRipple {\n  final double x;\n  final double z;\n  double radius;\n  final double maxRadius;\n  double life;\n\n  _WaterRipple({\n    required this.x,\n    required this.z,\n    required this.radius,\n    required this.maxRadius,\n    required this.life,\n  });\n}\n\nclass _SpoutDrop {\n  double x;\n  double y;\n  double z;\n  double vx;\n  double vy;\n  double vz;\n  double life;\n  final bool isCelebration;\n\n  _SpoutDrop({\n    required this.x,\n    required this.y,\n    required this.z,\n    required this.vx,\n    required this.vy,\n    required this.vz,\n    required this.life,\n    this.isCelebration = false,\n  });\n}\n\nclass _FloatingScore {\n  final String text;\n  final double x;\n  double y;\n  final double z;\n  double life;\n\n  _FloatingScore({\n    required this.text,\n    required this.x,\n    required this.y,\n    required this.z,\n    required this.life,\n  });\n}\n",
  "lib/games/santa_game.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/scheduler.dart';\nimport 'package:flutter/services.dart';\n\nconst Color kCrimsonRed = Color(0xFFD90429);\nconst Color kDarkBlood = Color(0xFF780000);\nconst Color kNoseGlow = Color(0xFFFF1E42);\nconst Color kSnowWhite = Color(0xFFF0F4F8);\nconst Color kSnowShadow = Color(0xFFBCCCDC);\nconst Color kNightTop = Color(0xFF050814);\nconst Color kNightBottom = Color(0xFF101B38);\n\nconst List<String> kReindeerNames = [\n  'DASHER',\n  'DANCER',\n  'PRANCER',\n  'VIXEN',\n  'COMET',\n  'CUPID',\n  'DONNER',\n  'BLITZEN',\n];\n\nclass SantasInvadersGame extends StatefulWidget {\n  const SantasInvadersGame({super.key});\n\n  @override\n  State<SantasInvadersGame> createState() => _SantasInvadersGameState();\n}\n\nclass _SantasInvadersGameState extends State<SantasInvadersGame>\n    with SingleTickerProviderStateMixin {\n  final FocusNode _focusNode = FocusNode();\n  final AudioPlayer _audioPlayer = AudioPlayer();\n  final Random _rng = Random();\n\n  late Ticker _ticker;\n  Duration _lastElapsed = Duration.zero;\n  double _worldTime = 0.0;\n\n  // Normalized world coordinates:\n  // X: 0.0 (left) to 1.0 (right)\n  // Y: 0.0 (top) to 1.0 (bottom), ground is at Y = 0.80\n  static const double _groundY = 0.80;\n  static const double _gravity = 1.95;\n\n  // Platforms (xMin, xMax, y)\n  final List<_Platform> _platforms = const [\n    _Platform(xMin: 0.08, xMax: 0.34, y: 0.63),\n    _Platform(xMin: 0.66, xMax: 0.92, y: 0.63),\n    _Platform(xMin: 0.32, xMax: 0.68, y: 0.47),\n  ];\n\n  // Rudolph state\n  double _playerX = 0.22;\n  double _playerY = _groundY;\n  double _playerVy = 0.0;\n  bool _facingRight = true;\n  double _aimAngle = 0.0; // radians, 0 = right, pi = left, -pi/2 = up\n  bool _isGrounded = true;\n  int _jumpsRemaining = 2;\n  double _walkCycle = 0.0;\n  double _muzzleFlashTimer = 0.0;\n  double _fireCooldown = 0.0;\n  double _recoilOffset = 0.0;\n\n  // Input states (Keyboard)\n  final Set<LogicalKeyboardKey> _keysPressed = {};\n  bool _mouseShooting = false;\n\n  // Input states (Touch Joystick & Buttons)\n  int? _joystickPointerId;\n  Offset _joystickCenter = Offset.zero;\n  Offset _joystickDelta = Offset.zero; // normalized -1..1\n  int? _shootButtonPointerId;\n  int? _jumpButtonPointerId;\n\n  // Game stats\n  int _score = 0;\n  int _kills = 0;\n  int _combo = 0;\n  double _comboTimer = 0.0;\n\n  // Entities\n  final List<_Bullet> _bullets = [];\n  final List<_ReindeerTarget> _reindeer = [];\n  final List<_BloodParticle> _bloodParticles = [];\n  final List<_SnowStain> _snowStains = [];\n  final List<_ShellCasing> _shells = [];\n  final List<_FloatingText> _floatingTexts = [];\n  final List<_HorizonCross> _horizonCrosses = [];\n  late final List<_Snowflake> _snowflakes;\n  late final List<_Star> _stars;\n\n  double _spawnTimer = 0.0;\n\n  // Audio playlist (Santa's Cookies EP)\n  final List<String> _playlist = [\n    'rudolph_spoke_in_class_today.wav',\n    'who_you_calling_a_ho_ho.wav',\n    'oh_christmas_tree.wav',\n    'must_be_a_south_pole_elf.wav',\n  ];\n  List<String> _musicQueue = [];\n  StreamSubscription? _playerCompleteSubscription;\n\n  @override\n  void initState() {\n    super.initState();\n\n    _snowflakes = List.generate(\n      70,\n      (_) => _Snowflake(\n        x: _rng.nextDouble(),\n        y: _rng.nextDouble(),\n        radius: 1.2 + _rng.nextDouble() * 2.5,\n        speedY: 0.04 + _rng.nextDouble() * 0.08,\n        drift: (_rng.nextDouble() - 0.5) * 0.03,\n        phase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n\n    _stars = List.generate(\n      45,\n      (_) => _Star(\n        x: _rng.nextDouble(),\n        y: _rng.nextDouble() * 0.52,\n        size: 0.8 + _rng.nextDouble() * 1.8,\n        twinklePhase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n\n    _seedInitialReindeer();\n\n    _ticker = createTicker(_onTick)..start();\n\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      if (mounted) {\n        _focusNode.requestFocus();\n      }\n    });\n\n    _setupAudioPlayer();\n  }\n\n  @override\n  void dispose() {\n    _ticker.dispose();\n    _focusNode.dispose();\n    _playerCompleteSubscription?.cancel();\n    _audioPlayer.dispose();\n    super.dispose();\n  }\n\n  void _setupAudioPlayer() {\n    _audioPlayer.setReleaseMode(ReleaseMode.release);\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((_) {\n      _playNextTrack();\n    });\n    // Start with Rudolph Spoke in Class Today, then shuffle the rest\n    _musicQueue = List.of(_playlist);\n    _playNextTrack();\n  }\n\n  Future<void> _playNextTrack() async {\n    if (_playlist.isEmpty) return;\n    if (_musicQueue.isEmpty) {\n      _musicQueue = List.of(_playlist)..shuffle();\n    }\n    final nextSong = _musicQueue.removeAt(0);\n    try {\n      await _audioPlayer.setSource(AssetSource('music/santas_cookies/\$nextSong'));\n      await _audioPlayer.setVolume(0.5);\n      await _audioPlayer.resume();\n    } catch (e) {\n      debugPrint('Audio Error: \$e');\n    }\n  }\n\n  void _seedInitialReindeer() {\n    _reindeer.clear();\n    for (int i = 0; i < 5; i++) {\n      _spawnReindeer(initialSpread: true);\n    }\n  }\n\n  void _resetAll() {\n    setState(() {\n      _score = 0;\n      _kills = 0;\n      _combo = 0;\n      _comboTimer = 0.0;\n      _playerX = 0.22;\n      _playerY = _groundY;\n      _playerVy = 0.0;\n      _facingRight = true;\n      _bullets.clear();\n      _bloodParticles.clear();\n      _snowStains.clear();\n      _shells.clear();\n      _floatingTexts.clear();\n      _horizonCrosses.clear();\n      _seedInitialReindeer();\n    });\n  }\n\n  void _spawnReindeer({bool initialSpread = false}) {\n    if (_reindeer.length >= 9) return;\n\n    final name = kReindeerNames[_rng.nextInt(kReindeerNames.length)];\n    final bool isPrancingSky = _rng.nextDouble() < 0.22;\n    final bool fromLeft = _rng.nextBool();\n\n    double startX;\n    if (initialSpread) {\n      startX = 0.38 + _rng.nextDouble() * 0.55;\n    } else {\n      startX = fromLeft ? -0.06 : 1.06;\n    }\n\n    double targetY = _groundY;\n    if (isPrancingSky) {\n      targetY = 0.20 + _rng.nextDouble() * 0.22;\n    } else if (_rng.nextDouble() < 0.45) {\n      final p = _platforms[_rng.nextInt(_platforms.length)];\n      targetY = p.y;\n      if (initialSpread) {\n        startX = p.xMin + _rng.nextDouble() * (p.xMax - p.xMin);\n      }\n    }\n\n    final double baseSpeed = 0.055 + _rng.nextDouble() * 0.065;\n    final double dir = initialSpread\n        ? (_rng.nextBool() ? 1.0 : -1.0)\n        : (fromLeft ? 1.0 : -1.0);\n\n    _reindeer.add(\n      _ReindeerTarget(\n        name: name,\n        x: startX,\n        y: targetY,\n        vx: dir * baseSpeed,\n        vy: 0.0,\n        isFlying: isPrancingSky,\n        hp: 3,\n        maxHp: 3,\n        furVariant: _rng.nextInt(3),\n        legPhase: _rng.nextDouble() * pi * 2,\n      ),\n    );\n  }\n\n  KeyEventResult _handleKeyEvent(FocusNode node, KeyEvent event) {\n    if (event is KeyDownEvent) {\n      _keysPressed.add(event.logicalKey);\n      if (event.logicalKey == LogicalKeyboardKey.space ||\n          event.logicalKey == LogicalKeyboardKey.keyZ ||\n          event.logicalKey == LogicalKeyboardKey.keyK) {\n        _triggerJump();\n      }\n    } else if (event is KeyUpEvent) {\n      _keysPressed.remove(event.logicalKey);\n    }\n    return KeyEventResult.handled;\n  }\n\n  void _triggerJump() {\n    final bool holdingDown =\n        _keysPressed.contains(LogicalKeyboardKey.keyS) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowDown) ||\n        _joystickDelta.dy > 0.55;\n\n    // Drop through platform if holding down on an elevated platform\n    if (holdingDown && _isGrounded && _playerY < _groundY - 0.02) {\n      setState(() {\n        _playerY += 0.03;\n        _isGrounded = false;\n      });\n      return;\n    }\n\n    if (_jumpsRemaining > 0) {\n      setState(() {\n        _playerVy = -0.78;\n        _isGrounded = false;\n        _jumpsRemaining--;\n      });\n      HapticFeedback.lightImpact();\n    }\n  }\n\n  void _fireWeapon() {\n    if (_fireCooldown > 0) return;\n    _fireCooldown = 0.11; // rapid fire Contra rifle\n    _muzzleFlashTimer = 0.06;\n    _recoilOffset = 0.012;\n\n    // Gun barrel tip position in normalized coordinates\n    final double cosA = cos(_aimAngle);\n    final double sinA = sin(_aimAngle);\n    final double muzzleX = _playerX + cosA * 0.038;\n    final double muzzleY = (_playerY - 0.055) + sinA * 0.038;\n\n    // Slight spread for rapid machine-gun feel\n    final double spread = (_rng.nextDouble() - 0.5) * 0.06;\n    final double shotAngle = _aimAngle + spread;\n    const double bulletSpeed = 1.35;\n\n    _bullets.add(\n      _Bullet(\n        x: muzzleX,\n        y: muzzleY,\n        vx: cos(shotAngle) * bulletSpeed,\n        vy: sin(shotAngle) * bulletSpeed,\n      ),\n    );\n\n    // Eject brass shell casing\n    _shells.add(\n      _ShellCasing(\n        x: _playerX,\n        y: _playerY - 0.06,\n        vx: (_facingRight ? -1 : 1) * (0.08 + _rng.nextDouble() * 0.08),\n        vy: -0.25 - _rng.nextDouble() * 0.12,\n        rotation: _rng.nextDouble() * pi,\n      ),\n    );\n    if (_shells.length > 35) {\n      _shells.removeAt(0);\n    }\n\n    // Scare nearby reindeer when gunfire rings out\n    for (final r in _reindeer) {\n      if ((r.x - _playerX).abs() < 0.45) {\n        r.panicTimer = 2.0;\n      }\n    }\n  }\n\n  void _onTick(Duration elapsed) {\n    final double dt = _lastElapsed == Duration.zero\n        ? 0.016\n        : ((elapsed - _lastElapsed).inMicroseconds / 1000000.0).clamp(\n            0.001,\n            0.05,\n          );\n    _lastElapsed = elapsed;\n\n    setState(() {\n      _worldTime += dt;\n      if (_muzzleFlashTimer > 0) _muzzleFlashTimer = max(0, _muzzleFlashTimer - dt);\n      if (_fireCooldown > 0) _fireCooldown = max(0, _fireCooldown - dt);\n      if (_recoilOffset > 0) _recoilOffset = max(0, _recoilOffset - dt * 0.09);\n\n      if (_comboTimer > 0) {\n        _comboTimer -= dt;\n        if (_comboTimer <= 0) {\n          _combo = 0;\n        }\n      }\n\n      _updatePlayer(dt);\n      _updateBulletsAndCollisions(dt);\n      _updateReindeer(dt);\n      _updateParticles(dt);\n      _updateSnowflakes(dt);\n\n      _spawnTimer -= dt;\n      if (_spawnTimer <= 0) {\n        _spawnReindeer();\n        _spawnTimer = _reindeer.length < 4 ? 0.55 : 1.15;\n      }\n    });\n  }\n\n  void _updatePlayer(double dt) {\n    // Combine keyboard and virtual joystick input\n    double moveX = 0.0;\n    double aimX = 0.0;\n    double aimY = 0.0;\n\n    if (_keysPressed.contains(LogicalKeyboardKey.keyA) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowLeft)) {\n      moveX -= 1.0;\n      aimX -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyD) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowRight)) {\n      moveX += 1.0;\n      aimX += 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyW) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowUp)) {\n      aimY -= 1.0;\n    }\n    if (_keysPressed.contains(LogicalKeyboardKey.keyS) ||\n        _keysPressed.contains(LogicalKeyboardKey.arrowDown)) {\n      aimY += 1.0;\n    }\n\n    if (_joystickPointerId != null && _joystickDelta.distance > 0.14) {\n      if (_joystickDelta.dx.abs() > 0.22) {\n        moveX = _joystickDelta.dx.clamp(-1.0, 1.0);\n      }\n      aimX = _joystickDelta.dx;\n      aimY = _joystickDelta.dy;\n    }\n\n    if (moveX < -0.05) _facingRight = false;\n    if (moveX > 0.05) _facingRight = true;\n\n    // 8-way Contra snapping for aim\n    if (aimX.abs() > 0.15 || aimY.abs() > 0.15) {\n      // Prevent aiming straight down when standing on ground\n      if (_isGrounded && aimY > 0.4 && aimX.abs() < 0.35) {\n        _aimAngle = _facingRight ? 0.0 : pi;\n      } else {\n        final double rawAngle = atan2(aimY, aimX);\n        // Snap to 8 directions (multiples of pi / 4)\n        final double step = pi / 4;\n        _aimAngle = (rawAngle / step).round() * step;\n      }\n    } else {\n      _aimAngle = _facingRight ? 0.0 : pi;\n    }\n\n    // Horizontal movement\n    const double playerSpeed = 0.36;\n    _playerX += moveX * playerSpeed * dt;\n    _playerX = _playerX.clamp(0.05, 0.95);\n\n    if (moveX.abs() > 0.05 && _isGrounded) {\n      _walkCycle += dt * 14.0;\n    } else if (_isGrounded) {\n      _walkCycle = 0.0;\n    }\n\n    // Vertical movement & platform collisions\n    final double prevY = _playerY;\n    _playerVy += _gravity * dt;\n    _playerY += _playerVy * dt;\n    _isGrounded = false;\n\n    // Check landing on elevated platforms when falling\n    if (_playerVy >= 0) {\n      for (final p in _platforms) {\n        if (_playerX >= p.xMin &&\n            _playerX <= p.xMax &&\n            prevY <= p.y + 0.008 &&\n            _playerY >= p.y) {\n          _playerY = p.y;\n          _playerVy = 0.0;\n          _isGrounded = true;\n          _jumpsRemaining = 2;\n          break;\n        }\n      }\n    }\n\n    // Ground collision\n    if (_playerY >= _groundY) {\n      _playerY = _groundY;\n      _playerVy = 0.0;\n      _isGrounded = true;\n      _jumpsRemaining = 2;\n    }\n\n    // Check shooting input (Keyboard or Touch Shoot button or Mouse hold)\n    final bool wantsShoot =\n        _shootButtonPointerId != null ||\n        _mouseShooting ||\n        _keysPressed.contains(LogicalKeyboardKey.keyJ) ||\n        _keysPressed.contains(LogicalKeyboardKey.keyX) ||\n        _keysPressed.contains(LogicalKeyboardKey.keyF) ||\n        _keysPressed.contains(LogicalKeyboardKey.enter) ||\n        _keysPressed.contains(LogicalKeyboardKey.shiftLeft) ||\n        _keysPressed.contains(LogicalKeyboardKey.shiftRight);\n\n    if (wantsShoot) {\n      _fireWeapon();\n    }\n  }\n\n  void _updateBulletsAndCollisions(double dt) {\n    final List<_Bullet> bulletsToRemove = [];\n    final List<_ReindeerTarget> killedReindeer = [];\n\n    for (final b in _bullets) {\n      b.x += b.vx * dt;\n      b.y += b.vy * dt;\n\n      if (b.x < -0.05 || b.x > 1.05 || b.y < -0.05 || b.y > 1.0) {\n        bulletsToRemove.add(b);\n        continue;\n      }\n\n      // Check collision with any reindeer (they have no weapons and cannot hurt Rudolph)\n      for (final r in _reindeer) {\n        if (r.hp <= 0) continue;\n        final double hitCenterX = r.x;\n        final double hitCenterY = r.y - 0.042;\n        final double dx = b.x - hitCenterX;\n        final double dy = b.y - hitCenterY;\n\n        if (dx.abs() < 0.046 && dy.abs() < 0.048) {\n          bulletsToRemove.add(b);\n          r.hp--;\n          r.hitFlash = 0.18;\n          r.panicTimer = 3.0;\n          // Boost fleeing speed when shot\n          if (r.vx.abs() < 0.14) {\n            final double fleeDir = (r.x >= _playerX) ? 1.0 : -1.0;\n            r.vx = fleeDir * (0.14 + _rng.nextDouble() * 0.05);\n          }\n\n          _score += 100;\n          _spawnBloodBurst(\n            x: b.x,\n            y: b.y,\n            count: r.hp <= 0 ? 38 : 14,\n            bulletVx: b.vx,\n            bulletVy: b.vy,\n            isFatal: r.hp <= 0,\n          );\n\n          if (r.hp <= 0) {\n            killedReindeer.add(r);\n            _onReindeerKilled(r);\n          } else {\n            _floatingTexts.add(\n              _FloatingText(\n                text: '+100',\n                x: r.x,\n                y: r.y - 0.08,\n                color: Colors.white,\n                life: 0.65,\n              ),\n            );\n          }\n          break;\n        }\n      }\n    }\n\n    _bullets.removeWhere((b) => bulletsToRemove.contains(b));\n    _reindeer.removeWhere((r) => killedReindeer.contains(r));\n  }\n\n  void _onReindeerKilled(_ReindeerTarget r) {\n    _kills++;\n    _combo++;\n    _comboTimer = 3.2;\n\n    final int killBonus = 500 * _combo;\n    _score += killBonus;\n\n    _floatingTexts.add(\n      _FloatingText(\n        text: '✖ \${r.name} +\$killBonus',\n        x: r.x.clamp(0.1, 0.9),\n        y: r.y - 0.09,\n        color: kCrimsonRed,\n        life: 1.25,\n        isBold: true,\n      ),\n    );\n\n    // Add a blood stain directly below if near ground/platform\n    _addSnowStainAt(r.x, r.isFlying ? _groundY : r.y, radius: 0.038);\n\n    // Add a little cross on the distant snow ridge (\"The next day, the crosses lined the horizon\")\n    if (_horizonCrosses.length < 24) {\n      _horizonCrosses.add(\n        _HorizonCross(\n          x: (0.08 + (_kills * 0.073 + _rng.nextDouble() * 0.03) % 0.84),\n          tilt: (_rng.nextDouble() - 0.5) * 0.18,\n        ),\n      );\n    }\n\n    HapticFeedback.mediumImpact();\n  }\n\n  void _spawnBloodBurst({\n    required double x,\n    required double y,\n    required int count,\n    required double bulletVx,\n    required double bulletVy,\n    required bool isFatal,\n  }) {\n    for (int i = 0; i < count; i++) {\n      final double angle = _rng.nextDouble() * pi * 2;\n      final double speed = 0.06 + _rng.nextDouble() * (isFatal ? 0.42 : 0.24);\n      _bloodParticles.add(\n        _BloodParticle(\n          x: x,\n          y: y,\n          vx: cos(angle) * speed + bulletVx * 0.12,\n          vy: sin(angle) * speed - 0.14 + bulletVy * 0.08,\n          radius: isFatal\n              ? (2.2 + _rng.nextDouble() * 4.5)\n              : (1.8 + _rng.nextDouble() * 3.0),\n          life: 0.55 + _rng.nextDouble() * 0.55,\n          isChunk: isFatal && i < 5,\n        ),\n      );\n    }\n  }\n\n  void _addSnowStainAt(double x, double y, {double radius = 0.022}) {\n    _snowStains.add(\n      _SnowStain(\n        x: x.clamp(0.02, 0.98),\n        y: y,\n        radiusX: radius * (0.8 + _rng.nextDouble() * 0.6),\n        radiusY: radius * 0.32,\n      ),\n    );\n    if (_snowStains.length > 70) {\n      _snowStains.removeAt(0);\n    }\n  }\n\n  void _updateReindeer(double dt) {\n    for (final r in _reindeer) {\n      if (r.hitFlash > 0) r.hitFlash = max(0, r.hitFlash - dt);\n      if (r.panicTimer > 0) r.panicTimer = max(0, r.panicTimer - dt);\n\n      final double speedMult = r.panicTimer > 0 ? 1.55 : 1.0;\n      r.x += r.vx * speedMult * dt;\n      r.legPhase += dt * (r.panicTimer > 0 ? 16.0 : 9.5);\n\n      if (r.isFlying) {\n        // Prancing wave motion in the night sky\n        r.y += sin(_worldTime * 3.5 + r.legPhase * 0.2) * 0.04 * dt;\n      } else {\n        // Occasional joyful/panicked hop\n        if (r.vy == 0 && _rng.nextDouble() < (r.panicTimer > 0 ? 0.03 : 0.008)) {\n          r.vy = -0.36;\n        }\n        if (r.vy != 0 || r.y < r.baseY) {\n          r.vy += _gravity * 0.75 * dt;\n          r.y += r.vy * dt;\n          if (r.y >= r.baseY) {\n            r.y = r.baseY;\n            r.vy = 0.0;\n          }\n        }\n      }\n\n      // Keep on platform or turn around at edges\n      if (!r.isFlying && r.baseY < _groundY - 0.02) {\n        final platform = _platforms.firstWhere(\n          (p) => (p.y - r.baseY).abs() < 0.03,\n          orElse: () => const _Platform(xMin: 0.05, xMax: 0.95, y: _groundY),\n        );\n        if (r.x < platform.xMin + 0.02) {\n          r.x = platform.xMin + 0.02;\n          r.vx = r.vx.abs();\n        } else if (r.x > platform.xMax - 0.02) {\n          r.x = platform.xMax - 0.02;\n          r.vx = -r.vx.abs();\n        }\n      } else {\n        // Wrap or bounce at screen edges\n        if (r.x < -0.08 && r.vx < 0) {\n          r.vx = r.vx.abs();\n        } else if (r.x > 1.08 && r.vx > 0) {\n          r.vx = -r.vx.abs();\n        }\n      }\n    }\n  }\n\n  void _updateParticles(double dt) {\n    for (final p in _bloodParticles) {\n      final double prevY = p.y;\n      p.x += p.vx * dt;\n      p.vy += _gravity * 0.85 * dt;\n      p.y += p.vy * dt;\n      p.life -= dt;\n\n      // Check if blood droplet hits a platform or the snow ground\n      for (final plat in _platforms) {\n        if (p.vy > 0 &&\n            p.x >= plat.xMin &&\n            p.x <= plat.xMax &&\n            prevY <= plat.y &&\n            p.y >= plat.y) {\n          _addSnowStainAt(p.x, plat.y, radius: 0.015);\n          p.life = 0;\n          break;\n        }\n      }\n      if (p.y >= _groundY && p.life > 0) {\n        _addSnowStainAt(p.x, _groundY, radius: 0.018);\n        p.life = 0;\n      }\n    }\n    _bloodParticles.removeWhere((p) => p.life <= 0);\n\n    for (final s in _shells) {\n      s.x += s.vx * dt;\n      s.vy += _gravity * dt;\n      s.y += s.vy * dt;\n      s.rotation += dt * 10.0;\n      if (s.y >= _groundY) {\n        s.y = _groundY;\n        s.vx *= 0.4;\n        s.vy = 0;\n      }\n    }\n\n    for (final ft in _floatingTexts) {\n      ft.y -= 0.065 * dt;\n      ft.life -= dt;\n    }\n    _floatingTexts.removeWhere((ft) => ft.life <= 0);\n  }\n\n  void _updateSnowflakes(double dt) {\n    for (final flake in _snowflakes) {\n      flake.y += flake.speedY * dt;\n      flake.x += (flake.drift + sin(_worldTime + flake.phase) * 0.01) * dt;\n      if (flake.y > 1.0) {\n        flake.y = -0.02;\n        flake.x = _rng.nextDouble();\n      }\n      if (flake.x < 0) flake.x += 1.0;\n      if (flake.x > 1.0) flake.x -= 1.0;\n    }\n  }\n\n  void _updateJoystickVector(Offset localPos, double maxRadius) {\n    final Offset raw = localPos - _joystickCenter;\n    final double dist = raw.distance;\n    if (dist <= 0.001) {\n      _joystickDelta = Offset.zero;\n      return;\n    }\n    final double clampedDist = min(dist, maxRadius);\n    final Offset dir = raw / dist;\n    _joystickDelta = dir * (clampedDist / maxRadius);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: kNightTop,\n      appBar: AppBar(\n        backgroundColor: const Color(0xFF060B19),\n        elevation: 0,\n        leading: const BackButton(color: Colors.white),\n        title: const Text(\n          'rudolph_spoke.sh',\n          style: TextStyle(\n            color: Colors.white,\n            fontFamily: 'JetBrainsMono',\n            fontSize: 15,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        centerTitle: true,\n        actions: [\n          IconButton(\n            tooltip: 'Reset Snowfield',\n            onPressed: _resetAll,\n            icon: const Icon(Icons.refresh, color: Colors.white70, size: 20),\n          ),\n        ],\n      ),\n      body: KeyboardListener(\n        focusNode: _focusNode,\n        autofocus: true,\n        onKeyEvent: (event) => _handleKeyEvent(_focusNode, event),\n        child: LayoutBuilder(\n          builder: (context, constraints) {\n            final bool isCompact = constraints.maxWidth < 700;\n            final double joystickSize = isCompact ? 118.0 : 128.0;\n            final double joystickRadius = joystickSize / 2;\n\n            return Stack(\n              fit: StackFit.expand,\n              children: [\n                // Main Cartoon Game Canvas (supports click/hold to aim & shoot on desktop)\n                Listener(\n                  behavior: HitTestBehavior.opaque,\n                  onPointerDown: (event) {\n                    _focusNode.requestFocus();\n                    // Allow clicking/tapping canvas outside controls to aim & shoot\n                    final double normX = event.localPosition.dx / constraints.maxWidth;\n                    final double normY = event.localPosition.dy / constraints.maxHeight;\n                    if (normY < 0.75) {\n                      _facingRight = normX >= _playerX;\n                      _aimAngle = atan2(\n                        normY - (_playerY - 0.055),\n                        normX - _playerX,\n                      );\n                      _mouseShooting = true;\n                      _fireWeapon();\n                    }\n                  },\n                  onPointerMove: (event) {\n                    if (_mouseShooting) {\n                      final double normX =\n                          event.localPosition.dx / constraints.maxWidth;\n                      final double normY =\n                          event.localPosition.dy / constraints.maxHeight;\n                      _facingRight = normX >= _playerX;\n                      _aimAngle = atan2(\n                        normY - (_playerY - 0.055),\n                        normX - _playerX,\n                      );\n                    }\n                  },\n                  onPointerUp: (_) => _mouseShooting = false,\n                  onPointerCancel: (_) => _mouseShooting = false,\n                  child: CustomPaint(\n                    painter: _RudolphContraPainter(\n                      worldTime: _worldTime,\n                      playerX: _playerX,\n                      playerY: _playerY,\n                      facingRight: _facingRight,\n                      aimAngle: _aimAngle,\n                      walkCycle: _walkCycle,\n                      isGrounded: _isGrounded,\n                      muzzleFlashTimer: _muzzleFlashTimer,\n                      recoilOffset: _recoilOffset,\n                      kills: _kills,\n                      platforms: _platforms,\n                      bullets: _bullets,\n                      reindeer: _reindeer,\n                      bloodParticles: _bloodParticles,\n                      snowStains: _snowStains,\n                      shells: _shells,\n                      floatingTexts: _floatingTexts,\n                      horizonCrosses: _horizonCrosses,\n                      snowflakes: _snowflakes,\n                      stars: _stars,\n                    ),\n                  ),\n                ),\n\n                // Top HUD: Score & Crimson Checkmarks\n                Positioned(\n                  top: 10,\n                  left: 14,\n                  right: 14,\n                  child: IgnorePointer(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.stretch,\n                      children: [\n                        Wrap(\n                          alignment: WrapAlignment.spaceBetween,\n                          crossAxisAlignment: WrapCrossAlignment.center,\n                          spacing: 8,\n                          runSpacing: 6,\n                          children: [\n                            Container(\n                              padding: const EdgeInsets.symmetric(\n                                horizontal: 12,\n                                vertical: 8,\n                              ),\n                              decoration: BoxDecoration(\n                                color: Colors.black.withValues(alpha: 0.65),\n                                border: Border.all(\n                                  color: kCrimsonRed.withValues(alpha: 0.8),\n                                  width: 1.5,\n                                ),\n                                borderRadius: BorderRadius.circular(6),\n                              ),\n                              child: Column(\n                                crossAxisAlignment: CrossAxisAlignment.start,\n                                mainAxisSize: MainAxisSize.min,\n                                children: [\n                                  Text(\n                                    'POINTS: \$_score',\n                                    style: const TextStyle(\n                                      color: Colors.white,\n                                      fontFamily: 'JetBrainsMono',\n                                      fontWeight: FontWeight.bold,\n                                      fontSize: 16,\n                                    ),\n                                  ),\n                                  const SizedBox(height: 2),\n                                  Text(\n                                    'MARKED IN CRIMSON: \$_kills\${_combo > 1 ? \"  (\${_combo}x COMBO!)\" : \"\"}',\n                                    style: const TextStyle(\n                                      color: kCrimsonRed,\n                                      fontFamily: 'JetBrainsMono',\n                                      fontWeight: FontWeight.bold,\n                                      fontSize: 12,\n                                    ),\n                                  ),\n                                ],\n                              ),\n                            ),\n                            if (!isCompact)\n                              Container(\n                                padding: const EdgeInsets.symmetric(\n                                  horizontal: 10,\n                                  vertical: 6,\n                                ),\n                                decoration: BoxDecoration(\n                                  color: Colors.black.withValues(alpha: 0.55),\n                                  borderRadius: BorderRadius.circular(6),\n                                  border: Border.all(color: Colors.white24),\n                                ),\n                                child: const Text(\n                                  'WASD/ARROWS: Move & Aim | SPACE: Jump | J/X/CLICK: Shoot',\n                                  style: TextStyle(\n                                    color: Colors.white70,\n                                    fontFamily: 'JetBrainsMono',\n                                    fontSize: 11,\n                                  ),\n                                ),\n                              ),\n                          ],\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n\n                // Contra-style Touch Controls: Left Virtual Joystick + Right JUMP & SHOOT buttons\n                Positioned(\n                  left: isCompact ? 16 : 28,\n                  bottom: isCompact ? 16 : 24,\n                  child: Listener(\n                    behavior: HitTestBehavior.opaque,\n                    onPointerDown: (event) {\n                      if (_joystickPointerId == null) {\n                        setState(() {\n                          _joystickPointerId = event.pointer;\n                          _joystickCenter = Offset(joystickRadius, joystickRadius);\n                          _updateJoystickVector(\n                            event.localPosition,\n                            joystickRadius * 0.68,\n                          );\n                        });\n                      }\n                    },\n                    onPointerMove: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _updateJoystickVector(\n                            event.localPosition,\n                            joystickRadius * 0.68,\n                          );\n                        });\n                      }\n                    },\n                    onPointerUp: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _joystickPointerId = null;\n                          _joystickDelta = Offset.zero;\n                        });\n                      }\n                    },\n                    onPointerCancel: (event) {\n                      if (event.pointer == _joystickPointerId) {\n                        setState(() {\n                          _joystickPointerId = null;\n                          _joystickDelta = Offset.zero;\n                        });\n                      }\n                    },\n                    child: SizedBox(\n                      key: const Key('virtual_joystick'),\n                      width: joystickSize,\n                      height: joystickSize,\n                      child: CustomPaint(\n                        painter: _JoystickPainter(\n                          delta: _joystickDelta,\n                          isActive: _joystickPointerId != null,\n                        ),\n                      ),\n                    ),\n                  ),\n                ),\n\n                // Right-side JUMP and SHOOT arcade buttons\n                Positioned(\n                  right: isCompact ? 16 : 28,\n                  bottom: isCompact ? 18 : 26,\n                  child: Row(\n                    mainAxisSize: MainAxisSize.min,\n                    crossAxisAlignment: CrossAxisAlignment.end,\n                    children: [\n                      // JUMP Button\n                      Padding(\n                        padding: const EdgeInsets.only(bottom: 6, right: 14),\n                        child: Listener(\n                          behavior: HitTestBehavior.opaque,\n                          onPointerDown: (event) {\n                            _jumpButtonPointerId = event.pointer;\n                            _triggerJump();\n                          },\n                          onPointerUp: (event) {\n                            if (event.pointer == _jumpButtonPointerId) {\n                              setState(() => _jumpButtonPointerId = null);\n                            }\n                          },\n                          onPointerCancel: (event) {\n                            if (event.pointer == _jumpButtonPointerId) {\n                              setState(() => _jumpButtonPointerId = null);\n                            }\n                          },\n                          child: _ArcadeControlButton(\n                            key: const Key('jump_button'),\n                            label: 'JUMP',\n                            subLabel: 'SPACE',\n                            color: const Color(0xFF1D4ED8),\n                            isPressed: _jumpButtonPointerId != null,\n                            size: isCompact ? 68 : 74,\n                          ),\n                        ),\n                      ),\n                      // SHOOT Button (Hold for auto-fire)\n                      Padding(\n                        padding: const EdgeInsets.only(bottom: 22),\n                        child: Listener(\n                          behavior: HitTestBehavior.opaque,\n                          onPointerDown: (event) {\n                            setState(() => _shootButtonPointerId = event.pointer);\n                            _fireWeapon();\n                          },\n                          onPointerUp: (event) {\n                            if (event.pointer == _shootButtonPointerId) {\n                              setState(() => _shootButtonPointerId = null);\n                            }\n                          },\n                          onPointerCancel: (event) {\n                            if (event.pointer == _shootButtonPointerId) {\n                              setState(() => _shootButtonPointerId = null);\n                            }\n                          },\n                          child: _ArcadeControlButton(\n                            key: const Key('shoot_button'),\n                            label: 'SHOOT',\n                            subLabel: 'FIRE',\n                            color: kCrimsonRed,\n                            isPressed: _shootButtonPointerId != null,\n                            size: isCompact ? 76 : 82,\n                          ),\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              ],\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass _ArcadeControlButton extends StatelessWidget {\n  final String label;\n  final String subLabel;\n  final Color color;\n  final bool isPressed;\n  final double size;\n\n  const _ArcadeControlButton({\n    super.key,\n    required this.label,\n    required this.subLabel,\n    required this.color,\n    required this.isPressed,\n    required this.size,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return AnimatedScale(\n      scale: isPressed ? 0.92 : 1.0,\n      duration: const Duration(milliseconds: 60),\n      child: Container(\n        width: size,\n        height: size,\n        decoration: BoxDecoration(\n          shape: BoxShape.circle,\n          color: isPressed\n              ? color.withValues(alpha: 0.85)\n              : color.withValues(alpha: 0.55),\n          border: Border.all(\n            color: Colors.white.withValues(alpha: isPressed ? 0.95 : 0.65),\n            width: 2.5,\n          ),\n          boxShadow: [\n            BoxShadow(\n              color: color.withValues(alpha: isPressed ? 0.65 : 0.3),\n              blurRadius: isPressed ? 14 : 8,\n              spreadRadius: isPressed ? 2 : 0,\n            ),\n          ],\n        ),\n        child: Center(\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              Text(\n                label,\n                style: const TextStyle(\n                  color: Colors.white,\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 13,\n                  letterSpacing: 0.8,\n                ),\n              ),\n              Text(\n                subLabel,\n                style: TextStyle(\n                  color: Colors.white.withValues(alpha: 0.7),\n                  fontFamily: 'JetBrainsMono',\n                  fontSize: 9,\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _JoystickPainter extends CustomPainter {\n  final Offset delta;\n  final bool isActive;\n\n  _JoystickPainter({required this.delta, required this.isActive});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final Offset center = size.center(Offset.zero);\n    final double radius = size.width / 2;\n\n    // Outer base circle\n    final Paint baseFill = Paint()\n      ..color = Colors.black.withValues(alpha: 0.45)\n      ..style = PaintingStyle.fill;\n    final Paint baseBorder = Paint()\n      ..color = Colors.white.withValues(alpha: isActive ? 0.75 : 0.38)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2;\n\n    canvas.drawCircle(center, radius - 2, baseFill);\n    canvas.drawCircle(center, radius - 2, baseBorder);\n\n    // 8-direction tick marks\n    final Paint tickPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.28)\n      ..strokeWidth = 1.5\n      ..strokeCap = StrokeCap.round;\n    for (int i = 0; i < 8; i++) {\n      final double a = i * (pi / 4);\n      final Offset p1 = center + Offset(cos(a), sin(a)) * (radius * 0.58);\n      final Offset p2 = center + Offset(cos(a), sin(a)) * (radius * 0.80);\n      canvas.drawLine(p1, p2, tickPaint);\n    }\n\n    // Thumbstick knob\n    final Offset knobPos = center + delta * (radius * 0.52);\n    final Paint stemPaint = Paint()\n      ..color = Colors.white38\n      ..strokeWidth = 5\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(center, knobPos, stemPaint);\n\n    final Paint knobFill = Paint()\n      ..color = isActive\n          ? kCrimsonRed.withValues(alpha: 0.9)\n          : const Color(0xFF475569).withValues(alpha: 0.85);\n    final Paint knobBorder = Paint()\n      ..color = Colors.white.withValues(alpha: 0.85)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.0;\n\n    canvas.drawCircle(knobPos, radius * 0.34, knobFill);\n    canvas.drawCircle(knobPos, radius * 0.34, knobBorder);\n  }\n\n  @override\n  bool shouldRepaint(covariant _JoystickPainter oldDelegate) =>\n      oldDelegate.delta != delta || oldDelegate.isActive != isActive;\n}\n\nclass _RudolphContraPainter extends CustomPainter {\n  final double worldTime;\n  final double playerX;\n  final double playerY;\n  final bool facingRight;\n  final double aimAngle;\n  final double walkCycle;\n  final bool isGrounded;\n  final double muzzleFlashTimer;\n  final double recoilOffset;\n  final int kills;\n  final List<_Platform> platforms;\n  final List<_Bullet> bullets;\n  final List<_ReindeerTarget> reindeer;\n  final List<_BloodParticle> bloodParticles;\n  final List<_SnowStain> snowStains;\n  final List<_ShellCasing> shells;\n  final List<_FloatingText> floatingTexts;\n  final List<_HorizonCross> horizonCrosses;\n  final List<_Snowflake> snowflakes;\n  final List<_Star> stars;\n\n  _RudolphContraPainter({\n    required this.worldTime,\n    required this.playerX,\n    required this.playerY,\n    required this.facingRight,\n    required this.aimAngle,\n    required this.walkCycle,\n    required this.isGrounded,\n    required this.muzzleFlashTimer,\n    required this.recoilOffset,\n    required this.kills,\n    required this.platforms,\n    required this.bullets,\n    required this.reindeer,\n    required this.bloodParticles,\n    required this.snowStains,\n    required this.shells,\n    required this.floatingTexts,\n    required this.horizonCrosses,\n    required this.snowflakes,\n    required this.stars,\n  });\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    _drawNightSkyAndStars(canvas, size);\n    _drawGrinningMoon(canvas, size);\n    _drawDistantMountainsAndCrosses(canvas, size);\n    _drawSnowcappedTreesAndGingerbread(canvas, size);\n    _drawMainSnowGround(canvas, size);\n    _drawPlatforms(canvas, size);\n    _drawSnowBloodStains(canvas, size);\n    _drawShellCasings(canvas, size);\n\n    // Draw unarmed target reindeer\n    for (final r in reindeer) {\n      _drawCartoonReindeerTarget(canvas, size, r);\n    }\n\n    // Draw playable Rudolph commando\n    _drawRudolphCommando(canvas, size);\n\n    // Draw bullets & blood particles\n    _drawBullets(canvas, size);\n    _drawBloodParticles(canvas, size);\n    _drawFloatingTexts(canvas, size);\n    _drawSnowfall(canvas, size);\n  }\n\n  void _drawNightSkyAndStars(Canvas canvas, Size size) {\n    final Rect skyRect = Offset.zero & size;\n    final Paint skyPaint = Paint()\n      ..shader = const LinearGradient(\n        begin: Alignment.topCenter,\n        end: Alignment.bottomCenter,\n        colors: [kNightTop, kNightBottom, Color(0xFF1B2A4A)],\n        stops: [0.0, 0.55, 0.85],\n      ).createShader(skyRect);\n    canvas.drawRect(skyRect, skyPaint);\n\n    final Paint starPaint = Paint()..style = PaintingStyle.fill;\n    for (final s in stars) {\n      final double alpha = 0.45 + 0.55 * sin(worldTime * 2.2 + s.twinklePhase).abs();\n      starPaint.color = Colors.white.withValues(alpha: alpha);\n      canvas.drawCircle(\n        Offset(s.x * size.width, s.y * size.height),\n        s.size,\n        starPaint,\n      );\n    }\n  }\n\n  void _drawGrinningMoon(Canvas canvas, Size size) {\n    // \"The moon grins down onto the snowcapped trees.\"\n    final Offset moonCenter = Offset(size.width * 0.80, size.height * 0.16);\n    final double moonRadius = min(size.width, size.height) * 0.085;\n\n    // Outer lunar glow\n    for (int i = 3; i >= 1; i--) {\n      final Paint glowPaint = Paint()\n        ..color = const Color(0xFFFFF3B0).withValues(alpha: 0.06 * i);\n      canvas.drawCircle(moonCenter, moonRadius * (1.0 + i * 0.35), glowPaint);\n    }\n\n    // Moon body with cartoon outline\n    final Paint moonFill = Paint()\n      ..shader = RadialGradient(\n        center: const Alignment(-0.25, -0.25),\n        radius: 0.9,\n        colors: const [Color(0xFFFFFAE5), Color(0xFFFDE68A), Color(0xFFF59E0B)],\n      ).createShader(Rect.fromCircle(center: moonCenter, radius: moonRadius));\n    final Paint outlinePaint = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.5;\n\n    canvas.drawCircle(moonCenter, moonRadius, moonFill);\n    canvas.drawCircle(moonCenter, moonRadius, outlinePaint);\n\n    // Subtle moon craters\n    final Paint craterPaint = Paint()\n      ..color = const Color(0xFFD97706).withValues(alpha: 0.22);\n    canvas.drawCircle(\n      moonCenter + Offset(-moonRadius * 0.42, -moonRadius * 0.35),\n      moonRadius * 0.16,\n      craterPaint,\n    );\n    canvas.drawCircle(\n      moonCenter + Offset(moonRadius * 0.48, -moonRadius * 0.12),\n      moonRadius * 0.12,\n      craterPaint,\n    );\n\n    // Mischievous cartoon eyes looking down at the snowfield\n    final Paint eyeWhite = Paint()..color = Colors.white;\n    final Paint pupilPaint = Paint()..color = const Color(0xFF0F172A);\n    final Offset leftEye = moonCenter + Offset(-moonRadius * 0.28, -moonRadius * 0.12);\n    final Offset rightEye = moonCenter + Offset(moonRadius * 0.22, -moonRadius * 0.12);\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: leftEye,\n        width: moonRadius * 0.28,\n        height: moonRadius * 0.22,\n      ),\n      eyeWhite,\n    );\n    canvas.drawOval(\n      Rect.fromCenter(\n        center: rightEye,\n        width: moonRadius * 0.28,\n        height: moonRadius * 0.22,\n      ),\n      eyeWhite,\n    );\n    canvas.drawCircle(\n      leftEye + Offset(-moonRadius * 0.03, moonRadius * 0.04),\n      moonRadius * 0.07,\n      pupilPaint,\n    );\n    canvas.drawCircle(\n      rightEye + Offset(-moonRadius * 0.03, moonRadius * 0.04),\n      moonRadius * 0.07,\n      pupilPaint,\n    );\n\n    // Angry/sly brow line\n    final Paint browPaint = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..strokeWidth = 2.4\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(\n      leftEye + Offset(-moonRadius * 0.15, -moonRadius * 0.13),\n      leftEye + Offset(moonRadius * 0.12, -moonRadius * 0.06),\n      browPaint,\n    );\n    canvas.drawLine(\n      rightEye + Offset(-moonRadius * 0.12, -moonRadius * 0.06),\n      rightEye + Offset(moonRadius * 0.15, -moonRadius * 0.13),\n      browPaint,\n    );\n\n    // Wide cartoon grin with teeth\n    final Path grinPath = Path()\n      ..moveTo(moonCenter.dx - moonRadius * 0.52, moonCenter.dy + moonRadius * 0.12)\n      ..quadraticBezierTo(\n        moonCenter.dx,\n        moonCenter.dy + moonRadius * 0.65,\n        moonCenter.dx + moonRadius * 0.52,\n        moonCenter.dy + moonRadius * 0.10,\n      )\n      ..quadraticBezierTo(\n        moonCenter.dx,\n        moonCenter.dy + moonRadius * 0.35,\n        moonCenter.dx - moonRadius * 0.52,\n        moonCenter.dy + moonRadius * 0.12,\n      )\n      ..close();\n\n    canvas.drawPath(grinPath, Paint()..color = Colors.white);\n    canvas.drawPath(grinPath, outlinePaint);\n\n    // Grin teeth dividers\n    final Paint toothLine = Paint()\n      ..color = const Color(0xFF1E293B)\n      ..strokeWidth = 1.5;\n    for (int t = -2; t <= 2; t++) {\n      final double tx = moonCenter.dx + t * moonRadius * 0.15;\n      canvas.drawLine(\n        Offset(tx, moonCenter.dy + moonRadius * 0.22),\n        Offset(tx, moonCenter.dy + moonRadius * 0.37),\n        toothLine,\n      );\n    }\n  }\n\n  void _drawDistantMountainsAndCrosses(Canvas canvas, Size size) {\n    final double horizonY = size.height * 0.68;\n\n    // Distant snow-covered mountain range\n    final Path mountainPath = Path()\n      ..moveTo(0, size.height)\n      ..lineTo(0, horizonY)\n      ..lineTo(size.width * 0.14, size.height * 0.50)\n      ..lineTo(size.width * 0.29, horizonY - 10)\n      ..lineTo(size.width * 0.48, size.height * 0.45)\n      ..lineTo(size.width * 0.66, horizonY - 5)\n      ..lineTo(size.width * 0.84, size.height * 0.52)\n      ..lineTo(size.width, horizonY - 12)\n      ..lineTo(size.width, size.height)\n      ..close();\n\n    canvas.drawPath(\n      mountainPath,\n      Paint()..color = const Color(0xFF1E2D4D),\n    );\n\n    // Rolling mid-ground snow hills\n    final Path hillPath = Path()\n      ..moveTo(0, size.height)\n      ..lineTo(0, horizonY + 8)\n      ..quadraticBezierTo(\n        size.width * 0.25,\n        horizonY - 22,\n        size.width * 0.52,\n        horizonY + 6,\n      )\n      ..quadraticBezierTo(\n        size.width * 0.78,\n        horizonY - 20,\n        size.width,\n        horizonY + 4,\n      )\n      ..lineTo(size.width, size.height)\n      ..close();\n\n    canvas.drawPath(\n      hillPath,\n      Paint()..color = const Color(0xFF334E68),\n    );\n\n    // \"The next day, the crosses lined the horizon.\"\n    final Paint crossPaint = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..strokeWidth = 2.6\n      ..strokeCap = StrokeCap.round;\n    for (final c in horizonCrosses) {\n      final double cx = c.x * size.width;\n      final double cy = horizonY - 6;\n      canvas.save();\n      canvas.translate(cx, cy);\n      canvas.rotate(c.tilt);\n      canvas.drawLine(const Offset(0, 4), const Offset(0, -18), crossPaint);\n      canvas.drawLine(const Offset(-6, -11), const Offset(6, -11), crossPaint);\n      canvas.restore();\n    }\n  }\n\n  void _drawSnowcappedTreesAndGingerbread(Canvas canvas, Size size) {\n    final double groundPx = size.height * 0.80;\n\n    // Distant gingerbread house silhouette with billowing chimney (\"Gingerbread house with a chimney that billows\")\n    final double houseX = size.width * 0.11;\n    final double houseY = groundPx - 36;\n    final Paint housePaint = Paint()..color = const Color(0xFF5C3A21);\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.0;\n\n    // Chimney smoke puffs\n    for (int i = 0; i < 4; i++) {\n      final double puffProgress = ((worldTime * 0.4 + i * 0.25) % 1.0);\n      final Offset puffCenter = Offset(\n        houseX + 18 + sin(worldTime * 2 + i) * 6,\n        houseY - 18 - puffProgress * 38,\n      );\n      canvas.drawCircle(\n        puffCenter,\n        5 + puffProgress * 9,\n        Paint()..color = Colors.white.withValues(alpha: (1 - puffProgress) * 0.28),\n      );\n    }\n\n    canvas.drawRect(\n      Rect.fromLTWH(houseX + 13, houseY - 16, 9, 18),\n      housePaint,\n    );\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 18, houseY, 38, 36),\n      housePaint,\n    );\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 18, houseY, 38, 36),\n      outline,\n    );\n    // Warm glowing window\n    canvas.drawRect(\n      Rect.fromLTWH(houseX - 6, houseY + 10, 12, 12),\n      Paint()..color = const Color(0xFFFBBF24),\n    );\n    // Snow-frosted roof\n    final Path roofSnow = Path()\n      ..moveTo(houseX - 24, houseY + 3)\n      ..lineTo(houseX + 1, houseY - 18)\n      ..lineTo(houseX + 26, houseY + 3)\n      ..close();\n    canvas.drawPath(roofSnow, Paint()..color = kSnowWhite);\n    canvas.drawPath(roofSnow, outline);\n\n    // Snowcapped pine trees across the background\n    final List<double> treePositions = [0.04, 0.21, 0.37, 0.54, 0.72, 0.91];\n    for (int i = 0; i < treePositions.length; i++) {\n      final double tx = treePositions[i] * size.width;\n      final double scale = (i.isEven ? 1.0 : 0.82);\n      _drawSingleSnowTree(canvas, Offset(tx, groundPx), 68 * scale);\n    }\n  }\n\n  void _drawSingleSnowTree(Canvas canvas, Offset base, double height) {\n    final Paint trunkPaint = Paint()..color = const Color(0xFF4A2C11);\n    final Paint pinePaint = Paint()..color = const Color(0xFF14532D);\n    final Paint snowCapPaint = Paint()..color = kSnowWhite;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0B132B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 1.8;\n\n    canvas.drawRect(\n      Rect.fromCenter(\n        center: base - Offset(0, height * 0.1),\n        width: height * 0.16,\n        height: height * 0.22,\n      ),\n      trunkPaint,\n    );\n\n    for (int tier = 0; tier < 3; tier++) {\n      final double tierBottom = base.dy - height * (0.18 + tier * 0.24);\n      final double tierTop = tierBottom - height * 0.36;\n      final double halfWidth = height * (0.38 - tier * 0.07);\n\n      final Path foliage = Path()\n        ..moveTo(base.dx, tierTop)\n        ..lineTo(base.dx - halfWidth, tierBottom)\n        ..lineTo(base.dx + halfWidth, tierBottom)\n        ..close();\n      canvas.drawPath(foliage, pinePaint);\n      canvas.drawPath(foliage, outline);\n\n      // Thick cartoon snow cap on top of each pine tier\n      final Path snowCap = Path()\n        ..moveTo(base.dx, tierTop)\n        ..lineTo(base.dx - halfWidth * 0.58, tierTop + (tierBottom - tierTop) * 0.52)\n        ..quadraticBezierTo(\n          base.dx,\n          tierTop + (tierBottom - tierTop) * 0.66,\n          base.dx + halfWidth * 0.58,\n          tierTop + (tierBottom - tierTop) * 0.52,\n        )\n        ..close();\n      canvas.drawPath(snowCap, snowCapPaint);\n    }\n  }\n\n  void _drawMainSnowGround(Canvas canvas, Size size) {\n    final double groundY = size.height * 0.80;\n\n    // Deep snowbank fill\n    final Rect snowRect = Rect.fromLTWH(0, groundY, size.width, size.height - groundY);\n    final Paint snowPaint = Paint()\n      ..shader = const LinearGradient(\n        begin: Alignment.topCenter,\n        end: Alignment.bottomCenter,\n        colors: [kSnowWhite, Color(0xFFD9E2EC), Color(0xFF9FB3C8)],\n      ).createShader(snowRect);\n    canvas.drawRect(snowRect, snowPaint);\n\n    // Cartoon wavy snowdrift ridge line\n    final Path driftPath = Path()..moveTo(0, groundY);\n    for (double x = 0; x <= size.width; x += size.width / 8) {\n      driftPath.quadraticBezierTo(\n        x + size.width / 16,\n        groundY - 5,\n        x + size.width / 8,\n        groundY,\n      );\n    }\n    canvas.drawPath(\n      driftPath,\n      Paint()\n        ..color = const Color(0xFF1E293B)\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 2.5,\n    );\n  }\n\n  void _drawPlatforms(Canvas canvas, Size size) {\n    final Paint rockPaint = Paint()..color = const Color(0xFF334155);\n    final Paint snowTopPaint = Paint()..color = kSnowWhite;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2;\n\n    for (final p in platforms) {\n      final double left = p.xMin * size.width;\n      final double right = p.xMax * size.width;\n      final double top = p.y * size.height;\n      final double width = right - left;\n\n      // Icy rock base\n      final RRect baseRect = RRect.fromRectAndRadius(\n        Rect.fromLTWH(left, top, width, 18),\n        const Radius.circular(8),\n      );\n      canvas.drawRRect(baseRect, rockPaint);\n      canvas.drawRRect(baseRect, outline);\n\n      // Thick snow blanket on top of the ledge\n      final RRect snowCap = RRect.fromRectAndRadius(\n        Rect.fromLTWH(left - 3, top - 4, width + 6, 11),\n        const Radius.circular(6),\n      );\n      canvas.drawRRect(snowCap, snowTopPaint);\n      canvas.drawRRect(snowCap, outline);\n    }\n  }\n\n  void _drawSnowBloodStains(Canvas canvas, Size size) {\n    for (final stain in snowStains) {\n      final Offset center = Offset(\n        stain.x * size.width,\n        stain.y * size.height + 2,\n      );\n      final Rect oval = Rect.fromCenter(\n        center: center,\n        width: stain.radiusX * size.width,\n        height: stain.radiusY * size.height + 4,\n      );\n      canvas.drawOval(\n        oval,\n        Paint()..color = kCrimsonRed.withValues(alpha: 0.82),\n      );\n      canvas.drawOval(\n        oval.deflate(2),\n        Paint()..color = kDarkBlood.withValues(alpha: 0.65),\n      );\n    }\n  }\n\n  void _drawShellCasings(Canvas canvas, Size size) {\n    final Paint brassPaint = Paint()..color = const Color(0xFFF59E0B);\n    for (final s in shells) {\n      canvas.save();\n      canvas.translate(s.x * size.width, s.y * size.height);\n      canvas.rotate(s.rotation);\n      canvas.drawRect(\n        const Rect.fromLTWH(-3, -1.5, 6, 3),\n        brassPaint,\n      );\n      canvas.restore();\n    }\n  }\n\n  void _drawCartoonReindeerTarget(\n    Canvas canvas,\n    Size size,\n    _ReindeerTarget r,\n  ) {\n    final double cx = r.x * size.width;\n    final double cy = r.y * size.height;\n    final bool movingRight = r.vx >= 0;\n    final bool panicked = r.panicTimer > 0;\n\n    // Fur palette variations so each reindeer looks distinct and detailed\n    final List<Color> coatColors = [\n      const Color(0xFF8D5524),\n      const Color(0xFFA0522D),\n      const Color(0xFF6F4E37),\n    ];\n    final Color mainCoat = r.hitFlash > 0\n        ? kCrimsonRed\n        : coatColors[r.furVariant % coatColors.length];\n    const Color bellyCream = Color(0xFFF3E5AB);\n    const Color darkHoof = Color(0xFF1F1610);\n    const Color antlerTan = Color(0xFFD2B48C);\n\n    final Paint coatPaint = Paint()..color = mainCoat;\n    final Paint bellyPaint = Paint()..color = bellyCream;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF1A110B)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.2\n      ..strokeJoin = StrokeJoin.round;\n\n    canvas.save();\n    canvas.translate(cx, cy);\n\n    // Shadow on snow\n    if (!r.isFlying) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(0, 0), width: 48, height: 10),\n        Paint()..color = Colors.black.withValues(alpha: 0.28),\n      );\n    }\n\n    canvas.save();\n    if (!movingRight) {\n      canvas.scale(-1, 1);\n    }\n\n    // Animated 4-legged deer gallop/walk cycle\n    final double swing = sin(r.legPhase) * (panicked ? 11.0 : 7.0);\n    final double swingOpp = cos(r.legPhase) * (panicked ? 11.0 : 7.0);\n\n    void drawDeerLeg(Offset hip, double angleOffset, bool isBackLayer) {\n      final Paint legPaint = Paint()\n        ..color = isBackLayer\n            ? Color.lerp(mainCoat, Colors.black, 0.25)!\n            : mainCoat\n        ..strokeWidth = 5.5\n        ..strokeCap = StrokeCap.round;\n      final Offset knee = hip + Offset(angleOffset * 0.45, 11);\n      final Offset hoof = knee + Offset(angleOffset * 0.65, 11);\n      canvas.drawLine(hip, knee, legPaint);\n      canvas.drawLine(knee, hoof, legPaint);\n\n      // Cloven hoof\n      final Path hoofPath = Path()\n        ..moveTo(hoof.dx - 3, hoof.dy - 2)\n        ..lineTo(hoof.dx + 4, hoof.dy - 2)\n        ..lineTo(hoof.dx + 5, hoof.dy + 3)\n        ..lineTo(hoof.dx - 3, hoof.dy + 3)\n        ..close();\n      canvas.drawPath(hoofPath, Paint()..color = darkHoof);\n    }\n\n    // Back legs\n    drawDeerLeg(const Offset(-14, -22), swingOpp, true);\n    drawDeerLeg(const Offset(12, -22), -swing, true);\n\n    // Fluffy white deer tail\n    final Path tailPath = Path()\n      ..moveTo(-20, -32)\n      ..quadraticBezierTo(-32, -40, -28, -26)\n      ..quadraticBezierTo(-24, -22, -18, -26)\n      ..close();\n    canvas.drawPath(tailPath, bellyPaint);\n    canvas.drawPath(tailPath, outline);\n\n    // Reindeer torso (sleek cartoon deer body with cream underbelly and spots)\n    final RRect bodyRRect = RRect.fromRectAndRadius(\n      Rect.fromCenter(center: const Offset(-2, -29), width: 42, height: 20),\n      const Radius.circular(10),\n    );\n    canvas.drawRRect(bodyRRect, coatPaint);\n\n    // Cream underbelly trim\n    canvas.drawArc(\n      Rect.fromCenter(center: const Offset(-2, -23), width: 34, height: 10),\n      0,\n      pi,\n      false,\n      bellyPaint,\n    );\n\n    // White fawn spots on back\n    final Paint spotPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.55);\n    canvas.drawCircle(const Offset(-12, -33), 2.5, spotPaint);\n    canvas.drawCircle(const Offset(-5, -35), 2.0, spotPaint);\n    canvas.drawCircle(const Offset(-9, -29), 1.8, spotPaint);\n    canvas.drawRRect(bodyRRect, outline);\n\n    // Front legs\n    drawDeerLeg(const Offset(-12, -22), swing, false);\n    drawDeerLeg(const Offset(14, -22), -swingOpp, false);\n\n    // Long reindeer neck & festive red/green jingle bell collar\n    final Path neckPath = Path()\n      ..moveTo(8, -33)\n      ..lineTo(18, -50)\n      ..lineTo(26, -46)\n      ..lineTo(18, -24)\n      ..close();\n    canvas.drawPath(neckPath, coatPaint);\n    canvas.drawPath(neckPath, outline);\n\n    // Festive collar + gold jingle bells\n    final Paint collarPaint = Paint()\n      ..color = const Color(0xFFB91C1C)\n      ..strokeWidth = 4.5\n      ..strokeCap = StrokeCap.round;\n    canvas.drawLine(const Offset(10, -36), const Offset(21, -30), collarPaint);\n    canvas.drawCircle(\n      const Offset(16, -32),\n      3.2,\n      Paint()..color = const Color(0xFFFACC15),\n    );\n\n    // Multi-pronged branching antlers (unmistakably a reindeer!)\n    final Paint antlerPaint = Paint()\n      ..color = antlerTan\n      ..strokeWidth = 3.2\n      ..strokeCap = StrokeCap.round\n      ..style = PaintingStyle.stroke;\n    final Paint antlerOutline = Paint()\n      ..color = const Color(0xFF1A110B)\n      ..strokeWidth = 5.0\n      ..strokeCap = StrokeCap.round\n      ..style = PaintingStyle.stroke;\n\n    final Path antlers = Path()\n      // Back antler beam + tines\n      ..moveTo(19, -54)\n      ..lineTo(11, -72)\n      ..moveTo(15, -63)\n      ..lineTo(7, -66)\n      ..moveTo(13, -68)\n      ..lineTo(18, -75)\n      // Front antler beam + tines\n      ..moveTo(22, -54)\n      ..lineTo(20, -75)\n      ..moveTo(21, -64)\n      ..lineTo(28, -68)\n      ..moveTo(20, -70)\n      ..lineTo(14, -77);\n    canvas.drawPath(antlers, antlerOutline);\n    canvas.drawPath(antlers, antlerPaint);\n\n    // Reindeer ear\n    final Path earPath = Path()\n      ..moveTo(16, -50)\n      ..quadraticBezierTo(6, -56, 9, -46)\n      ..close();\n    canvas.drawPath(earPath, coatPaint);\n    canvas.drawPath(earPath, outline);\n\n    // Reindeer head & elongated snout\n    final Path headPath = Path()\n      ..moveTo(14, -52)\n      ..quadraticBezierTo(24, -58, 29, -50)\n      ..lineTo(39, -47)\n      ..quadraticBezierTo(41, -41, 34, -39)\n      ..lineTo(18, -41)\n      ..close();\n    canvas.drawPath(headPath, coatPaint);\n    canvas.drawPath(headPath, outline);\n\n    // Dark reindeer nose (non-glowing)\n    canvas.drawCircle(\n      const Offset(38, -45),\n      3.2,\n      Paint()..color = darkHoof,\n    );\n\n    // Expressive cartoon eye (wide-eyed panic when Rudolph shoots!)\n    final Offset eyeCenter = const Offset(25, -48);\n    canvas.drawCircle(\n      eyeCenter,\n      panicked ? 4.4 : 3.4,\n      Paint()..color = Colors.white,\n    );\n    canvas.drawCircle(\n      eyeCenter,\n      panicked ? 4.4 : 3.4,\n      Paint()\n        ..color = Colors.black\n        ..style = PaintingStyle.stroke\n        ..strokeWidth = 1.3,\n    );\n    canvas.drawCircle(\n      eyeCenter + Offset(panicked ? -0.5 : 0.8, 0),\n      panicked ? 1.6 : 1.8,\n      Paint()..color = Colors.black,\n    );\n\n    // Open shocked mouth & sweat drop when panicked\n    if (panicked) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(31, -41), width: 6, height: 4),\n        Paint()..color = const Color(0xFF7F1D1D),\n      );\n    }\n\n    canvas.restore(); // restore flip\n\n    // Name tag + HP bar above reindeer\n    final TextPainter nameTp = TextPainter(\n      text: TextSpan(\n        text: r.name,\n        style: TextStyle(\n          color: panicked ? const Color(0xFFFCA5A5) : Colors.white,\n          fontFamily: 'JetBrainsMono',\n          fontSize: 10,\n          fontWeight: FontWeight.bold,\n          shadows: const [Shadow(color: Colors.black, blurRadius: 4)],\n        ),\n      ),\n      textDirection: TextDirection.ltr,\n    )..layout();\n    nameTp.paint(canvas, Offset(-nameTp.width / 2, -88));\n\n    // Mini health bar if damaged\n    if (r.hp < r.maxHp) {\n      const double barW = 30;\n      canvas.drawRect(\n        const Rect.fromLTWH(-barW / 2, -74, barW, 4),\n        Paint()..color = Colors.black54,\n      );\n      canvas.drawRect(\n        Rect.fromLTWH(-barW / 2, -74, barW * (r.hp / r.maxHp), 4),\n        Paint()..color = kCrimsonRed,\n      );\n    }\n\n    canvas.restore();\n  }\n\n  void _drawRudolphCommando(Canvas canvas, Size size) {\n    final double cx = playerX * size.width;\n    final double cy = playerY * size.height;\n\n    const Color rudolphCoat = Color(0xFF9A5B25);\n    const Color bellyCream = Color(0xFFF5E6C4);\n    const Color darkHoof = Color(0xFF1A110B);\n    const Color antlerColor = Color(0xFFE6CCB2);\n\n    final Paint coatPaint = Paint()..color = rudolphCoat;\n    final Paint bellyPaint = Paint()..color = bellyCream;\n    final Paint outline = Paint()\n      ..color = const Color(0xFF140C06)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = 2.4\n      ..strokeJoin = StrokeJoin.round;\n\n    canvas.save();\n    canvas.translate(cx, cy);\n\n    // Ground shadow\n    if (isGrounded) {\n      canvas.drawOval(\n        Rect.fromCenter(center: const Offset(0, 0), width: 54, height: 12),\n        Paint()..color = Colors.black.withValues(alpha: 0.35),\n      );\n    }\n\n    canvas.save();\n    if (!facingRight) {\n      canvas.scale(-1, 1);\n    }\n\n    final double legSwing = isGrounded ? sin(walkCycle) * 10.0 : 8.0;\n\n    // Hind reindeer legs in heroic action stance\n    void drawRudolphLeg(Offset hip, double swingOffset, bool isBack) {\n      final Paint legP = Paint()\n        ..color = isBack\n            ? Color.lerp(rudolphCoat, Colors.black, 0.22)!\n            : rudolphCoat\n        ..strokeWidth = 6.5\n        ..strokeCap = StrokeCap.round;\n      final Offset knee = hip + Offset(swingOffset * 0.5, 12);\n      final Offset hoof = knee + Offset(swingOffset * 0.7, 12);\n      canvas.drawLine(hip, knee, legP);\n      canvas.drawLine(knee, hoof, legP);\n      canvas.drawRect(\n        Rect.fromCenter(center: hoof, width: 8, height: 5),\n        Paint()..color = darkHoof,\n      );\n    }\n\n    drawRudolphLeg(const Offset(-12, -24), -legSwing, true);\n    drawRudolphLeg(const Offset(10, -24), legSwing, true);\n\n    // Fluffy white tail\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(-23, -34), width: 12, height: 8),\n      bellyPaint,\n    );\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(-23, -34), width: 12, height: 8),\n      outline,\n    );\n\n    // Muscular reindeer lower body + upright commando chest\n    final RRect lowerBody = RRect.fromRectAndRadius(\n      Rect.fromCenter(center: const Offset(-3, -30), width: 40, height: 20),\n      const Radius.circular(10),\n    );\n    canvas.drawRRect(lowerBody, coatPaint);\n    canvas.drawRRect(lowerBody, outline);\n\n    drawRudolphLeg(const Offset(-9, -24), legSwing, false);\n\n    // Upright chest & neck\n    final Path chestPath = Path()\n      ..moveTo(-6, -34)\n      ..lineTo(6, -58)\n      ..lineTo(20, -54)\n      ..lineTo(15, -26)\n      ..close();\n    canvas.drawPath(chestPath, coatPaint);\n    canvas.drawPath(\n      Path()\n        ..moveTo(8, -54)\n        ..lineTo(19, -52)\n        ..lineTo(15, -30)\n        ..lineTo(6, -32)\n        ..close(),\n      bellyPaint,\n    );\n    canvas.drawPath(chestPath, outline);\n\n    // Tactical ammo bandolier across Rudolph's chest\n    final Paint strapPaint = Paint()\n      ..color = const Color(0xFF1F2937)\n      ..strokeWidth = 5.0;\n    canvas.drawLine(const Offset(-3, -32), const Offset(15, -52), strapPaint);\n    for (int b = 0; b < 4; b++) {\n      final double t = b / 3.0;\n      final Offset shellPos = Offset(-1 + t * 14, -34 - t * 16);\n      canvas.drawCircle(\n        shellPos,\n        2.2,\n        Paint()..color = const Color(0xFFFBBF24),\n      );\n    }\n\n    // Large branching reindeer antlers (\"Antlers covered in stains of their enemies\")\n    final Path antlerPath = Path()\n      ..moveTo(7, -64)\n      ..lineTo(-5, -86)\n      ..moveTo(1, -74)\n      ..lineTo(-9, -77)\n      ..moveTo(-2, -80)\n      ..lineTo(5, -88)\n      ..moveTo(12, -64)\n      ..lineTo(11, -89)\n      ..moveTo(11, -75)\n      ..lineTo(20, -80)\n      ..moveTo(11, -82)\n      ..lineTo(4, -90);\n\n    canvas.drawPath(\n      antlerPath,\n      Paint()\n        ..color = const Color(0xFF140C06)\n        ..strokeWidth = 5.8\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n    canvas.drawPath(\n      antlerPath,\n      Paint()\n        ..color = antlerColor\n        ..strokeWidth = 3.6\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n\n    // Crimson blood stains on Rudolph's antlers when kills > 0\n    if (kills > 0) {\n      final Paint bloodAntler = Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 3.8\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke;\n      final Path stainedTips = Path()\n        ..moveTo(-1, -79)\n        ..lineTo(-5, -86)\n        ..moveTo(11, -81)\n        ..lineTo(11, -89)\n        ..moveTo(15, -77)\n        ..lineTo(20, -80);\n      canvas.drawPath(stainedTips, bloodAntler);\n    }\n\n    // Rudolph's head, ear, and Contra red commando headband with trailing tails\n    final Path headbandTails = Path()\n      ..moveTo(2, -60)\n      ..quadraticBezierTo(-14, -64 + sin(worldTime * 12) * 4, -24, -56)\n      ..moveTo(2, -57)\n      ..quadraticBezierTo(-12, -57 + cos(worldTime * 12) * 4, -21, -50);\n    canvas.drawPath(\n      headbandTails,\n      Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 3.5\n        ..strokeCap = StrokeCap.round\n        ..style = PaintingStyle.stroke,\n    );\n\n    final Path headPath = Path()\n      ..moveTo(3, -62)\n      ..quadraticBezierTo(14, -68, 21, -60)\n      ..lineTo(34, -56)\n      ..quadraticBezierTo(36, -49, 27, -47)\n      ..lineTo(8, -49)\n      ..close();\n    canvas.drawPath(headPath, coatPaint);\n    canvas.drawPath(headPath, outline);\n\n    // Red Contra headband across forehead\n    canvas.drawLine(\n      const Offset(4, -60),\n      const Offset(21, -59),\n      Paint()\n        ..color = kCrimsonRed\n        ..strokeWidth = 4.5\n        ..strokeCap = StrokeCap.round,\n    );\n\n    // Fierce cartoon commando eye with angry brow\n    canvas.drawOval(\n      Rect.fromCenter(center: const Offset(17, -56), width: 7, height: 5.5),\n      Paint()..color = Colors.white,\n    );\n    canvas.drawCircle(\n      const Offset(18.5, -56),\n      2.0,\n      Paint()..color = Colors.black,\n    );\n    canvas.drawLine(\n      const Offset(13, -60),\n      const Offset(21, -57),\n      Paint()\n        ..color = Colors.black\n        ..strokeWidth = 2.2,\n    );\n\n    // Glowing Red Nose (\"Please don't make light of a nose that's glowing\")\n    const Offset nosePos = Offset(34, -54);\n    for (int g = 3; g >= 1; g--) {\n      canvas.drawCircle(\n        nosePos,\n        4.5 + g * 4.5,\n        Paint()..color = kNoseGlow.withValues(alpha: 0.14 * g),\n      );\n    }\n    canvas.drawCircle(nosePos, 4.8, Paint()..color = const Color(0xFFFF002B));\n    canvas.drawCircle(\n      nosePos + const Offset(-1.2, -1.2),\n      1.6,\n      Paint()..color = Colors.white,\n    );\n\n    canvas.restore(); // restore horizontal flip so gun rotates accurately in world space\n\n    // Draw Contra Heavy Assault Rifle / Twelve-Gauge aimed along aimAngle\n    canvas.save();\n    final double recoilPx = recoilOffset * size.width;\n    canvas.translate(\n      -cos(aimAngle) * recoilPx,\n      -42 - sin(aimAngle) * recoilPx,\n    );\n    canvas.rotate(aimAngle);\n    if (!facingRight) {\n      canvas.scale(1, -1);\n    }\n\n    // Gun stock, receiver, barrel, and magazine\n    final Paint gunMetal = Paint()..color = const Color(0xFF1E293B);\n    final Paint gunHighlight = Paint()..color = const Color(0xFF64748B);\n    // Stock\n    canvas.drawRRect(\n      RRect.fromRectAndRadius(\n        const Rect.fromLTWH(-14, -3, 14, 7),\n        const Radius.circular(2),\n      ),\n      Paint()..color = const Color(0xFF451A03),\n    );\n    // Receiver body\n    canvas.drawRect(const Rect.fromLTWH(-2, -5, 22, 8), gunMetal);\n    canvas.drawRect(const Rect.fromLTWH(0, -4, 18, 2.5), gunHighlight);\n    // Curved banana magazine\n    final Path magPath = Path()\n      ..moveTo(6, 3)\n      ..lineTo(12, 3)\n      ..lineTo(15, 13)\n      ..lineTo(8, 13)\n      ..close();\n    canvas.drawPath(magPath, Paint()..color = const Color(0xFF0F172A));\n    // Heavy barrel + barrel shroud\n    canvas.drawRect(const Rect.fromLTWH(20, -4, 16, 4.5), gunMetal);\n    canvas.drawRect(\n      const Rect.fromLTWH(20, -5, 18, 9),\n      outline..strokeWidth = 1.6,\n    );\n\n    // Front hoof gripping the rifle handguard\n    canvas.drawCircle(\n      const Offset(14, 2),\n      4.2,\n      Paint()..color = darkHoof,\n    );\n\n    // Bright cartoon muzzle flash when firing\n    if (muzzleFlashTimer > 0) {\n      final Path flashPath = Path()\n        ..moveTo(36, -2)\n        ..lineTo(54, -10)\n        ..lineTo(47, -2)\n        ..lineTo(58, 0)\n        ..lineTo(47, 3)\n        ..lineTo(53, 10)\n        ..close();\n      canvas.drawPath(\n        flashPath,\n        Paint()..color = const Color(0xFFFef08a),\n      );\n      canvas.drawCircle(\n        const Offset(39, -1),\n        6,\n        Paint()..color = Colors.white,\n      );\n    }\n\n    canvas.restore();\n    canvas.restore();\n  }\n\n  void _drawBullets(Canvas canvas, Size size) {\n    for (final b in bullets) {\n      final Offset pos = Offset(b.x * size.width, b.y * size.height);\n      final double angle = atan2(b.vy, b.vx);\n      canvas.save();\n      canvas.translate(pos.dx, pos.dy);\n      canvas.rotate(angle);\n\n      // Glowing Contra energy/tracer shell\n      canvas.drawRRect(\n        RRect.fromRectAndRadius(\n          const Rect.fromLTWH(-9, -3.2, 18, 6.4),\n          const Radius.circular(3),\n        ),\n        Paint()..color = const Color(0xFFEF4444).withValues(alpha: 0.45),\n      );\n      canvas.drawRRect(\n        RRect.fromRectAndRadius(\n          const Rect.fromLTWH(-6, -2, 12, 4),\n          const Radius.circular(2),\n        ),\n        Paint()..color = const Color(0xFFFEF08A),\n      );\n      canvas.restore();\n    }\n  }\n\n  void _drawBloodParticles(Canvas canvas, Size size) {\n    for (final p in bloodParticles) {\n      final Offset pos = Offset(p.x * size.width, p.y * size.height);\n      final Paint bloodPaint = Paint()\n        ..color = (p.isChunk ? kDarkBlood : kCrimsonRed).withValues(\n          alpha: p.life.clamp(0.0, 1.0),\n        );\n      canvas.drawCircle(pos, p.radius, bloodPaint);\n    }\n  }\n\n  void _drawFloatingTexts(Canvas canvas, Size size) {\n    for (final ft in floatingTexts) {\n      final TextPainter tp = TextPainter(\n        text: TextSpan(\n          text: ft.text,\n          style: TextStyle(\n            color: ft.color.withValues(alpha: ft.life.clamp(0.0, 1.0)),\n            fontFamily: 'JetBrainsMono',\n            fontWeight: ft.isBold ? FontWeight.bold : FontWeight.w600,\n            fontSize: ft.isBold ? 14 : 12,\n            shadows: const [Shadow(color: Colors.black, blurRadius: 4)],\n          ),\n        ),\n        textDirection: TextDirection.ltr,\n      )..layout();\n\n      tp.paint(\n        canvas,\n        Offset(ft.x * size.width - tp.width / 2, ft.y * size.height),\n      );\n    }\n  }\n\n  void _drawSnowfall(Canvas canvas, Size size) {\n    final Paint snowPaint = Paint()\n      ..color = Colors.white.withValues(alpha: 0.78);\n    for (final f in snowflakes) {\n      canvas.drawCircle(\n        Offset(f.x * size.width, f.y * size.height),\n        f.radius,\n        snowPaint,\n      );\n    }\n  }\n\n  @override\n  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;\n}\n\nclass _Platform {\n  final double xMin;\n  final double xMax;\n  final double y;\n\n  const _Platform({\n    required this.xMin,\n    required this.xMax,\n    required this.y,\n  });\n}\n\nclass _Bullet {\n  double x;\n  double y;\n  final double vx;\n  final double vy;\n\n  _Bullet({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n  });\n}\n\nclass _ReindeerTarget {\n  final String name;\n  double x;\n  double y;\n  final double baseY;\n  double vx;\n  double vy;\n  final bool isFlying;\n  int hp;\n  final int maxHp;\n  final int furVariant;\n  double legPhase;\n  double hitFlash = 0.0;\n  double panicTimer = 0.0;\n\n  _ReindeerTarget({\n    required this.name,\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.isFlying,\n    required this.hp,\n    required this.maxHp,\n    required this.furVariant,\n    required this.legPhase,\n  }) : baseY = y;\n}\n\nclass _BloodParticle {\n  double x;\n  double y;\n  double vx;\n  double vy;\n  final double radius;\n  double life;\n  final bool isChunk;\n\n  _BloodParticle({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.radius,\n    required this.life,\n    this.isChunk = false,\n  });\n}\n\nclass _SnowStain {\n  final double x;\n  final double y;\n  final double radiusX;\n  final double radiusY;\n\n  _SnowStain({\n    required this.x,\n    required this.y,\n    required this.radiusX,\n    required this.radiusY,\n  });\n}\n\nclass _ShellCasing {\n  double x;\n  double y;\n  double vx;\n  double vy;\n  double rotation;\n\n  _ShellCasing({\n    required this.x,\n    required this.y,\n    required this.vx,\n    required this.vy,\n    required this.rotation,\n  });\n}\n\nclass _FloatingText {\n  final String text;\n  final double x;\n  double y;\n  final Color color;\n  double life;\n  final bool isBold;\n\n  _FloatingText({\n    required this.text,\n    required this.x,\n    required this.y,\n    required this.color,\n    required this.life,\n    this.isBold = false,\n  });\n}\n\nclass _HorizonCross {\n  final double x;\n  final double tilt;\n\n  _HorizonCross({required this.x, required this.tilt});\n}\n\nclass _Snowflake {\n  double x;\n  double y;\n  final double radius;\n  final double speedY;\n  final double drift;\n  final double phase;\n\n  _Snowflake({\n    required this.x,\n    required this.y,\n    required this.radius,\n    required this.speedY,\n    required this.drift,\n    required this.phase,\n  });\n}\n\nclass _Star {\n  final double x;\n  final double y;\n  final double size;\n  final double twinklePhase;\n\n  _Star({\n    required this.x,\n    required this.y,\n    required this.size,\n    required this.twinklePhase,\n  });\n}\n",
  "lib/games/lemon_game.dart": "import 'dart:async';\nimport 'dart:math';\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:audioplayers/audioplayers.dart';\nimport 'package:flutter/material.dart';\n\nenum LemonItemType {\n  lemon,\n  crosstopPill,\n  elixirPotion,\n  blueCandle,\n  coffeeCup,\n  cherrySeven,\n}\n\nextension LemonItemTypeMeta on LemonItemType {\n  Color get themeColor {\n    switch (this) {\n      case LemonItemType.lemon:\n        return const Color(0xFFFACC15);\n      case LemonItemType.crosstopPill:\n        return const Color(0xFFEF4444);\n      case LemonItemType.elixirPotion:\n        return const Color(0xFFA855F7);\n      case LemonItemType.blueCandle:\n        return const Color(0xFF38BDF8);\n      case LemonItemType.coffeeCup:\n        return const Color(0xFFD97706);\n      case LemonItemType.cherrySeven:\n        return const Color(0xFFEC4899);\n    }\n  }\n\n  String get label {\n    switch (this) {\n      case LemonItemType.lemon:\n        return 'LEMON';\n      case LemonItemType.crosstopPill:\n        return 'CROSSTOP';\n      case LemonItemType.elixirPotion:\n        return 'ELIXIR';\n      case LemonItemType.blueCandle:\n        return 'CANDLEWAX';\n      case LemonItemType.coffeeCup:\n        return 'COLOMBIAN';\n      case LemonItemType.cherrySeven:\n        return 'CHERRY 7';\n    }\n  }\n}\n\nclass Pill {\n  final LemonItemType type;\n  final String id;\n\n  Pill(this.type) : id = UniqueKey().toString();\n\n  Color get color => type.themeColor;\n}\n\nclass LemonsGame extends StatefulWidget {\n  const LemonsGame({super.key});\n\n  @override\n  State<LemonsGame> createState() => _LemonsGameState();\n}\n\nclass _LemonsGameState extends State<LemonsGame> {\n  final AudioPlayer _audioPlayer = AudioPlayer();\n  final List<String> _playlist = [\n    'almost_intelligent.wav',\n    'crosstops.wav',\n    'c_u_next_tuesday.wav',\n    'drinking_outta_cups.wav',\n    'elixir.wav',\n    'florence.wav',\n    'it_seemed_like_a_good_idea_at_the_time.wav',\n    'you_call_this_mercy.wav',\n    'midnight_oil.wav',\n    'i_may_not_be_a_smart_man_but_i_know_what_love_is.wav',\n    'lets_take_it_apart_and_put_it_back_together.wav',\n    'and_thats_how_it_happened.wav',\n    'third_times_a_charm.wav',\n  ];\n\n  List<String> _musicQueue = [];\n  StreamSubscription? _playerCompleteSubscription;\n\n  final int _rows = 8;\n  final int _cols = 5;\n\n  final List<LemonItemType> _itemTypes = LemonItemType.values;\n\n  late List<List<Pill?>> _grid;\n  Point<int>? _selectedPoint;\n\n  int _score = 0;\n  bool _isWon = false;\n  bool _isGameOver = false;\n  bool _isProcessing = false;\n\n  Timer? _gameTimer;\n  int _secondsRemaining = 180;\n\n  @override\n  void initState() {\n    super.initState();\n    _initGrid(resetScore: true);\n    _setupAudioPlayer();\n  }\n\n  @override\n  void dispose() {\n    _playerCompleteSubscription?.cancel();\n    _audioPlayer.dispose();\n    _gameTimer?.cancel();\n    super.dispose();\n  }\n\n  void _setupAudioPlayer() {\n    _audioPlayer.setReleaseMode(ReleaseMode.release);\n\n    _playerCompleteSubscription = _audioPlayer.onPlayerComplete.listen((event) {\n      _playNextTrack();\n    });\n\n    _playNextTrack();\n  }\n\n  Future<void> _playNextTrack() async {\n    if (_playlist.isEmpty) return;\n\n    if (_musicQueue.isEmpty) {\n      _musicQueue = List.of(_playlist)..shuffle();\n    }\n\n    final nextSong = _musicQueue.removeAt(0);\n\n    try {\n      final fullPath = 'music/lemons/\$nextSong';\n      await _audioPlayer.setSource(AssetSource(fullPath));\n      await _audioPlayer.setVolume(0.5);\n      await _audioPlayer.resume();\n    } catch (e) {\n      debugPrint('Audio Error: \$e');\n    }\n  }\n\n  Future<void> _cleanupStragglers() async {\n    final Map<LemonItemType, int> typeCounts = {};\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) {\n          typeCounts[item.type] = (typeCounts[item.type] ?? 0) + 1;\n        }\n      }\n    }\n\n    final List<LemonItemType> doomedTypes = [];\n    typeCounts.forEach((type, count) {\n      if (count > 0 && count < 3) {\n        doomedTypes.add(type);\n      }\n    });\n\n    if (doomedTypes.isEmpty) return;\n\n    bool changed = false;\n    setState(() {\n      for (int y = 0; y < _rows; y++) {\n        for (int x = 0; x < _cols; x++) {\n          final item = _grid[y][x];\n          if (item != null && doomedTypes.contains(item.type)) {\n            _grid[y][x] = null;\n            _score += 5;\n            changed = true;\n          }\n        }\n      }\n    });\n\n    if (changed) {\n      await Future.delayed(const Duration(milliseconds: 200));\n      await _applyGravity();\n      await _resolveMatches();\n    }\n  }\n\n  void _startTimer() {\n    _gameTimer?.cancel();\n    _secondsRemaining = 180;\n    _gameTimer = Timer.periodic(const Duration(seconds: 1), (timer) {\n      if (!mounted) return;\n      setState(() {\n        if (_secondsRemaining > 0) {\n          _secondsRemaining--;\n        } else {\n          _isGameOver = true;\n          _gameTimer?.cancel();\n        }\n      });\n    });\n  }\n\n  void _initGrid({bool resetScore = true}) {\n    final rng = Random();\n    _grid = List.generate(_rows, (_) => List<Pill?>.filled(_cols, null));\n\n    for (int y = 0; y < _rows; y++) {\n      for (int x = 0; x < _cols; x++) {\n        LemonItemType proposedType;\n        do {\n          proposedType = _itemTypes[rng.nextInt(_itemTypes.length)];\n        } while (!_isMatchSafe(_grid, x, y, proposedType, isTopDown: true));\n\n        _grid[y][x] = Pill(proposedType);\n      }\n    }\n\n    setState(() {\n      if (resetScore) _score = 0;\n      _isWon = false;\n      _isGameOver = false;\n      _isProcessing = false;\n      _selectedPoint = null;\n    });\n\n    _startTimer();\n  }\n\n  Future<void> _shuffleGrid() async {\n    if (_isProcessing || _isWon || _isGameOver) return;\n\n    setState(() {\n      _isProcessing = true;\n    });\n\n    final List<Pill> availableItems = [];\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) availableItems.add(item);\n      }\n    }\n    availableItems.shuffle();\n\n    final List<List<Pill?>> newGrid = List.generate(\n      _rows,\n      (_) => List<Pill?>.filled(_cols, null),\n    );\n\n    int itemIndex = 0;\n\n    for (int y = _rows - 1; y >= 0; y--) {\n      for (int x = 0; x < _cols; x++) {\n        if (itemIndex >= availableItems.length) break;\n\n        int foundIndex = -1;\n\n        for (int k = itemIndex; k < availableItems.length; k++) {\n          if (_isMatchSafe(\n            newGrid,\n            x,\n            y,\n            availableItems[k].type,\n            isTopDown: false,\n          )) {\n            foundIndex = k;\n            break;\n          }\n        }\n\n        if (foundIndex != -1) {\n          final temp = availableItems[itemIndex];\n          availableItems[itemIndex] = availableItems[foundIndex];\n          availableItems[foundIndex] = temp;\n        }\n\n        newGrid[y][x] = availableItems[itemIndex];\n        itemIndex++;\n      }\n    }\n\n    setState(() {\n      _grid = newGrid;\n      _selectedPoint = null;\n    });\n\n    await Future.delayed(const Duration(milliseconds: 500));\n    await _resolveMatches();\n\n    if (mounted) {\n      setState(() {\n        _isProcessing = false;\n      });\n    }\n  }\n\n  bool _isMatchSafe(\n    List<List<Pill?>> tempGrid,\n    int x,\n    int y,\n    LemonItemType type, {\n    required bool isTopDown,\n  }) {\n    if (x >= 2) {\n      if (tempGrid[y][x - 1]?.type == type &&\n          tempGrid[y][x - 2]?.type == type) {\n        return false;\n      }\n    }\n\n    if (isTopDown) {\n      if (y >= 2) {\n        if (tempGrid[y - 1][x]?.type == type &&\n            tempGrid[y - 2][x]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x >= 2 && y >= 2) {\n        if (tempGrid[y - 1][x - 1]?.type == type &&\n            tempGrid[y - 2][x - 2]?.type == type) {\n          return false;\n        }\n      }\n      if (x <= _cols - 3 && y >= 2) {\n        if (tempGrid[y - 1][x + 1]?.type == type &&\n            tempGrid[y - 2][x + 2]?.type == type) {\n          return false;\n        }\n      }\n    } else {\n      if (y <= _rows - 3) {\n        if (tempGrid[y + 1][x]?.type == type &&\n            tempGrid[y + 2][x]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x >= 2 && y <= _rows - 3) {\n        if (tempGrid[y + 1][x - 1]?.type == type &&\n            tempGrid[y + 2][x - 2]?.type == type) {\n          return false;\n        }\n      }\n\n      if (x <= _cols - 3 && y <= _rows - 3) {\n        if (tempGrid[y + 1][x + 1]?.type == type &&\n            tempGrid[y + 2][x + 2]?.type == type) {\n          return false;\n        }\n      }\n    }\n\n    return true;\n  }\n\n  void _handleTap(int x, int y) {\n    if (_isProcessing || _isWon || _isGameOver || _grid[y][x] == null) return;\n\n    setState(() {\n      if (_selectedPoint == null) {\n        _selectedPoint = Point(x, y);\n      } else if (_selectedPoint!.x == x && _selectedPoint!.y == y) {\n        _selectedPoint = null;\n      } else {\n        final dx = (x - _selectedPoint!.x).abs();\n        final dy = (y - _selectedPoint!.y).abs();\n\n        final isNeighbor = dx <= 1 && dy <= 1 && !(dx == 0 && dy == 0);\n\n        if (isNeighbor) {\n          _attemptSwap(_selectedPoint!, Point(x, y));\n          _selectedPoint = null;\n        } else {\n          _selectedPoint = Point(x, y);\n        }\n      }\n    });\n  }\n\n  Future<void> _attemptSwap(Point<int> p1, Point<int> p2) async {\n    setState(() {\n      _isProcessing = true;\n      final temp = _grid[p1.y][p1.x];\n      _grid[p1.y][p1.x] = _grid[p2.y][p2.x];\n      _grid[p2.y][p2.x] = temp;\n    });\n\n    await Future.delayed(const Duration(milliseconds: 300));\n\n    final bool hasMatch = await _resolveMatches();\n\n    if (!hasMatch) {\n      if (mounted) {\n        setState(() {\n          final temp = _grid[p1.y][p1.x];\n          _grid[p1.y][p1.x] = _grid[p2.y][p2.x];\n          _grid[p2.y][p2.x] = temp;\n          _isProcessing = false;\n        });\n      }\n    }\n  }\n\n  Future<bool> _resolveMatches({bool initial = false}) async {\n    final Set<Point<int>> matchedPoints = {};\n\n    LemonItemType? getType(int x, int y) => _grid[y][x]?.type;\n\n    for (int y = 0; y < _rows; y++) {\n      for (int x = 0; x < _cols - 2; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x + 1, y) == t && getType(x + 2, y) == t) {\n          matchedPoints.addAll([Point(x, y), Point(x + 1, y), Point(x + 2, y)]);\n          int k = x + 3;\n          while (k < _cols && getType(k, y) == t) {\n            matchedPoints.add(Point(k, y));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int x = 0; x < _cols; x++) {\n      for (int y = 0; y < _rows - 2; y++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x, y + 1) == t && getType(x, y + 2) == t) {\n          matchedPoints.addAll([Point(x, y), Point(x, y + 1), Point(x, y + 2)]);\n          int k = y + 3;\n          while (k < _rows && getType(x, k) == t) {\n            matchedPoints.add(Point(x, k));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int y = 0; y < _rows - 2; y++) {\n      for (int x = 0; x < _cols - 2; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x + 1, y + 1) == t && getType(x + 2, y + 2) == t) {\n          matchedPoints.addAll([\n            Point(x, y),\n            Point(x + 1, y + 1),\n            Point(x + 2, y + 2),\n          ]);\n          int k = 3;\n          while (y + k < _rows &&\n              x + k < _cols &&\n              getType(x + k, y + k) == t) {\n            matchedPoints.add(Point(x + k, y + k));\n            k++;\n          }\n        }\n      }\n    }\n\n    for (int y = 0; y < _rows - 2; y++) {\n      for (int x = 2; x < _cols; x++) {\n        final t = getType(x, y);\n        if (t == null) continue;\n        if (getType(x - 1, y + 1) == t && getType(x - 2, y + 2) == t) {\n          matchedPoints.addAll([\n            Point(x, y),\n            Point(x - 1, y + 1),\n            Point(x - 2, y + 2),\n          ]);\n          int k = 3;\n          while (y + k < _rows && x - k >= 0 && getType(x - k, y + k) == t) {\n            matchedPoints.add(Point(x - k, y + k));\n            k++;\n          }\n        }\n      }\n    }\n\n    if (matchedPoints.isNotEmpty) {\n      if (!initial) {\n        if (mounted) {\n          setState(() {\n            for (final p in matchedPoints) {\n              _grid[p.y][p.x] = null;\n            }\n            _score += matchedPoints.length * 10;\n          });\n        }\n        await Future.delayed(const Duration(milliseconds: 300));\n      } else {\n        for (final p in matchedPoints) {\n          _grid[p.y][p.x] = null;\n        }\n      }\n\n      await _applyGravity();\n      await _resolveMatches(initial: initial);\n      return true;\n    }\n\n    if (!initial) {\n      await _cleanupStragglers();\n      _checkWinCondition();\n    }\n\n    if (!initial && mounted) {\n      setState(() {\n        _isProcessing = false;\n      });\n    }\n    return false;\n  }\n\n  void _checkWinCondition() {\n    bool isEmpty = true;\n    for (final row in _grid) {\n      for (final item in row) {\n        if (item != null) {\n          isEmpty = false;\n          break;\n        }\n      }\n    }\n    if (isEmpty && !_isWon) {\n      setState(() {\n        _isWon = true;\n        _gameTimer?.cancel();\n      });\n    }\n  }\n\n  Future<void> _applyGravity() async {\n    bool moved = false;\n    for (int x = 0; x < _cols; x++) {\n      int writeIdx = _rows - 1;\n      for (int readIdx = _rows - 1; readIdx >= 0; readIdx--) {\n        if (_grid[readIdx][x] != null) {\n          if (writeIdx != readIdx) {\n            _grid[writeIdx][x] = _grid[readIdx][x];\n            _grid[readIdx][x] = null;\n            moved = true;\n          }\n          writeIdx--;\n        }\n      }\n    }\n    if (moved && mounted) {\n      setState(() {});\n      await Future.delayed(const Duration(milliseconds: 300));\n    }\n  }\n\n  String get _timerString {\n    final mins = (_secondsRemaining ~/ 60).toString().padLeft(2, '0');\n    final secs = (_secondsRemaining % 60).toString().padLeft(2, '0');\n    return '\$mins:\$secs';\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      backgroundColor: const Color(0xFF0B1021),\n      appBar: AppBar(\n        backgroundColor: const Color(0xFF070B17),\n        elevation: 0,\n        leading: IconButton(\n          icon: const Icon(Icons.arrow_back, color: kAccentColor),\n          onPressed: () => Navigator.of(context).pop(),\n        ),\n        title: Text(\n          _isWon\n              ? 'NO MORE MELANCHOLY'\n              : (_isGameOver ? 'TIMEOUT' : _timerString),\n          style: TextStyle(\n            fontFamily: 'JetBrainsMono',\n            color: _isWon\n                ? const Color(0xFFFACC15)\n                : (_isGameOver ? Colors.red : kAccentColor),\n            fontSize: 18,\n            fontWeight: FontWeight.bold,\n          ),\n        ),\n        actions: [\n          Center(\n            child: Padding(\n              padding: const EdgeInsets.only(right: 16.0),\n              child: Container(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 10,\n                  vertical: 5,\n                ),\n                decoration: BoxDecoration(\n                  color: Colors.white.withValues(alpha: 0.08),\n                  borderRadius: BorderRadius.circular(8),\n                  border: Border.all(\n                    color: const Color(0xFFFACC15).withValues(alpha: 0.6),\n                  ),\n                ),\n                child: Text(\n                  'SCORE: \$_score',\n                  style: const TextStyle(\n                    fontFamily: 'JetBrainsMono',\n                    color: Colors.white,\n                    fontWeight: FontWeight.bold,\n                    fontSize: 13,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n      floatingActionButton: (!_isWon && !_isGameOver)\n          ? FloatingActionButton(\n              tooltip: 'Shuffle Board',\n              onPressed: _shuffleGrid,\n              backgroundColor: const Color(0xFFFACC15),\n              child: const Icon(Icons.shuffle, color: Colors.black),\n            )\n          : null,\n      body: Container(\n        decoration: const BoxDecoration(\n          gradient: RadialGradient(\n            center: Alignment(0.0, -0.3),\n            radius: 1.2,\n            colors: [\n              Color(0xFF1E1B4B),\n              Color(0xFF0F172A),\n              Color(0xFF060913),\n            ],\n          ),\n        ),\n        child: Stack(\n          children: [\n            if (_isWon) _buildWinScreen(),\n            if (_isGameOver && !_isWon) _buildLoseScreen(),\n            if (!_isWon && !_isGameOver) _buildGameLayout(),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildWinScreen() {\n    return Center(\n      child: Container(\n        margin: const EdgeInsets.all(24),\n        padding: const EdgeInsets.all(28),\n        decoration: BoxDecoration(\n          color: const Color(0xFF0F172A).withValues(alpha: 0.92),\n          borderRadius: BorderRadius.circular(18),\n          border: Border.all(color: const Color(0xFFFACC15), width: 3),\n          boxShadow: [\n            BoxShadow(\n              color: const Color(0xFFFACC15).withValues(alpha: 0.25),\n              blurRadius: 20,\n            ),\n          ],\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            const SizedBox(\n              width: 90,\n              height: 90,\n              child: CustomPaint(\n                painter: _LemonItemPainter(type: LemonItemType.lemon),\n              ),\n            ),\n            const SizedBox(height: 18),\n            const Text(\n              \"LIFE'S LEMONS CLEARED!\",\n              textAlign: TextAlign.center,\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                color: Color(0xFFFACC15),\n                fontWeight: FontWeight.bold,\n                fontSize: 22,\n              ),\n            ),\n            const SizedBox(height: 28),\n            ElevatedButton(\n              style: ElevatedButton.styleFrom(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 32,\n                  vertical: 16,\n                ),\n                backgroundColor: const Color(0xFFFACC15),\n                foregroundColor: Colors.black,\n              ),\n              onPressed: () => _initGrid(resetScore: false),\n              child: const Text(\n                'squeeze another batch',\n                style: TextStyle(\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 16,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildLoseScreen() {\n    return Center(\n      child: Container(\n        margin: const EdgeInsets.all(24),\n        padding: const EdgeInsets.all(28),\n        decoration: BoxDecoration(\n          color: const Color(0xFF0F172A).withValues(alpha: 0.92),\n          borderRadius: BorderRadius.circular(18),\n          border: Border.all(color: Colors.redAccent, width: 3),\n        ),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            const Icon(Icons.error_outline, color: Colors.redAccent, size: 76),\n            const SizedBox(height: 20),\n            const Text(\n              'CONNECTION TIMED OUT',\n              textAlign: TextAlign.center,\n              style: TextStyle(\n                fontFamily: 'JetBrainsMono',\n                color: Colors.redAccent,\n                fontWeight: FontWeight.bold,\n                fontSize: 22,\n              ),\n            ),\n            const SizedBox(height: 28),\n            ElevatedButton(\n              style: ElevatedButton.styleFrom(\n                padding: const EdgeInsets.symmetric(\n                  horizontal: 32,\n                  vertical: 16,\n                ),\n                backgroundColor: const Color(0xFFFACC15),\n                foregroundColor: Colors.black,\n              ),\n              onPressed: () => _initGrid(resetScore: true),\n              child: const Text(\n                'retry',\n                style: TextStyle(\n                  fontFamily: 'JetBrainsMono',\n                  fontWeight: FontWeight.bold,\n                  fontSize: 16,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildGameLayout() {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        final double maxWidth = constraints.maxWidth - 20;\n        final double maxHeight = constraints.maxHeight - 20;\n\n        double cellSize = maxWidth / _cols;\n        if (cellSize * _rows > maxHeight) {\n          cellSize = maxHeight / _rows;\n        }\n\n        final double boardWidth = cellSize * _cols;\n        final double boardHeight = cellSize * _rows;\n        final double xOffset = (constraints.maxWidth - boardWidth) / 2;\n        final double yOffset = (constraints.maxHeight - boardHeight) / 2;\n\n        final List<Widget> gridWidgets = [\n          // Cartoon Board Frame\n          Positioned(\n            left: xOffset - 6,\n            top: yOffset - 6,\n            width: boardWidth + 12,\n            height: boardHeight + 12,\n            child: Container(\n              decoration: BoxDecoration(\n                color: const Color(0xFF090D1A).withValues(alpha: 0.85),\n                borderRadius: BorderRadius.circular(16),\n                border: Border.all(\n                  color: const Color(0xFF334155),\n                  width: 3,\n                ),\n                boxShadow: [\n                  BoxShadow(\n                    color: Colors.black.withValues(alpha: 0.6),\n                    blurRadius: 16,\n                    offset: const Offset(0, 6),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        ];\n\n        for (int y = 0; y < _rows; y++) {\n          for (int x = 0; x < _cols; x++) {\n            gridWidgets.add(\n              Positioned(\n                left: xOffset + (x * cellSize),\n                top: yOffset + (y * cellSize),\n                width: cellSize,\n                height: cellSize,\n                child: Container(\n                  margin: const EdgeInsets.all(2.5),\n                  decoration: BoxDecoration(\n                    color: const Color(0xFF1E293B).withValues(alpha: 0.45),\n                    border: Border.all(color: Colors.white12, width: 1.2),\n                    borderRadius: BorderRadius.circular(12),\n                  ),\n                  child: GestureDetector(\n                    behavior: HitTestBehavior.translucent,\n                    onTap: () => _handleTap(x, y),\n                  ),\n                ),\n              ),\n            );\n          }\n        }\n\n        for (int y = 0; y < _rows; y++) {\n          for (int x = 0; x < _cols; x++) {\n            final item = _grid[y][x];\n            if (item == null) continue;\n\n            gridWidgets.add(\n              AnimatedPositioned(\n                key: Key(item.id),\n                duration: const Duration(milliseconds: 300),\n                curve: Curves.easeInOutBack,\n                left: xOffset + (x * cellSize),\n                top: yOffset + (y * cellSize),\n                width: cellSize,\n                height: cellSize,\n                child: IgnorePointer(\n                  child: _buildCartoonItemCell(x, y, cellSize, item),\n                ),\n              ),\n            );\n          }\n        }\n\n        return Stack(children: gridWidgets);\n      },\n    );\n  }\n\n  Widget _buildCartoonItemCell(int x, int y, double size, Pill item) {\n    final bool isSelected =\n        _selectedPoint != null &&\n        _selectedPoint!.x == x &&\n        _selectedPoint!.y == y;\n    final Color baseColor = item.color;\n\n    return Center(\n      child: AnimatedScale(\n        scale: isSelected ? 1.08 : 1.0,\n        duration: const Duration(milliseconds: 140),\n        child: SizedBox(\n          width: size * 0.90,\n          height: size * 0.90,\n          child: Container(\n            decoration: BoxDecoration(\n              gradient: RadialGradient(\n                center: const Alignment(-0.3, -0.35),\n                radius: 1.0,\n                colors: [\n                  Color.lerp(baseColor, Colors.white, 0.32)!,\n                  baseColor.withValues(alpha: 0.85),\n                  Color.lerp(baseColor, Colors.black, 0.45)!,\n                ],\n              ),\n              borderRadius: BorderRadius.circular(size * 0.24),\n              border: Border.all(\n                color: isSelected ? Colors.white : const Color(0xFF0F172A),\n                width: isSelected ? 3.2 : 2.2,\n              ),\n              boxShadow: [\n                if (isSelected)\n                  BoxShadow(\n                    color: baseColor.withValues(alpha: 0.85),\n                    blurRadius: 14,\n                    spreadRadius: 2,\n                  ),\n                BoxShadow(\n                  color: Colors.black.withValues(alpha: 0.45),\n                  offset: const Offset(0, 3),\n                  blurRadius: 4,\n                ),\n              ],\n            ),\n            child: Padding(\n              padding: EdgeInsets.all(size * 0.11),\n              child: CustomPaint(\n                painter: _LemonItemPainter(type: item.type),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _LemonItemPainter extends CustomPainter {\n  final LemonItemType type;\n\n  const _LemonItemPainter({required this.type});\n\n  @override\n  void paint(Canvas canvas, Size size) {\n    final Offset c = size.center(Offset.zero);\n    final double r = min(size.width, size.height) * 0.46;\n\n    final Paint outline = Paint()\n      ..color = const Color(0xFF0F172A)\n      ..style = PaintingStyle.stroke\n      ..strokeWidth = (r * 0.11).clamp(1.6, 3.0)\n      ..strokeJoin = StrokeJoin.round\n      ..strokeCap = StrokeCap.round;\n\n    switch (type) {\n      case LemonItemType.lemon:\n        // \"No more melancholy, only life's lemons\"\n        // Detailed cartoon lemon with tips, green leaf, and glossy shine\n        canvas.save();\n        canvas.translate(c.dx, c.dy);\n        canvas.rotate(-0.35);\n\n        final Path lemonBody = Path()\n          ..moveTo(-r * 1.05, 0)\n          ..quadraticBezierTo(-r * 0.75, -r * 0.78, 0, -r * 0.72)\n          ..quadraticBezierTo(r * 0.75, -r * 0.78, r * 1.05, 0)\n          ..quadraticBezierTo(r * 0.75, r * 0.78, 0, r * 0.72)\n          ..quadraticBezierTo(-r * 0.75, r * 0.78, -r * 1.05, 0)\n          ..close();\n\n        canvas.drawPath(\n          lemonBody,\n          Paint()..color = const Color(0xFFFDE047),\n        );\n        // Bottom shading arc\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(0, r * 0.1),\n            width: r * 1.6,\n            height: r * 1.0,\n          ),\n          0.1,\n          pi - 0.2,\n          false,\n          Paint()..color = const Color(0xFFEAB308),\n        );\n        canvas.drawPath(lemonBody, outline);\n\n        // Specular highlight\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: Offset(-r * 0.15, -r * 0.22),\n            width: r * 1.1,\n            height: r * 0.5,\n          ),\n          pi + 0.3,\n          1.4,\n          false,\n          Paint()\n            ..color = Colors.white.withValues(alpha: 0.75)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.12\n            ..strokeCap = StrokeCap.round,\n        );\n\n        // Green citrus leaf on top\n        final Path leaf = Path()\n          ..moveTo(-r * 0.2, -r * 0.68)\n          ..quadraticBezierTo(-r * 0.05, -r * 1.25, r * 0.55, -r * 1.05)\n          ..quadraticBezierTo(r * 0.25, -r * 0.62, -r * 0.2, -r * 0.68)\n          ..close();\n        canvas.drawPath(leaf, Paint()..color = const Color(0xFF22C55E));\n        canvas.drawPath(leaf, outline);\n        canvas.restore();\n        break;\n\n      case LemonItemType.crosstopPill:\n        // \"[crosstops] Pill pop in peace\"\n        // Cartoon two-tone capsule + white scored crosstop tablet\n        canvas.save();\n        canvas.translate(c.dx - r * 0.18, c.dy - r * 0.12);\n        canvas.rotate(-0.55);\n        final RRect topHalf = RRect.fromRectAndCorners(\n          Rect.fromLTWH(-r * 0.42, -r * 0.78, r * 0.84, r * 0.78),\n          topLeft: Radius.circular(r * 0.42),\n          topRight: Radius.circular(r * 0.42),\n        );\n        final RRect bottomHalf = RRect.fromRectAndCorners(\n          Rect.fromLTWH(-r * 0.42, 0, r * 0.84, r * 0.78),\n          bottomLeft: Radius.circular(r * 0.42),\n          bottomRight: Radius.circular(r * 0.42),\n        );\n        canvas.drawRRect(topHalf, Paint()..color = const Color(0xFFEF4444));\n        canvas.drawRRect(bottomHalf, Paint()..color = Colors.white);\n        canvas.drawRRect(\n          RRect.fromRectAndRadius(\n            Rect.fromCenter(\n              center: Offset.zero,\n              width: r * 0.84,\n              height: r * 1.56,\n            ),\n            Radius.circular(r * 0.42),\n          ),\n          outline,\n        );\n        canvas.drawLine(\n          Offset(-r * 0.42, 0),\n          Offset(r * 0.42, 0),\n          outline,\n        );\n        canvas.restore();\n\n        // Foreground crosstop tablet with '+' score lines\n        final Offset tabCenter = c + Offset(r * 0.32, r * 0.28);\n        canvas.drawCircle(\n          tabCenter,\n          r * 0.52,\n          Paint()..color = const Color(0xFFF8FAFC),\n        );\n        canvas.drawCircle(tabCenter, r * 0.52, outline);\n        canvas.drawLine(\n          tabCenter + Offset(-r * 0.32, 0),\n          tabCenter + Offset(r * 0.32, 0),\n          outline,\n        );\n        canvas.drawLine(\n          tabCenter + Offset(0, -r * 0.32),\n          tabCenter + Offset(0, r * 0.32),\n          outline,\n        );\n        break;\n\n      case LemonItemType.elixirPotion:\n        // \"[elixir] A violent, greedy alchemist. Amethyst, channeling\"\n        // Bubbling amethyst potion flask with cork stopper\n        final Path cork = Path()\n          ..moveTo(c.dx - r * 0.22, c.dy - r * 0.78)\n          ..lineTo(c.dx - r * 0.28, c.dy - r * 1.05)\n          ..lineTo(c.dx + r * 0.28, c.dy - r * 1.05)\n          ..lineTo(c.dx + r * 0.22, c.dy - r * 0.78)\n          ..close();\n        canvas.drawPath(cork, Paint()..color = const Color(0xFFB45309));\n        canvas.drawPath(cork, outline);\n\n        // Glass neck\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: c + Offset(0, -r * 0.62),\n            width: r * 0.46,\n            height: r * 0.36,\n          ),\n          Paint()..color = const Color(0xFFE0E7FF),\n        );\n        canvas.drawRect(\n          Rect.fromCenter(\n            center: c + Offset(0, -r * 0.62),\n            width: r * 0.46,\n            height: r * 0.36,\n          ),\n          outline,\n        );\n\n        // Bulbous flask body\n        final Offset bulbCenter = c + Offset(0, r * 0.16);\n        canvas.drawCircle(\n          bulbCenter,\n          r * 0.74,\n          Paint()..color = const Color(0xFFDDD6FE),\n        );\n        // Glowing purple elixir liquid inside\n        canvas.drawArc(\n          Rect.fromCircle(center: bulbCenter, radius: r * 0.65),\n          -0.2,\n          pi + 0.4,\n          true,\n          Paint()..color = const Color(0xFF9333EA),\n        );\n        // Magic bubbles\n        canvas.drawCircle(\n          bulbCenter + Offset(-r * 0.22, r * 0.12),\n          r * 0.12,\n          Paint()..color = const Color(0xFFF0ABFC),\n        );\n        canvas.drawCircle(\n          bulbCenter + Offset(r * 0.18, -r * 0.08),\n          r * 0.09,\n          Paint()..color = Colors.white,\n        );\n        canvas.drawCircle(bulbCenter, r * 0.74, outline);\n        break;\n\n      case LemonItemType.blueCandle:\n        // \"Blue candle wax drips onto bolded yellow letters\" / \"Mirtazipine and candlewax\"\n        final RRect candleBody = RRect.fromRectAndRadius(\n          Rect.fromCenter(\n            center: c + Offset(0, r * 0.24),\n            width: r * 0.92,\n            height: r * 1.18,\n          ),\n          Radius.circular(r * 0.16),\n        );\n        canvas.drawRRect(\n          candleBody,\n          Paint()..color = const Color(0xFF0284C7),\n        );\n        canvas.drawRRect(candleBody, outline);\n\n        // Dripping blue wax down the candle front\n        final Path waxDrips = Path()\n          ..moveTo(c.dx - r * 0.46, c.dy - r * 0.32)\n          ..quadraticBezierTo(\n            c.dx - r * 0.25,\n            c.dy + r * 0.22,\n            c.dx - r * 0.12,\n            c.dy - r * 0.15,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.08,\n            c.dy + r * 0.38,\n            c.dx + r * 0.22,\n            c.dy - r * 0.12,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.36,\n            c.dy + r * 0.12,\n            c.dx + r * 0.46,\n            c.dy - r * 0.32,\n          )\n          ..close();\n        canvas.drawPath(waxDrips, Paint()..color = const Color(0xFF7DD3FC));\n        canvas.drawPath(waxDrips, outline);\n\n        // Wick & Butane/Candle Flame\n        canvas.drawLine(\n          c + Offset(0, -r * 0.35),\n          c + Offset(0, -r * 0.52),\n          outline,\n        );\n        final Path outerFlame = Path()\n          ..moveTo(c.dx, c.dy - r * 1.08)\n          ..quadraticBezierTo(\n            c.dx + r * 0.38,\n            c.dy - r * 0.65,\n            c.dx,\n            c.dy - r * 0.48,\n          )\n          ..quadraticBezierTo(\n            c.dx - r * 0.38,\n            c.dy - r * 0.65,\n            c.dx,\n            c.dy - r * 1.08,\n          )\n          ..close();\n        canvas.drawPath(outerFlame, Paint()..color = const Color(0xFFF97316));\n        canvas.drawPath(outerFlame, outline);\n        canvas.drawCircle(\n          c + Offset(0, -r * 0.68),\n          r * 0.14,\n          Paint()..color = const Color(0xFFFEF08A),\n        );\n        break;\n\n      case LemonItemType.coffeeCup:\n        // \"10th cup of Colombian\" / \"drinking outta cups\"\n        // Cup handle\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: c + Offset(r * 0.52, r * 0.12),\n            width: r * 0.62,\n            height: r * 0.68,\n          ),\n          -pi / 2,\n          pi,\n          false,\n          Paint()\n            ..color = Colors.white\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.18,\n        );\n        canvas.drawArc(\n          Rect.fromCenter(\n            center: c + Offset(r * 0.52, r * 0.12),\n            width: r * 0.62,\n            height: r * 0.68,\n          ),\n          -pi / 2,\n          pi,\n          false,\n          outline,\n        );\n\n        // Mug body\n        final RRect mug = RRect.fromRectAndCorners(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, r * 0.16),\n            width: r * 1.15,\n            height: r * 1.08,\n          ),\n          bottomLeft: Radius.circular(r * 0.45),\n          bottomRight: Radius.circular(r * 0.45),\n          topLeft: Radius.circular(r * 0.1),\n          topRight: Radius.circular(r * 0.1),\n        );\n        canvas.drawRRect(mug, Paint()..color = const Color(0xFFFFFBEB));\n        canvas.drawRRect(mug, outline);\n\n        // Dark Colombian coffee surface\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, -r * 0.34),\n            width: r * 1.12,\n            height: r * 0.34,\n          ),\n          Paint()..color = const Color(0xFF451A03),\n        );\n        canvas.drawOval(\n          Rect.fromCenter(\n            center: c + Offset(-r * 0.08, -r * 0.34),\n            width: r * 1.12,\n            height: r * 0.34,\n          ),\n          outline,\n        );\n\n        // Rising steam curls\n        final Paint steamPaint = Paint()\n          ..color = Colors.white.withValues(alpha: 0.85)\n          ..style = PaintingStyle.stroke\n          ..strokeWidth = r * 0.1\n          ..strokeCap = StrokeCap.round;\n        for (int s = -1; s <= 1; s += 2) {\n          final double sx = c.dx - r * 0.08 + s * r * 0.24;\n          final Path steam = Path()\n            ..moveTo(sx, c.dy - r * 0.55)\n            ..quadraticBezierTo(\n              sx + s * r * 0.14,\n              c.dy - r * 0.78,\n              sx - s * r * 0.06,\n              c.dy - r * 0.98,\n            );\n          canvas.drawPath(steam, steamPaint);\n        }\n        break;\n\n      case LemonItemType.cherrySeven:\n        // \"The sevens are repetitive. Cherry on top of cherry-flavored sedatives.\"\n        final Offset leftCherry = c + Offset(-r * 0.42, r * 0.38);\n        final Offset rightCherry = c + Offset(r * 0.42, r * 0.38);\n        final Offset stemTop = c + Offset(0, -r * 0.88);\n\n        // Green arched cherry stems\n        final Path stems = Path()\n          ..moveTo(leftCherry.dx, leftCherry.dy - r * 0.2)\n          ..quadraticBezierTo(\n            c.dx - r * 0.35,\n            c.dy - r * 0.45,\n            stemTop.dx,\n            stemTop.dy,\n          )\n          ..quadraticBezierTo(\n            c.dx + r * 0.35,\n            c.dy - r * 0.45,\n            rightCherry.dx,\n            rightCherry.dy - r * 0.2,\n          );\n        canvas.drawPath(\n          stems,\n          Paint()\n            ..color = const Color(0xFF16A34A)\n            ..style = PaintingStyle.stroke\n            ..strokeWidth = r * 0.14\n            ..strokeCap = StrokeCap.round,\n        );\n\n        // Twin glossy cartoon cherries\n        for (final pos in [leftCherry, rightCherry]) {\n          canvas.drawCircle(\n            pos,\n            r * 0.44,\n            Paint()..color = const Color(0xFFE11D48),\n          );\n          canvas.drawCircle(pos, r * 0.44, outline);\n          canvas.drawCircle(\n            pos + Offset(-r * 0.14, -r * 0.14),\n            r * 0.12,\n            Paint()..color = Colors.white.withValues(alpha: 0.85),\n          );\n        }\n\n        // Golden Lucky '7' badge in the center\n        final TextPainter sevenTp = TextPainter(\n          text: TextSpan(\n            text: '7',\n            style: TextStyle(\n              color: const Color(0xFFFACC15),\n              fontFamily: 'JetBrainsMono',\n              fontWeight: FontWeight.w900,\n              fontSize: r * 1.05,\n              shadows: const [\n                Shadow(\n                  color: Color(0xFF0F172A),\n                  offset: Offset(1.5, 1.5),\n                  blurRadius: 1,\n                ),\n              ],\n            ),\n          ),\n          textDirection: TextDirection.ltr,\n        )..layout();\n        sevenTp.paint(\n          canvas,\n          c - Offset(sevenTp.width / 2, sevenTp.height * 0.72),\n        );\n        break;\n    }\n  }\n\n  @override\n  bool shouldRepaint(covariant _LemonItemPainter oldDelegate) =>\n      oldDelegate.type != type;\n}\n",
  "lib/global/helpers.dart": "import 'package:flutter/material.dart';\nimport 'package:url_launcher/url_launcher.dart';\n\nFuture<void> openUrl(String url) async {\n    final Uri uri = Uri.parse(url);\n    if (!await launchUrl(uri)) {\n      debugPrint('Could not launch \$url');\n    }\n  }\n\n",
  "lib/global/noop_url_strategy.dart": "void usePathUrlStrategy() {}\n",
  "lib/global/colors.dart": "import 'package:flutter/material.dart';\n\nconst Color kTerminalGreen = Colors.white;\nconst Color kTerminalDark = Color(0xFF0A1A0A);\nconst Color kBackgroundColor = Colors.black;\nconst Color kTextColor = Colors.white;\nconst Color kAccentColor = Color(0xFFB072FF);\n",
  "lib/widgets/selectable_highlight_view.dart": "import 'package:flutter/material.dart';\nimport 'package:highlight/highlight.dart' show highlight, Node;\n\nclass SelectableHighlightView extends StatelessWidget {\n  final String source;\n  final String? language;\n  final Map<String, TextStyle> theme;\n  final EdgeInsetsGeometry? padding;\n  final TextStyle? textStyle;\n\n  SelectableHighlightView(\n    String input, {\n    super.key,\n    this.language,\n    this.theme = const {},\n    this.padding,\n    this.textStyle,\n    int tabSize = 8,\n  }) : source = input.replaceAll('\\t', ' ' * tabSize);\n\n  List<TextSpan> _convert(List<Node> nodes) {\n    List<TextSpan> spans = [];\n    var currentSpans = spans;\n    List<List<TextSpan>> stack = [];\n\n    void _traverse(Node node) {\n      if (node.value != null) {\n        currentSpans.add(\n          node.className == null\n              ? TextSpan(text: node.value)\n              : TextSpan(text: node.value, style: theme[node.className!]),\n        );\n      } else if (node.children != null) {\n        List<TextSpan> tmp = [];\n        currentSpans.add(\n          TextSpan(children: tmp, style: theme[node.className!]),\n        );\n        stack.add(currentSpans);\n        currentSpans = tmp;\n\n        for (var n in node.children!) {\n          _traverse(n);\n          if (n == node.children!.last) {\n            currentSpans = stack.isEmpty ? spans : stack.removeLast();\n          }\n        }\n      }\n    }\n\n    for (var node in nodes) {\n      _traverse(node);\n    }\n\n    return spans;\n  }\n\n  static const _rootKey = 'root';\n  static const _defaultFontColor = Color(0xff000000);\n  static const _defaultBackgroundColor = Color(0xffffffff);\n  static const _defaultFontFamily = 'monospace';\n\n  @override\n  Widget build(BuildContext context) {\n    var style = TextStyle(\n      fontFamily: _defaultFontFamily,\n      color: theme[_rootKey]?.color ?? _defaultFontColor,\n    );\n    if (textStyle != null) {\n      style = style.merge(textStyle);\n    }\n\n    return Container(\n      color: theme[_rootKey]?.backgroundColor ?? _defaultBackgroundColor,\n      padding: padding,\n      child: Text.rich(\n        TextSpan(\n          style: style,\n          children: _convert(\n            highlight.parse(source, language: language).nodes!,\n          ),\n        ),\n        softWrap: false,\n      ),\n    );\n  }\n}\n",
  "lib/widgets/loading_waveform.dart": "import 'dart:math' as math;\nimport 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass WaveformLoader extends StatefulWidget {\n  final double height;\n  final double barWidth;\n  final Color? color;\n\n  const WaveformLoader({\n    super.key,\n    this.height = 50.0,\n    this.barWidth = 4.0,\n    this.color,\n  });\n\n  @override\n  State<WaveformLoader> createState() => _WaveformLoaderState();\n}\n\nclass _WaveformLoaderState extends State<WaveformLoader>\n    with SingleTickerProviderStateMixin {\n  late AnimationController _controller;\n\n  @override\n  void initState() {\n    super.initState();\n    _controller = AnimationController(\n      vsync: this,\n      duration: const Duration(milliseconds: 1200),\n    )..repeat();\n  }\n\n  @override\n  void dispose() {\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final color = Colors.white;\n\n    return SizedBox(\n      height: widget.height,\n      child: Row(\n        mainAxisSize: MainAxisSize.min,\n        mainAxisAlignment: MainAxisAlignment.center,\n        crossAxisAlignment: CrossAxisAlignment.center,\n        children: List.generate(5, (index) {\n          final double delayFactor = index * (1 / 12);\n\n          return AnimatedBuilder(\n            animation: _controller,\n            builder: (context, child) {\n              double t = (_controller.value - delayFactor) % 1.0;\n\n              double sinVal = math.sin(t * 2 * math.pi);\n\n              double normalized = (sinVal + 1) / 2;\n              double scale = 0.1 + (normalized * 0.9);\n\n              return Container(\n                width: widget.barWidth,\n                height: widget.height * scale,\n                margin: const EdgeInsets.symmetric(horizontal: 3.0),\n                decoration: BoxDecoration(\n                  color: color,\n                  borderRadius: BorderRadius.circular(99),\n                ),\n              );\n            },\n          );\n        }),\n      ),\n    );\n  }\n}\n",
  "lib/widgets/social_icons.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/global/helpers.dart';\nimport 'package:flutter/material.dart';\nimport 'package:font_awesome_flutter/font_awesome_flutter.dart';\n\nclass SocialIcon extends StatelessWidget {\n  final dynamic icon;\n  final String? url;\n  final double iconSize;\n  final VoidCallback? onPressed;\n  final String? tooltip;\n  final Color? color;\n  final Color? hoverColor;\n\n  const SocialIcon({\n    super.key,\n    required this.icon,\n    this.url,\n    this.iconSize = 18.0,\n    this.onPressed,\n    this.tooltip,\n    this.color,\n    this.hoverColor,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final effectiveHover = hoverColor ?? kAccentColor;\n    final Widget iconWidget = icon is FaIconData\n        ? FaIcon(\n            icon as FaIconData,\n            color: color ?? Colors.grey,\n            size: iconSize,\n          )\n        : Icon(\n            icon as IconData,\n            color: color ?? Colors.grey,\n            size: iconSize,\n          );\n\n    return IconButton(\n      tooltip: tooltip,\n      icon: iconWidget,\n      onPressed: onPressed ??\n          () {\n            if (url != null) openUrl(url!);\n          },\n      splashColor: effectiveHover.withValues(alpha: 0.3),\n      hoverColor: effectiveHover.withValues(alpha: 0.1),\n    );\n  }\n}\n",
  "lib/widgets/header.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:archbtw_sh/widgets/nav_link.dart';\nimport 'package:flutter/material.dart';\n\nclass Header extends StatelessWidget {\n  final int currentIndex;\n  final Function(int) onItemTapped;\n\n  const Header({\n    required this.currentIndex,\n    required this.onItemTapped,\n  });\n\n  static const double kTabletBreakpoint = 768.0;\n\n\n  @override\n  Widget build(BuildContext context) {\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        \n        final bool isDesktop = constraints.maxWidth >= kTabletBreakpoint;\n\n        final double titleFontSize = isDesktop ? 22 : 18;\n        final double navLinkFontSize = isDesktop ? 16 : 14;\n        \n        final EdgeInsets padding = isDesktop\n            ? const EdgeInsets.symmetric(horizontal: 48.0, vertical: 16.0)\n            : const EdgeInsets.symmetric(horizontal: 16.0, vertical: 16.0);\n\n        final headerContent = Row(\n          mainAxisAlignment: MainAxisAlignment.spaceBetween,\n          crossAxisAlignment: CrossAxisAlignment.center,\n          children: [\n            TextButton(\n              onPressed: () => onItemTapped(0),\n              style: TextButton.styleFrom(\n                splashFactory: NoSplash.splashFactory,\n                overlayColor: Colors.transparent,\n                padding: EdgeInsets.zero,\n                alignment: Alignment.centerLeft,\n              ),\n              child: Text(\n                '// archBTW.',\n                style: TextStyle(\n                  color: kTextColor,\n                  fontSize: titleFontSize,\n                  fontWeight: FontWeight.bold,\n                  letterSpacing: 1.5,\n                  fontFamily: 'JetBrainsMono',\n                ),\n              ),\n            ),\n            Row(\n              mainAxisAlignment: MainAxisAlignment.start,\n              children: [\n                NavLink(\n                  title: 'about',\n                  index: 1,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(1),\n                  fontSize: navLinkFontSize,\n                ),\n                NavLink(\n                  title: 'music',\n                  index: 2,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(2),\n                  fontSize: navLinkFontSize,\n                ),\n                NavLink(\n                  title: 'merch',\n                  index: 3,\n                  currentIndex: currentIndex,\n                  onTap: () => onItemTapped(3),\n                  fontSize: navLinkFontSize,\n                ),\n              ],\n            ),\n          ],\n        );\n        return Container(\n          color: kBackgroundColor,\n          child: Padding(\n            padding: padding,\n            child: headerContent,\n          ),\n        );\n      },\n    );\n  }\n}",
  "lib/widgets/nav_link.dart": "import 'package:archbtw_sh/global/colors.dart';\nimport 'package:flutter/material.dart';\n\nclass NavLink extends StatelessWidget {\n  final String title;\n  final int index;\n  final int currentIndex;\n  final VoidCallback onTap;\n  final double fontSize;\n\n  const NavLink({super.key, \n    required this.title,\n    required this.index,\n    required this.currentIndex,\n    required this.onTap,\n    this.fontSize = 14.0,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final bool isActive = index == currentIndex;\n\n    return TextButton(\n      onPressed: onTap,\n      style: TextButton.styleFrom(\n        splashFactory: NoSplash.splashFactory,\n        overlayColor: Colors.transparent,\n        foregroundColor: isActive ? kTextColor : Colors.grey,\n        \n        textStyle: TextStyle(\n          fontFamily: 'JetBrainsMono',\n          fontSize: fontSize,\n          fontWeight: isActive ? FontWeight.bold : FontWeight.normal,\n        ),\n      ),\n      child: Text(title),\n    );\n  }\n}",
};
